(window.GIM_TS=window.GIM_TS||{})["Bava Metzia.8"]={"from":192,"a":[["\u0003אמר רבא:\u0004 אמר לחבירו \u0003\"מנה לי בידך\", והלה,\u0004 הנתבע, \u0003אומר\u0004 לו: \u0003אין לך בידי אלא חמשים, והשאר\u0004 — \u0003איני יודע.\u0004 הרי הוא איפוא מודה במקצת הטענה (בחמישים) שחייב שבועה, ו\u0003מתוך שאינו יכול לישבע\u0004 (להשבע) על השאר, שהרי הוא עצמו מודה שאינו יודע דבר ביחס לזה — משלם הכל.","ומעירים: ולענין פירוש משנתנו בדרך זו \u0003משכחת לה רישא\u0004 \u0005[מוצא אתה אותה\u0006 אם תפרש \u0005תחילה]\u0006 \u0003בשתים\u0004 פרות \u0003וסיפא\u0004 \u0005[\u0006\u0005וסופה]\u0006 \u0003בשלש.\u0004","ומפרטים: \u0003רישא\u0004 \u0005[ראש]\u0006 המשנה מדבר \u0003בשתים,\u0004 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 בעל הבהמות: \u0003שתי פרות מסרתי לך, פלגיה דיומא\u0004 \u0005[חצי\u0006 \u0003היום]\u0004 \u0003בשאילה, ופלגיה דיומא\u0004 \u0005[וחצי היום]\u0006 \u0003בשכירות.\u0004 \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003חד יומא\u0004 \u0005[יום אחד]\u0006 \u0003בשאילה וחד יומא\u0004 \u0005[ויום אחד]\u0006 \u0003בשכירות, ומתו תרוייהו בעידן\u0004 \u0005[ומתו שתיהן בזמן]\u0006 \u0003שאילה.\u0004","\u0003ואמר ליה\u0004 \u0005[לו]\u0006 ה\u0003שואל: חדא\u0004 \u0005[אחת]\u0006 — \u0003אין, בעידן\u0004 \u0005[כן, בזמן]\u0006 \u0003שאילה מתה,\u0004 \u0003ואידך לא ידענא אי בעידן\u0004 \u0005[והאחרת איני יודע אם בזמן]\u0006 \u0003שאילה מתה ואי בעידן\u0004 \u0005[ואם בזמן]\u0006 \u0003שכירות מתה\u0004 ש\u0003מתוך שאינו יכול לישבע\u0004 (להשבע) על זו שאינו יודע — \u0003משלם\u0004 הכל.","\u0003וסיפא\u0004 \u0005[וסופה]\u0006 של המשנה מדובר \u0003בשלש\u0004 פרות, ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 בעל הפרות: \u0003שלש פרות נתתי לך, שתים בשאילה ואחת בשכירות, ומתו הני תרתי\u0004 \u0005[אלה השתים]\u0006 של ה\u0003שאילה,\u0004 \u0003ואמר ליה\u0004 \u0005[לו]\u0006 ה\u0003שואל: אין\u0004 \u0005[כן],\u0006 \u0003חדא\u0004 \u0005[אחת]\u0006 של ה\u0003שאילה מתה,\u0004 ו\u0003אידך לא ידענא אי\u0004 \u0005[והאחרת איני יודע\u0006 \u0003אם]\u0004 זו של ה\u0003שאילה מתה ודקיימא\u0004 \u0005[וזו שעומדת,\u0006 קיימת\u0005]\u0006 זו של ה\u0003שכירות היא,\u0004 \u0003אי\u0004 \u0005[אם זו]\u0006 של ה\u0003שכירות מתה והא דקיימא\u0004 \u0005[וזו שעומדת,\u0006 קיימת\u0005]\u0006 של \u0003שאילה היא,\u0004 \u0003ומתוך שאינו יכול לישבע\u0004 (להשבע) — \u0003משלם.\u0004","ומעירים: \u0003ול\u0004שיטת \u0003רמי בר חמא,\u0004 ש\u0003אמר: ארבעה שומרים\u0004 המנויים בתורה \u0003צריכין כפירה במקצת והודאה במקצת,\u0004 שאינם חייבים שבועה על טענה הפוטרת אותם, וכגון שומר חינם בטענת גניבה, ושומר שכר בטענת אונס, אלא אם כן היתה בטענתם הודאה במקצת הטענה וכפירה במקצת, לשיטתו \u0003משכחת לה\u0004 \u0005[מוצא אתה]\u0006 להסביר את משנתנו באופן שיש עסק שבועה ביניהם, \u0003רישא\u0004 \u0005[ראשה]\u0006 \u0003בשלש\u0004 פרות \u0003וסיפא\u0004 \u0005[וסופה]\u0006 \u0003בארבע.\u0004","ומפרטים: \u0003רישא\u0004 \u0005[ראשה]\u0006 \u0003בשלש\u0004 — ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 בעל הפרות: \u0003שלש פרות נתתי לך, פלגיה דיומא\u0004 \u0005[חצי היום]\u0006 \u0003בשאלה ופלגיה דיומא\u0004 \u0005[וחצי היום]\u0006 \u0003בשכירות,\u0004 \u0003אי נמי\u0004 \u0005[או גם כן]:\u0006 \u0003חד יומא\u0004 \u0005[יום אחד]\u0006 \u0003בשאלה וחד יומא\u0004 \u0005[ויום אחד]\u0006 \u0003בשכירות\u0004 ומתו \u0003שלש\u0004 הפרות \u0003כולהו בעידן\u0004 \u0005[כולן בזמן]\u0006 \u0003שאילה,\u0004","\u0003ואמר ליה\u0004 \u0005[לו]\u0006 \u0003ה\u0004\u0003שואל:\u0004 לענין פרה \u0003חדא\u0004 \u0005[אחת]\u0006 — \u0003לא היו דברים מעולם,\u0004 שלא שלש שאלתי כי אם שתים. \u0003וחדא\u0004 \u0005[ואחת]\u0006 — \u0003אין, בעידן\u0004 \u0005[כן, בזמן]\u0006 ה\u0003שאילה מתה,\u0004 \u0003ואידך\u0004 \u0005[והאחרת]\u0006 — \u0003לא ידענא אי בעידן\u0004 \u0005[איני יודע אם בזמן]\u0006 \u0003שאילה מתה ואי בעידן\u0004 \u0005[ואם בזמן]\u0006 \u0003שכירות מתה,\u0004 שחל עליו חיוב שבועה, שהרי הוא כופר במקצת (בפרה אחת) ומודה במקצת, ש\u0003מתוך שאינו יכול לישבע\u0004 (להשבע) על זו שאינו יודע — \u0003משלם.\u0004","\u0003סיפא\u0004 \u0005[בסופה\u0006 של המשנה\u0005]\u0006 מדובר \u0003בארבע\u0004 פרות, ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 בעל הפרות: \u0003ארבע פרות נתתי לך, שלש בשאלה, חדא\u0004 \u0005[אחת]\u0006 \u0003בשכירות, ומתו הנך\u0004 \u0005[אותן]\u0006 \u0003שלש\u0004 של \u0003שאלה\u0004 וחייב אתה להחזירן לי. \u0003ואמר ליה\u0004 \u0005[לו]\u0006"],["ה\u0003שואל:\u0004 לגבי פרה \u0003חדא\u0004 \u0005[אחת]\u0006 \u0003לא היו דברים מעולם,\u0004 שכן שאלתי ממך רק שלוש פרות. \u0003וחדא\u0004 \u0003אין\u0004 \u0005[ואחת, כן]\u0006 זו שהיתה של \u0003שאלה מתה,\u0004 \u0003ואידך לא ידענא אי\u0004 \u0005[והאחרת איני יודע אם זו]\u0006 של ה\u0003שכירות מתה ודקיימא\u0004 \u0005[וזו שעומדת,\u0006 קיימת\u0005]\u0006 של \u0003שאלה\u0004 היא, \u0003או\u0004 זו של \u0003שאלה מתה ודקיימא\u0004 \u0005[וזו שעומדת,\u0006 קיימת\u0005]\u0006 של \u0003שכירות,\u0004 ש\u0003מתוך שאינו יכול לישבע\u0004 (להשבע) — \u0003משלם.\u0004","שנינו במשנה: \u0003זה אומר שאולה\u0004 מתה, \u0003וזה אומר שכורה\u0004 מתה — \u0003ישבע השוכר ששכורה מתה.\u0004","שואלים: \u0003ואמאי\u0004 \u0005[מדוע]\u0006 ישבע? והרי אין כאן מודה במקצת כלל, שהרי \u0003מה שטענו\u0004 — \u0003לא הודה לו, ומה שהודה לו\u0004 — \u0003לא טענו! אמר עולא:\u0004 מדובר כאן שמחייבו להשבע \u0003על ידי גלגול.\u0004 כלומר, כיון שהתחייב כבר להשבע לו בענין אחד, יכול לתבוע שיכלול בשבועתו גם טענה זו שכרגיל אינו יכול לחייב שבועה עליה.","ש\u0003אמר ליה: אישתבע\u0004 \u0005[השבע]\u0006 \u0003לי איזו מיהת\u0004 \u0005[מכל מקום]\u0006 שזו שאתה טוען שהיתה שכורה אכן \u0003כדרכה מתה\u0004 ולא בפשיעה, \u0003ומיגו דמישתבע\u0004 \u0005[ומתוך שנשבע]\u0006 בהכרח ש\u0003כדרכה מתה\u0004 \u0003מישתבע נמי\u0004 \u0005[נשבע גם כן]\u0006 ש\u0003שכורה מתה\u0004 ולא אחרת.","שנינו במשנה שאם \u0003זה אומר: איני יודע, וזה אומר:\u0004 איני יודע — יחלוקו. ומעירים: \u0003הא מני\u0004 \u0005[הלכה זו\u0006 כשיטת \u0005מי היא]\u0006 — כשיטת \u0003סומכוס היא,\u0004 ש\u0003אמר: ממון המוטל בספק\u0004 שאין דרך לברר למי הוא — \u0003חולקין\u0004 בין הטוענים.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' אבא בר ממל:\u0004 אם לקח פרה אחת, קודם בשאילה, ואחר כך לפני שהחזירה שכרה מבעליה, \u0003שאלה בבעלים\u0004 ואחר כך \u0003שכרה שלא בבעלים מהו\u0004 הדין?","\u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 \u0003שאילה לחודה קיימא\u0004 \u0005[לעצמה עומדת]\u0006 \u0003ושכירות לחודה קיימא\u0004 \u0005[לעצמה עומדת]\u0006 ובכל אחת מהן יש לדון כבמקרה לעצמו, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003שכירות בשאלה מישך שייכי\u0004 \u0005[היא שייכת]\u0006 ונחשבת כהמשך לה \u0003דהא מיחייב\u0004 \u0005[שהרי הוא מתחייב]\u0006 \u0003בגניבה ואבידה\u0004 גם בשכירות כמו בשאילה?","ועל בסיס שאלה זו \u0003אם תמצא\u0004 \u0005[אם תוכל\u0006 ותחליט \u0005למצות]\u0006 את הדברים ו\u0003לומר\u0004 כי \u0003שכירה בשאלה מישך שייכי\u0004 \u0005[שייכת היא]\u0006 ונידונה כהמשך לה, מה יהא במקרה הפוך: \u0003שכרה בבעלים\u0004 ואחר כך \u0003שאלה שלא בבעלים, מהו\u0004 הדין?","האם נאמר כי \u0003שאלה בשכירות ודאי לא שייכא\u0004 \u0005[אינה שייכת],\u0006 שהרי שאילה חמורה הרבה מן השכירות. \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון דשייכא\u0004 \u0005[ששייכת]\u0006 \u0003במקצת\u0004 שכירות בבעלים הרי \u0003כמאן דשייכא\u0004 \u0005[כמי ששייכת]\u0006 \u0003בכולה דמי\u0004 \u0005[נחשבת]?\u0006","ושאלה נוספת: \u0003אם תמצא\u0004 \u0005[אם תוכל\u0006 ותחליט \u0005למצות]\u0006 את הדברים ו\u0003לומר\u0004 כי \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 \u0003כיון דשייכא\u0004 \u0005[ששייכת]\u0006 \u0003במקצת\u0004 הרי \u0003כמאן דשייכא\u0004 \u0005[כמי ששייכת]\u0006 \u0003בכולה דמי\u0004 \u0005[נחשבת],\u0006 יש מקום לשאלה הבאה: \u0003שאלה בבעלים ושכרה\u0004 לאחר מכן \u0003שלא בבעלים, וחזר ושאלה, מהו\u0004 הדין?","האם \u0003הדר אתיא\u0004 \u0005[חוזרת\u0006 ו\u0005באה]\u0006 \u0003לה\u0004 ה\u0003שאלה לדוכתה\u0004 \u0005[למקומה],\u0006 ונחשב כשאלה בבעלים, \u0003או דלמא אפסיקא\u0004 \u0005[הפסיקה]\u0006 \u0003לה\u0004 ה\u0003שכירות ביני וביני\u0004 \u0005[באמצע]\u0006 ואין שתי השאילות נחשבות כהמשך אחד?","וכן \u0003שכרה בבעלים, ו\u0004לאחר מכן \u0003שאלה, וחזר ושכרה,\u0004 \u0003מהו\u0004 הדין? \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 כי \u0003אתיא\u0004 \u0005באה\u0006 \u0003לה שכירות\u0004 וחזרה \u0003לדוכתה\u0004 \u0005[למקומה]\u0006 והוא כשכירות אחת, \u0003או דלמא אפסיקא\u0004 \u0005[שמא הפסיקה]\u0006 \u0003לה\u0004 ה\u0003שאלה\u0004 שהיתה \u0003ביני וביני\u0004 \u0005[באמצע]\u0006 והדברים אינם קשורים זה בזה?","לכל אחת מן השאלות הללו לא נמצאה תשובה ולכן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003השואל את הפרה\u0004 מחבירו \u0003ושלחה לו ביד בנו,\u0004 או \u0003ביד עבדו,\u0004 או \u0003ביד שלוחו, או\u0004 ששלחה לו \u0003ביד בנו,\u0004 או \u0003ביד עבדו,\u0004 או \u0003ביד שלוחו של\u0004 ה\u0003שואל, ומתה\u0004 הפרה בינתיים — \u0003פטור,\u0004 שלא התחילה השאילה מבחינה חוקית עד שתגיע הפרה לידי השואל.","\u0003אמר לו השואל: שלחה לי ביד בני,\u0004 או שאמר לו שלחה לי \u0003ביד עבדי,\u0004 או \u0003ביד שלוחי, או\u0004 שאמר לו שלחה לי \u0003ביד בנך,\u0004 או \u0003ביד עבדך,\u0004 או \u0003ביד שלוחך, או שאמר לו המשאיל\u0004 במפורש: \u0003הריני משלחה לך ביד בני,\u0004 או \u0003ביד עבדי,\u0004 או \u0003ביד שלוחי, או\u0004 שאמר לו במפורש הריני משלחה לך \u0003ביד בנך,\u0004 או \u0003ביד עבדך,\u0004 או \u0003ביד שלוחך, ואמר לו השואל: שלח, ושלחה ומתה\u0004 — במקרה זה \u0003חייב,\u0004 שהרי היתה כאן שאלה ממש בכל אותו הזמן.","\u0003וכן\u0004 הדין \u0003בשעה שמחזירה.\u0004 שאם לא החזירה במישרין למשאיל והיתה בידי אחר, אינה נחשבת כמוחזרת עד שתמסר לבעליה, או עד שיקבלו שני הצדדים על עצמם."],["על המשנה תוהים: נאמר שם שאם הסכים השואל, ושלח המשאיל \u0003ביד עבדו\u0004 — \u0003חייב,\u0004 ואולם הלא \u0003יד עבד כיד רבו\u0004 שעבד נחשב מבחינה משפטית כהמשך של אדוניו, והמצוי בידו, כאילו היה ביד האדון, ואם כן, כל עוד הפרה בידי העבד כאילו לא יצאה מרשות המשאיל כלל, ומדוע חייב השואל?","\u0003אמר שמואל:\u0004 מדובר כאן \u0003בעבד עברי, דלא קני ליה גופיה\u0004 \u0005[שאין גופו קנוי לו]\u0006 לאדון, שכן עבד עברי הריהו כפועל שכיר, שגופו אינו שייך לאדוניו, ומשום כך אין ידו כיד רבו. \u0003רב אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שמדובר כאן \u0003בעבד כנעני, נעשה כאומר ליה\u0004 \u0005[לו]\u0006 למשאיל: \u0003הכישה\u0004 (הכה אותה) \u0003במקל והיא תבא\u0004 מעצמה, שמרגע שיצאה מיד המשאיל עצמו הרי היא ברשות השואל, ואף כאן, כיון שהשואל הסכים לדבר, אין מציאותו של העבד מעלה או מורידה.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 מברייתא ששנו בה: \u0003השואל\u0004 את \u0003הפרה ושלחה לו ביד בנו,\u0004 או \u0003ביד שלוחו\u0004 — אם הסכים השואל לכך \u0003חייב,\u0004 ואם שלחה \u0003ביד עבדו\u0004 — \u0003פטור.\u0004","ומעתה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003שמואל\u0004 אפשר להסביר כי \u0003מתניתין\u0004 \u0005[משנתינו]\u0006 מדברת \u0003בעבד עברי,\u0004 ולכן המשלח ביד עבדו חייב, ואילו ה\u0003ברייתא\u0004 מדברת \u0003בעבד כנעני. אלא לרב קשיא\u0004 \u0005[קשה\u0006 הסתירה\u0005]!\u0006","\u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך לך:\u0004 \u0003לא תימא נעשה כאמר ליה\u0004 \u0005[אל תאמר\u0006 ותפרש את המשנה \u0005שנעשה כאומר לו],\u0006 \u0003אלא תימא\u0004 \u0005[אמור]\u0006 \u0003ב\u0004אופן ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 השואל למשאיל: \u0003הכישה במקל והיא תבא,\u0004 שאז ודאי אם שלח גם את העבד עם הפרה אין זה מוריד מאחריותו של השואל.","\u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 על מקרה כזה, מי שאמר לחבירו: \u0003השאילני פרת\u0004 \u0003ך, ואמר ליה\u0004 \u0005[לו]\u0006 חבירו: \u0003ביד מי? ואמר ליה\u0004 \u0005[לו]\u0006 השואל: אינני צריך שליח, אלא \u0003הכישה במקל ותבא\u0004 הפרה מעצמה. \u0003אמר רב נחמן אמר רבה בר אבוה אמר רב: כיון שיצאת\u0004 (יצאה) הפרה \u0003מרשות\u0004 ה\u0003משאיל ומתה\u0004 — \u0003חייב\u0004 השואל. שכן על ידי כך קיבל עליו אחריות לפרה מאותו רגע.","ומציעים: \u0003נימא מסייע ליה\u0004 \u0005[האם לומר שאפשר לסייע לו]\u0006 ממה ששנינו בברייתא, אמר אחד לחבירו: \u0003\"השאילני פרתך\". ואמר ליה\u0004 \u0005[לו]\u0006 \u0003ביד מי? ואמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכישה במקל והיא תבא. כיון שיצאת מרשות משאיל ומתה\u0004 — \u0003חייב.\u0004 והרי זו לכאורה ראיה גמורה.","\u0003אמר רב אשי: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עסוקים]\u0006 — במקרה מיוחד, \u0003כגון שהיתה חצרו של שואל\u0004 מצויה \u0003לפנים מחצרו של משאיל, דכי משלחה לה\u0004 \u0005[שכאשר הוא משלח אותה]\u0006 — \u0003ודאי להתם אזלא\u0004 \u0005[לשם\u0006 היא \u0005הולכת].\u0006","ושואלים: \u0003אי הכי, מאי למימרא\u0004 \u0005[אם כך, מה יש לומר],\u0006 שהרי במקרה זה ברור הדבר מעצמו ואין החכמים צריכים להודיענו דבר פשוט כל כך! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא לאופן \u0003דאיכא גזייתא\u0004 \u0005[שיש פינות\u0006 בחצר\u0005].\u0006 \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003לא סמכא דעתיה דלמא קיימא התם\u0004 \u0005[אין דעתו סומכת\u0006 על ההכאה במקל \u0005שמא תעמוד שם]\u0006 בפינה \u0003ולא אתיא אזלא להדיא\u0004 \u0005[תבוא\u0006 ו\u0005תלך במישרים],\u0006 על כן \u0003קא משמע לן דסמכא דעתיה\u0004 \u0005[השמיע לנו ש\u0006בכל זאת \u0005סומכת דעתו],\u0006 וקיבל על עצמו את האחריות לפרה.","\u0003אמר רב הונא: השואל קרדום מחבירו,\u0004 אם \u0003בקע בו\u0004 עצים — \u0003קנאו, לא בקע בו\u0004 — \u0003לא קנאו.\u0004","ושואלים: \u0003למאי\u0004 \u0005[למה],\u0006 לאיזה ענין מדובר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 לענין \u0003אונסין,\u0004 שהשואל חייב אם נשבר באונס — \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 דבר זה משאילת \u0003פרה,\u0004 שכבר \u0003משעת שאילה\u0004 נתחייב באונסין? \u0003אלא\u0004 הכוונה היא לענין \u0003חזרה\u0004 \u0005[החזרה]\u0006 לבעליו, אם \u0003בקע בו\u0004 — \u0003לא מצי הדר ביה\u0004 \u0005[יכול לחזור בו]\u0006 ה\u0003משאיל\u0004 ולומר \"שוב איני רוצה להשאילך\", אך אם \u0003לא בקע בו\u0004 — \u0003מצי\u0004 \u0005[יכול]\u0006 ה\u0003משאיל הדר ביה\u0004 \u0005[לחזור בו].\u0006","ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 שיטה זו על דברי \u0003ר' אמי,\u0004 ש\u0003אמר ר' אמי\u0004: \u0003המשאיל קרדום של הקדש\u0004 — \u0003מעל\u0004 בקודש ומשלם להקדש \u0003לפי טובת הנאה שבו,\u0004 כלומר, לפי הכסף שמוכן אדם לשלם עבור אפשרות להשאיל קרדום, שהרי ודאי יש למשאיל הנאה מסויימת (ישירה או עקיפה) ממה שהוא משאיל, ועבור הנאה זו הוא משלם. ואם כן ברור שהחפץ נקנה מיד לשואל, עוד לפני השימוש בו. \u0003וחבירו\u0004 ששאל את הקרדום הזה \u0003מותר לבקע בו לכתחילה,\u0004 שהרי כיון שחבירו מעל, נעשה החפץ כשייך למשאיל.","\u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא קנאו\u0004 בשאלה בלבד — \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003מעל?\u0004 \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 \u0003חבירו מותר לבקע בו לכתחילה? ניהדריה\u0004 \u0005[שיחזירנו]\u0006 \u0003ולא ליקנייה\u0004 \u0005[יקנה אותו]\u0006 \u0003ולא לימעול\u0004 \u0005[ימעל].\u0006 אלא ודאי סבור ר' אמי כי מרגע שהשאילו חפץ — קנה אותו השואל לענין זה שאינו חייב להחזירו למשאיל, ויכול להשתמש בו כל צורכו.","ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 דעת רב הונא גם על דעת \u0003ר' אלעזר.\u0004 ש\u0003אמר ר' אלעזר: כדרך שתקנו משיכה בלקוחות\u0004 שמאותו זמן שמשך הקונה חפץ — החפץ נקנה לו, והמקח נגמר על ידי כך, \u0003כך תקנו משיכה בשומרים,\u0004 שכאשר משך השומר את החפץ חלו עליו מיד כל החיובים והזכויות התלויים בשמירתו.","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003כשם שתקנו משיכה בלקוחות\u0004 — \u0003כך תקנו משיכה בשומרים, וכשם\u0004"],["וכשם \u0003שקרקע נקנית בכסף ובשטר ובחזקה\u0004 — \u0003כך שכירות נקנה בכסף ובשטר ובחזקה.\u0004 ושואלים: \u0003שכירות מאי עבידתיה\u0004 \u0005[מה עניינה]\u0006 פה, ומה ענין חזקה בשכירות? \u0003אמר רב חסדא:\u0004 כאן מדובר ב\u0003שכירות קרקע,\u0004 ובזו הקנין נעשה על ידי מתן כסף של השוכר, או בעצם העובדה שהשוכר מחזיק בנכס בפועל.","\u0003אמר שמואל: האי מאן דגזיל חביצא דתמרי\u0004 \u0005[מי שגוזל עיסה של תמרים]\u0006 \u0003מחבירו ואית\u0004 \u0005[ויש]\u0006 \u0003בה חמשים תמרי\u0004 \u0005[תמרים],\u0006 באופן ש\u0003אגב הדדי מזדבנן\u0004 \u0005[כולן ביחד נמכרות]\u0006 \u0003בחמשים נכי חדא\u0004 \u0005[פחות אחת]\u0006 פרוטות, כלומר, בארבעים ותשע פרוטות, ואם מוכרן \u0003חדא חדא\u0004 \u0005[אחת אחת]\u0006 \u0003מזדבנן\u0004 \u0005[הריהן נמכרות]\u0006 \u0003בחמשים,\u0004 אז, אם היתה זו גזילה מ","\u0003הדיוט,\u0004 סתם אדם — \u0003משלם חמשים נכי חדא\u0004 \u0005[פחות אחת],\u0006 כמו שעולה החבילה בשלימותה, ואם גזל מה \u0003הקדש\u0004 — \u0003משלם חמשים\u0004 שלמות \u0003וחומשייהו\u0004 \u0005[וחומש שלהם],\u0006 \u0003מה שאין כן במזיק,\u0004 שאם לא אכל אלא השמיד את התמרים, \u0003דלא משלם חומשא\u0004 \u0005[שאינו משלם חומש]\u0006 כלל, אף שמשלם את כל דמי הקרן. ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 על מה שנאמר \u0003\"ואיש כי יאכל קדש\u0004 בשגגה ויסף חמשיתו עליו\u0003\"\u0004 (ויקרא כב, יד): \"כי יאכל\" — \u0003פרט למזיק,\u0004 שאיננו מוסיף חומש.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב ביבי בר אביי: להדיוט אמאי\u0004 \u0005[מדוע]\u0006 \u0003משלם חמשים נכי חדא\u0004 \u0005[פחות אחת]?\u0006 \u0003נימא ליה\u0004 \u0005[שיאמר לו]:\u0006 \u0003אנא חדא חדא הוה מזבנינא להו\u0004 \u0005[אני אחת אחת הייתי מוכר אותן]\u0006 ומקבל חמישים, ומשום מה משלם אתה לי פחות?","\u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: \"שמין בית סאה באותה שדה\" תנן\u0004 \u0005[שנינו]\u0006 במשנה, שאם הזיק בית סאה בשדה אין מעריכים את חלק הנזק בלבד אלא מעריכים אותו כחלק מכל השדה. ומכאן שאין אנו מעריכים את הנזק לפי המחיר שיכול היה לקבל, אלא מעריכים אותו כפי שהוא שווה בשלמותו.","ומעירים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 ש\u0003סבר שמואל\u0004 כי \u0003דין הדיוט לאו\u0004 \u0005[לא]\u0006 \u0003כדין גבוה דמי\u0004 \u0005[נחשב]\u0006 לענין זה? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003נטל אבן או קורה מהקדש\u0004 — בנטילה זו בלבד \u0003לא מעל, נתנה לחבירו, הוא,\u0004 הנוטל — \u0003מעל, וחבירו\u0004 שלקח ממנו \u0003לא מעל.\u0004 וכן אם נטל אבן זו ו\u0003בנאה בתוך ביתו\u0004 — \u0003לא מעל\u0004 בעצם הבניה \u0003עד שידור תחתיה בשוה פרוטה,\u0004 שכיון שנהנה בשווה פרוטה — חייב.","\u0003ויתיב\u0004 \u0005[וישב]\u0006 \u0003ר' אבהו קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' יוחנן, ויתיב וקאמר משמיה\u0004 \u0005[וישב ואמר משמו]\u0006 של \u0003שמואל\u0004 דברים אלה, \u0003זאת אומרת: הדר בחצר חבירו שלא מדעתו צריך להעלות\u0004 (לשלם) \u0003לו שכר,\u0004 שכיוון שהדר תחת אבן של הקדש צריך לשלם עבור מה שנהנה, הרי אף הנהנה מדירה בחצר חבירו, גם אם אותה חצר אינה עומדת להשכרה, ואין בעליה יודע, ואינו מפסיד כלל, מכל מקום צריך לשלם עבור הנאתו. ולענייננו הרי זו ראיה ששמואל לומד דין הדיוט מדין הקדש! ודוחים: \u0003אמר ליה רבי יוחנן, הדר ביה\u0004 \u0005[חזר בו]\u0006 \u0003שמואל מההיא\u0004 \u0005[מאותה\u0006 סברה\u0005]\u0006 שלמדים דין הדיוט מהקדש.","ושואלים: \u0003וממאי\u0004 \u0005[וממה]\u0006 ודע אתה \u0003ש\u0004\u0003מההיא הדר ביה\u0004 \u0005[חזר בו],\u0006 \u0003דלמא מהא הדר\u0004 \u0005[שמא מזו\u0006 שלנו \u0005חזר בו]?\u0006 ומשיבים: \u0003לא,\u0004 ברור לנו כי \u0003מההיא הדר ביה\u0004 \u0005[חזר בו]\u0006 לפי שאז מכוונים הדברים \u0003כ\u0004דברי \u0003רבא.\u0004 ש\u0003אמר רבא:\u0004 הנוטל חפץ של \u0003הקדש שלא מדעת\u0004 הגזבר הממונה על ההקדש — דינו \u0003כהדיוט\u0004 שלקח דבר \u0003מדעת דמי\u0004 \u0005[נחשב],\u0006 הרי כאן הסבר לדברי המשנה לענין האבן, משמע, שאין דין הקדש כדין הדיוט.","לעצם החלוקה בין מחירים שונים עבור אותה סחורה \u0003אמר רבא: הני שקולאי דתברו חביתא דחמרא לחנוואה\u0004 \u0005[אלה הסבלים ששברו חבית יין לחנווני],\u0006 ואותה חבית \u0003ביומא דשוקא מיזדבנא\u0004 \u0005[ביום השוק\u0006 היא \u0005נמכרת]\u0006 \u0003בחמש, בשאר יומי מיזדבנא\u0004 \u0005[הימים\u0006 היא \u0005נמכרת]\u0006 \u0003בארבע.\u0004 אם \u0003אהדרו ליה ביומא דשוקא\u0004 \u0005[החזירו לו\u0006 את היין \u0005ביום השוק]\u0006 — \u0003מהדרו ליה חביתא דחמרא\u0004 \u0005[מחזירים לו חבית יין],\u0006 ואם היה זה \u0003בשאר יומי\u0004 \u0005[בשאר הימים]\u0006 \u0003מהדרו ליה בחמש\u0004 \u0005[מחזירים לו חמישה זוזים],\u0006 ומוסיפים:","\u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 דבר זה \u0003אלא\u0004 כש\u0003לא הוה ליה חמרא לזבוני\u0004 \u0005[היה לו יין\u0006 אחר \u0005למכור],\u0006 ונמצא מפסיד, \u0003אבל\u0004 אם \u0003הוה ליה חמרא לזבוני\u0004 \u0005[היה לו יין\u0006 אחר \u0005למכור]\u0006 — \u0003הא איבעי ליה לזבוני\u0004 \u0005[הרי היה צריך למכור]\u0006 ולכן עליהם להחזיר לו רק חבית יין, וכשמחזירים לו חמשה זוזים ו","\u0003מנכי ליה אגר טירחיה ודמי ברזנייתא\u0004 \u0005[ומנכה לו\u0006 החנווני את דמי \u0005שכר טירחתו ודמי נקיבת החבית],\u0006 שהרי אם היתה בידו החבית היה צריך לטרוח במכירתה ולשלם עבור נקיבתה, וכיון שהם נותנים לו כסף, מנכים לו מן הכסף מה שהיה צריך להוציא אילו היתה החבית עצמה בידו."],["\u0003המחליף פרה בחמור וילדה\u0004 הפרה בינתיים, \u0003וכן המוכר שפחתו וילדה\u0004 בינתיים, \u0003זה\u0004 בעל הפרה או בעל השפחה \u0003אומר: עד שלא מכרתי\u0004 ילדה, ולכן הוולד שייך לי. \u0003וזה\u0004 הקונה \u0003אומר: משלקחתי\u0004 (משקניתי) ילדה, והוולד שלי, כיון שאין הוכחה בדבר — \u0003יחלוקו.\u0004","\u0003היו לו שני עבדים, אחד גדול ואחד קטן, וכן שתי שדות, אחת גדולה ואחת קטנה\u0004 ומכר אחד מהם ולא פירש.","\u0003הלוקח אומר: גדול לקחתי, והלה\u0004 המוכר \u0003אומר: איני יודע\u0004 — \u0003זכה\u0004 הלוקח \u0003בגדול.\u0004","ולהיפך, אם \u0003המוכר אומר: קטן מכרתי, והלה אומר: איני יודע\u0004 — \u0003אין לו\u0004 ללוקח \u0003אלא קטן.\u0004","\u0003זה\u0004 הלוקח \u0003אומר גדול וזה אומר קטן\u0004 — \u0003ישבע המוכר שהקטן מכר.\u0004","\u0003זה אומר: איני יודע, וזה אומר: איני יודע\u0004 — \u0003יחלוקו.\u0004","ושואלים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003יחלוקו\u0004 בדברים אלה? \u0003וליחזי ברשות דמאן קיימא\u0004 \u0005[ונראה ברשותו של מי נמצא\u0006 הולד\u0005]\u0006 \u0003ולהוי אידך\u0004 \u0005[ושיהיה האחר]\u0006 \u0003המוציא מחבירו\u0004 ותהא \u0003עליו\u0004 חובת \u0003הראיה!\u0004","\u0003אמר ר' חייא בר אבין אמר שמואל:\u0004 מדובר כאן בפרה ה\u0003עומדת באגם\u0004 (אחו), שאיננה מצויה אז לא ברשות המוכר ולא ברשות הקונה. \u0003שפחה נמי\u0004 \u0005[גם כן]\u0006 מדובר באופן \u0003דקיימא בסימטא\u0004 \u0005[ש\u0006היא \u0005עומדת,\u0006 נמצאת\u0005],\u0006 שאיננה שייכת לאף אחד מהם.","ושואלים: אף אז אפשר לומר: \u0003ונוקמא אחזקת דמרא קמא\u0004 \u0005[ונעמיד אותה על החזקה של בעליה הראשון]\u0006 \u0003וליהוי אידך\u0004 \u0005[ושיהיה האחר],\u0006 הלוקח, \u0003המוציא מחבירו עליו הראיה,\u0004 שהרי כל עוד שלא הוכח שיצאה מחזקת בעליה הריהו עדיין בחזקתם!","ומשיבים: \u0003הא מני\u0004 \u0005[\u0006משנתנו \u0005זו\u0006 כדעת \u0005מי היא]\u0006 — כדעת \u0003סומכוס היא,\u0004 ש\u0003אמר: ממון המוטל בספק חולקין\u0004 הטוענים עליו \u0003בלא שבועה.\u0004","ומקשים: \u0003אימור\u0004 \u0005[אמור]\u0006 ש\u0003אמר\u0004 \u0003סומכוס\u0004 דבריו \u0003ב\u0004טענת \u0003שמא ושמא,\u0004 כאשר שני הצדדים אינם בטוחים בדבריהם, וטוענים שמא היו הדברים באופן זה. אבל \u0003ב\u0004טענת \u0003ברי וברי,\u0004 ששני הצדדים טוענים בוודאות שהוא שלהם, \u0003מי\u0004 \u0005האם\u0006 \u0003אמר\u0004 כן?","\u0003אמר רבה בר רב הונא: אין\u0004 \u0005[כן],\u0006 \u0003אמר סומכוס\u0004 יחלוקו \u0003אפילו ב\u0004טענת \u0003ברי וברי.\u0004","\u0003רבא אמר: לעולם כי\u0004 \u0005[כאשר]\u0006 \u0003אמר סומכוס\u0004 שיחלוקו הרי זה בטענת \u0003שמא ושמא, אבל\u0004 בטענת \u0003ברי וברי לא אמר. ותני\u0004 \u0005[ושנה]\u0006 ותקן וגרוס בלשון משנתנו: \u0003זה אומר שמא עד שלא מכרתי, וזה אומר שמא משלקחתי.\u0004","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003זה אומר איני יודע וזה אומר איני יודע\u0004 — \u0003יחלוקו.\u0004","\u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רבא\u0004 \u0003מדסיפא\u0004 \u0005[מכיון שבסופה]\u0006 מדובר בטענת \u0003שמא ושמא\u0004 — \u0003רישא נמי\u0004 \u0005[\u0006ב\u0005ראשה\u0006 \u0003גם כן]\u0004 מדובר בטענת \u0003שמא ושמא.\u0004 \u0003אלא ל\u0004שיטת \u0003רבה בר רב הונא,\u0004 ש\u0003אמר: אין\u0004 \u0005[כן],\u0006 \u0003אמר סומכוס\u0004 שיחלוקו \u0003אפילו\u0004 בטענת \u0003ברי וברי,\u0004 אם כן יש להקשות: \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 בטענת \u0003ברי וברי אמר\u0004 סומכוס ש\u0003יחלוקו,\u0004 ואם כן בטענת \u0003שמא ושמא מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]?\u0006","ודוחים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום הא\u0004 \u0005[כך]\u0006 — \u0003לא איריא\u0004 \u0005[אינו שייך]\u0006 להקשות, כי אפשר לומר: \u0003תנא סיפא לגלויי רישא\u0004 \u0005[שנה את סופה של\u0006 המשנה כדי \u0005לגלות\u0006 לנו \u0005את\u0006 משמעות \u0005ראשה],\u0006 \u0003שלא תאמר\u0004 שב\u0003רישא\u0004 \u0005[ראשה]\u0006 מדובר בטענת \u0003שמא ושמא, אבל\u0004 אם היה זה בטענת \u0003ברי וברי לא\u0004 היה אומר סומכוס שיחלוקו, לכן \u0003תנא סיפא\u0004 \u0005[שנה בסופה]\u0006 בפירוש טענת \u0003שמא ושמא,\u0004 כדי שנלמד מכאן: \u0003מכלל דרישא\u0004 \u0005[מכאן שבראשיתה]\u0006 מדובר בטענת \u0003ברי וברי, ואפילו הכי\u0004 \u0005[כך]\u0006 סבור כי \u0003יחלוקו.\u0004","ושואלים עוד, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתינו\u0005]:\u0006 \u0003זה\u0004 הקונה \u0003אומר גדול\u0004 קנה \u0003וזה\u0004 המוכר \u0003אומר קטן\u0004 — \u0003ישבע המוכר שקטן מכר.\u0004","\u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רבא\u0004 ש\u0003אמר: כי\u0004 \u0005[כאשר]\u0006 \u0003אמר סומכוס\u0004 שיחלוקו — בטענת \u0003שמא ושמא אמר\u0004 כן, \u0003אבל\u0004 בטענת \u0003ברי וברי\u0004 — \u0003לא אמר, משום הכי\u0004 \u0005[כך]\u0006 \u0003ישבע,\u0004 לפי שיש כאן טענת ברי וברי, ואף סומכוס מודה שחייב שבועה. \u0003אלא לרבה בר רב הונא\u0004 ש\u0003אמר: אין\u0004 \u0005[כן],\u0006 \u0003אמר סומכוס\u0004 שיחלוקו \u0003אפילו\u0004 בטענת \u0003ברי וברי, אמאי\u0004 \u0005[מדוע]\u0006 \u0003ישבע\u0004 ה\u0003מוכר? יחלוקו מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006","ומשיבים: \u0003מודה סומכוס היכא דאיכא\u0004 \u0005[במקום שיש]\u0006 חיוב \u0003שבועה דאורייתא\u0004 \u0005[מן התורה]\u0006 שאין אומרים יחלוקו, אלא ישבע החייב, \u0003כדבעינן למימר לקמן\u0004 \u0005[כפי שנצטרך לומר הלאה]\u0006 בהמשך הדיון. וכיון שכאן יש מקום לחיוב שבועה כזו, אף סומכוס אומר שישבע.","שנינו במשנה: \u0003היו לו\u0004 למוכר \u0003שני עבדים אחד גדול ואחד קטן,\u0004 ואמר המוכר שקטן מכר — ישבע שאכן את הקטן מכר. ותוהים, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003ישבע?\u0004 הלא אין זה מודה במקצת הטענה, כי \u0003מה שטענו\u0004 לגבי העבד הגדול — \u0003לא הודה לו, ומה שהודה לו\u0004 — \u0003לא טענו!\u0004","\u0003ועוד,\u0004 הרי מקרה זה \u0003\"הילך\" הוא,\u0004 שבו אין מקום לישבע. שכן כאשר הנתבע מודה בדבר ואינו מעכב אותו כלל, אלא אומר \"הילך\" (=הא לך) — אינו חייב שבועה על השאר.","\u0003ועוד,\u0004 הלא כלל הוא ש\u0003אין נשבעין על העבדים,\u0004 שהרי עבדים דינם כקרקעות!","\u0003אמר רב:\u0004 מדובר כאן \u0003בטוענו דמי\u0004 \u0005[דמים,\u0006 מחיר\u0005],\u0006 שאינו תובע את גוף העבד, אלא רק דמים; \u0003דמי עבד גדול, דמי עבד קטן, דמי שדה גדולה, דמי שדה קטנה.\u0004 וכיון שהם מתדיינים רק בכספים ממילא נפתרות חלק מן השאלות הללו, שכן הוא מודה המקצת הסכום, וכן שאין זו שבועה על העבד על חיוב כספי.","\u0003ושמואל אמר:\u0004 במשנה מדובר \u0003בטוענו\u0004 לא על העבד עצמו אלא על \u0003כסות עבד גדול,\u0004 והמוכר מודה לו ב\u0003כסות עבד קטן,\u0004 ובשדה — שטוענו על \u0003עומרי שדה גדולה\u0004 שמכר לו, והמוכר מודה לו ב\u0003עומרי שדה קטנה.\u0004"],["\u0003כסות,\u0004 הלא \u0003מה שטענו לא הודה לו, ומה שהודה לו לא טענו,\u0004 שהרי הוא טען כסות גדולה, והאחר הודה לו בכסות אחרת! ומשיבים: \u0003כדאמר\u0004 \u0005[כפי שאמר]\u0006 \u0003רב פפא\u0004 להלן, שמדובר \u0003בדיילפי\u0004 \u0005[במחוברות],\u0006 בכסות גדולה וקטנה שהיו מחוברות זו לזו, וכן יש לומר כי \u0003הכא נמי בדיילפי\u0004 \u0005[כאן גם כן\u0006 מדובר \u0005כשהיו מחוברות].\u0006","\u0003קשיא ליה\u0004 \u0005[קשה היה לו]\u0006 \u0003לר' הושעיא\u0004 על תירוץ זה: \u0003מידי\u0004 \u0005[וכי]\u0006 \u0003\"כסות\" קתני\u0004 \u0005[שנינו]?\u0006 והלא \u0003\"עבד\" קתני\u0004 \u0005[שנינו]!\u0006","\u0003אלא אמר ר' הושעיא:\u0004 כאן מדובר \u0003כגון שטענו עבד בכסותו ושדה בעומריה.\u0004 ושתי טענות היו כאן, שעל אחת מהן חייב להשבע וכיון שנשבע כבר זוקקים שישבע גם על העבד והשדה. ושואלים: \u0003ואכתי\u0004 \u0005[ועדיין]\u0006 בענין \u0003כסות\u0004 זו, הלא \u0003מה שטענו\u0004 — \u0003לא הודה לו ומה שהודה לו\u0004 — \u0003לא טענו!\u0004 על כך \u0003אמר רב פפא:\u0004 מדובר פה \u0003בדיילפי\u0004 \u0005[במחוברות],\u0006 בשני חלקי כסות שהיו צמודים זה לזה. ומודה לו בחלק הקטן.","\u0003קשיא ליה\u0004 \u0005[קשה היה לו]\u0006 ל\u0003רב ששת\u0004 על פירוש זה, שלפיו מדברת המשנה במי שנתחייב שבועה על טענה אחת, שעל ידי כך מחייבים (\"זוקקים\") אותו להשבע גם על טענה אחרת — וכי את הדין ש\u0003\"זוקקין\"\u0004 דברים בשבועה \u0003אתא לאשמועינן\u0004 \u0005[\u0006\u0005בא להשמיענו]?!\u0006 הלא \u0003תנינא\u0004 \u0005[שנינו\u0006 כבר במפורש\u0005]:\u0006 \u0003זוקקין הנכסים שאין להן אחריות\u0004 (מטלטלין), \u0003את הנכסים שיש להן אחריות לישבע עליהן.\u0004 ואם זו היא משמעות המשנה נמצא שלא נתחדש בה דבר!","\u0003אלא אמר רב ששת: הא מני\u0004 \u0005[\u0006משנתינו \u0005זו\u0006 כשיטת \u0005מי היא]\u0006 — כ\u0003ר' מאיר,\u0004 ש\u0003אמר: עבדא\u0004 \u0005[העבד]\u0006 \u0003כמטלטלין דמי\u0004 \u0005[\u0006הוא \u0005נחשב]\u0006 ומשום כך נשבעים עליו.","ושואלים: \u0003ואכתי\u0004 \u0005[ועדיין]\u0006 אפשר להקשות: \u0003מה שטענו\u0004 — \u0003לא הודה לו, ומה שהודה לו\u0004 — \u0003לא טענו,\u0004 שהרי טענו בעבד גדול והודה לו בעבד קטן! ומשיבים: בענין זה יש לומר ש\u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 רבי מאיר \u0003כ\u0004שיטת \u0003רבן גמליאל. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003טענו\u0004 (תבעו) \u0003חטים והודה\u0004 לו ב\u0003שעורים\u0004 — \u0003פטור,\u0004 שהרי הודה שלא ממין הטענה. \u0003רבן גמליאל מחייב.\u0004 ומדוע — שלדעתו כיון שמחיר השעורים פחות ממחיר החיטים, הרי זה כמודה במקצת. וכן הדין בעבד קטן וגדול.","ומקשים עוד: \u0003אכתי\u0004 \u0005[עדיין]\u0006 קיימת השאלה האחרת, שהרי \u0003\"הילך\" הוא,\u0004 שהרי הוא מודה ומוכן לתת מיד, ובכגון זה שנינו שאינו נשבע! \u0003אמר רבא:\u0004 אין כאן הילך, כי כאן מדובר במקרה מיוחד ב\u0003עבדא\u0004 \u0005[עבד]\u0006 ש\u0003קטע לידיה\u0004 \u0005[את ידו],\u0006 שנמצא שאיננו יכול להחזיר לו את העבד כמו שהוא (ולומר \"הילך\") אלא יצטרך לחזור ולשלם תשלום נוסף. \u0003ושדה\u0004 זה, אף הוא אין בו הילך, ומדובר כאן בכגון \u0003שחפר בה בורות, שיחין\u0004 (בורות מוארכים) \u0003ומערות\u0004 ושוב אינו יכול להשיבה לו כמו שהיתה.","ושוב מקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' מאיר איפכא שמעינן ליה\u0004 \u0005[היפך\u0006 דברים אלה \u0005שמענו אותו\u0006 אומר\u0005],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003גזל בהמה ו\u0004בינתיים \u0003הזקינה, עבדים והזקינו\u0004 — הרי זה \u0003משלם כשעת הגזילה,\u0004 ואילו \u0003ר' מאיר אומר: בעבדים אומר לו \"הרי שלך לפניך\",\u0004 ואיננו מתחשב במה שהזקינו. משמע, שלשיטתו בעבדים, אפילו כשירד ערכם איננו צריך להשלים את המחיר!","ומשיבים: \u0003הא לא קשיא\u0004 \u0005[זה איננו קשה],\u0006 כי יש לשנות שם את הגרסה \u0003כדמחליף\u0004 \u0005[כפי שהיה מחליף]\u0006 \u0003רבה בר אבוה ותני\u0004 \u0005[ושונה],\u0006 \u0003ר' מאיר אומר: משלם כשעת הגזילה, וחכמים אומרים: אומר לו בעבדים \"הרי שלך לפניך\".\u0004","אלא יש להקשות על דברי רב ששת באופן אחר: \u0003ממאי\u0004 \u0005[ממה]\u0006 מסיק אתה \u0003דסבר\u0004 \u0005[שסבור]\u0006 \u0003ר' מאיר\u0004 כי \u0003מקשינן\u0004 \u0005[מקישים אנו,\u0006 משווים\u0005]\u0006 דין \u0003קרקע ל\u0004דין \u0003עבד; מה עבד נשבעין\u0004 — \u0003אף קרקע נשבעין? דלמא\u0004 \u0005[שמא]\u0006 על \u0003עבד הוא\u0004 ש\u0003נשבעין, אבל\u0004 על \u0003קרקע\u0004 \u0003לא\u0004 נשבעים — אין נשבעים!","ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[יכול לעלות על דעתך]\u0006 לומר כך, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003המחליף פרה בחמור וילדה, וכן המוכר שפחתו וילדה,\u0004","\u0003זה,\u0004 אחד מהם, \u0003אומר: ברשותי\u0004 ילדה, \u0003וזה\u0004 הצד השני \u0003שותק\u0004 — \u0003זכה\u0004 הטוען.","\u0003זה אומר: \"איני יודע\", וזה אומר: \"איני יודע\"\u0004 — \u0003יחלוקו.\u0004","\u0003זה אומר: \"ברשותי\", וזה אומר: \"ברשותי\"\u0004 — \u0003ישבע המוכר שברשותו ילדה, לפי שכל הנשבעין שבתורה נשבעין ולא משלמין,\u0004 אלו \u0003דברי ר' מאיר,\u0004 ולכן במקרה של ספק כזה חובת השבועה היא תמיד על הנתבע. \u0003וחכמים אומרים: אין נשבעין לא על העבדים ולא על הקרקעות.\u0004","וכיון שחכמים אומרים כך, \u0003לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 נלמד \u0003מכלל\u0004 הדברים ש\u0003ר' מאיר סבר\u0004 \u0005[סבור]\u0006 ש\u0003נשבעין\u0004 על שניהם!","ודוחים: \u0003ממאי\u0004 \u0005[ממה]\u0006 מוכיח אתה זאת? \u0003דלמא\u0004 \u0005[שמא]\u0006 בסגנון של \u0003\"כשם\" קאמרו ליה\u0004 \u0005[אמרו לו],\u0006 כלומר, \u0003כי היכי דאודית לן\u0004 \u0005[כפי שהודית לנו]\u0006 \u0003בקרקעות\u0004 שאין נשבעים — \u0003אודי לן נמי\u0004 \u0005[הודה לנו גם כן]\u0006 \u0003בעבדים,\u0004 וממילא תתבטל ההלכה שקבעה.","ומוסיפים: \u0003תדע\u0004 שכן הוא, \u0003דתנן\u0004 \u0005[שכן שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' מאיר אומר: יש דברים שהן כקרקע\u0004 לענין חיוב שבועה \u0003ואינן כקרקע\u0004 ממש. \u0003ואין חכמים מודים לו. כיצד?\u0004 — כגון שהמוכר אומר: \u0003עשר גפנים טעונות\u0004 ענבים \u0003מסרתי לך, והלה\u0004 הקונה \u0003אומר: אינן אלא חמש, ר' מאיר מחייב\u0004 שבועה בכגון זה, שכיון שהגפנים היו טעונות ענבים נמצא שדנים גם על חלק מסויים שאיננו קרקע, ועליו אפשר לישבע. \u0003וחכמים אומרים: כל המחובר לקרקע\u0004 — \u0003הרי הוא כקרקע.\u0004","\u0003ואמר ר' יוסי בר חנינא:\u0004 לענין \u0003ענבים העומדות ליבצר איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005].\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 ר' \u0003מאיר\u0004 \u0005סבור]:\u0006 \u0003כבצורות דמיין\u0004 \u0005[הן נחשבות]\u0006 ויש עליהן חובת שבועה כאילו היו תלושות, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 חכמים \u0005סבור]:\u0006 \u0003לאו\u0004 \u0005[לא]\u0006 \u0003כבצורות דמיין\u0004 \u0005[הן נחשבות].\u0006 נמצא איפוא כי ר' מאיר מודה שאין נשבעים על הקרקעות. ואם כך פירושו של רב ששת אין לו קיום.","\u0003אלא, לעולם\u0004 תפרש \u0003כ\u0004דברי \u0003ר' הושעיא, ודקשיא\u0004 \u0005[ומה שהיה קשה]\u0006 \u0003לך\u0004 וכי דין \u0003זוקקין\u0004 הוצרך ללמדנו? אף על פי כן \u0003איצטריך\u0004 \u0005[צריך];\u0006 שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 כי \u0003כסות עבד\u0004 — \u0003כעבד דמי\u0004 \u0005[היא נחשבת],\u0006 וכן כי \u0003עומרי שדה\u0004 — \u0003כשדה דמי\u0004 \u0005[הם נחשבים],\u0006 שהם כחלק מדבר שאין עליו חובת שבועה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין הדבר כן, וכי זו טענה לעצמה שחייבים עליה שבועה.","שנינו בברייתא : \u0003זה אומר: \"איני יודע\", וזה אומר: \"איני יודע\"\u0004 — \u0003יחלוקו.\u0004 ומעירים : \u0003הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי היא]\u0006 — כשיטת \u0003סומכוס היא\u0004 ש\u0003אמר:\u0004 כל \u0003ממון המוטל בספק\u0004 — \u0003חולקין\u0004 הטוענים עליו,","ואולם, \u0003אימא סיפא\u0004 \u0005[אמור את סופה]\u0006 של הברייתא: \u0003זה אומר \"ברשותי\" וזה אומר \"ברשותי\"\u0004 — \u0003ישבע המוכר שברשותו ילדה,\u0004 \u0003ול\u0004דעת \u0003רבה בר רב הונא\u0004 שאמר \u0003אין\u0004 \u0005[כן]\u0006 \u0003אמר סומכוס\u0004 שיחלוקו \u0003אפילו\u0004 בטענת \u0003ברי וברי, אמאי\u0004 \u0005[מדוע]\u0006 \u0003ישבע\u0004 ה\u0003מוכר?\u0004 הלא \u0003\"יחלוקו\" מיבעיא\u0004 \u0005[צריך היה\u0006 לומר\u0005]!\u0006","ומשיבים: \u0003מודה סומכוס היכא דאיכא\u0004 \u0005[במקום שיש]\u0006 \u0003שבועה דאורייתא\u0004 \u0005[מן התורה],\u0006 וכאן יש לפרש ש\u0003קטעה לידה\u0004 של השפחה \u0003כ\u0004שיטת \u0003רבא,\u0004 וכיון שצריך להוסיף ולשלם, ואינו יכול להסתפק בהחזרת השפחה בלבד, אין כאן משום \"הילך\", וחלה עליו חובת שבועה, אפילו לדעת סומכוס.","\u0003המוכר זיתיו לעצים\u0004 — שהזקינו עצי הזית ואין נותנין עוד פירות, ומכר אותם לאדם שיקצצם וישתמש בעצים, \u0003ו\u0004בינתיים \u0003עשו\u0004 הזיתים פירות עד שקצצם, אם עשו זיתים גרועים הנותנים \u0003פחות מרביעית\u0004 שמן \u0003לסאה\u0004 של זיתים — \u0003הרי אלו של בעל הזיתים,\u0004 האיש שקנה את העצים.","אם \u0003עשו רביעית לסאה, זה\u0004 הקונה \u0003אומר: זיתי גדלו\u0004 את הזיתים הללו, \u0003וזה,\u0004 בעל הקרקע \u0003אומר: ארצי,\u0004 הקרקע שלי \u0003גדלה\u0004 אותם, ושלי הם — \u0003יחלוקו.\u0004","ודין אחר: \u0003שטף נהר\u0004 את עצי \u0003זיתיו ונתנם לתוך שדה חבירו\u0004 ושם נקלטו הזיתים ועשו פירות, \u0003זה\u0004 הקונה \u0003אומר: \"זיתי גדלו\", וזה,\u0004 בעל הקרקע \u0003אומר: \"ארצי גדלה\"\u0004 — \u0003יחלוקו.\u0004","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד היה בדיוק]\u0006 ענין זה במוכר הזיתים? \u0003אי\u0004 \u0005[אם]\u0006 מדובר באופן ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 בעל הזיתים לקונה: \u0003קוץ לאלתר\u0004 \u0005[\u0006\u0005קצוץ\u0006 אותם \u0005מיד]\u0006 — \u0003אפילו\u0004 הניבו הזיתים \u0003פחות מרביעית\u0004 שמן — \u0003נמי\u0004 \u0005[גם כן]\u0006 שייך הכל \u0003לבעל הקרקע,\u0004 שאם לא נטל מיד את הזיתים כל מה שירוויח בינתיים הוא ברשות בעליהם הראשונים. \u0003אי\u0004 \u0005[אם]\u0006 מדובר באופן ש\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כל אימת דבעית\u0004 \u0005[זמן שתרצה]\u0006 לקצוץ — \u0003קוץ\u0004 \u0005[קצוץ],\u0006 נמצא שהניח לו את הזיתים כפי שהם — \u0003אפילו\u0004 הניבו הזיתים \u0003רביעית\u0004 שמן \u0003נמי\u0004 \u0005[גם כן]\u0006 הוא שייך \u0003לבעל\u0004 ה\u0003זיתים!\u0004","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא לכאשר \u0003אמר ליה סתמא\u0004 \u0005[לו סתם]\u0006 ולא קבע זמן. ובכגון זה אם עשו \u0003פחות מרביעית\u0004 — \u0003לא קפדי אינשי\u0004 \u0005[אין אנשים מקפידים]\u0006 ובוודאי מחל לו, ואם עשו \u0003רביעית\u0004 — \u0003קפדי אינשי\u0004 \u0005[מקפידים אנשים]\u0006 על כך ואינם מוותרים.","\u0003אמר ר' שמעון בן פזי: ורביעית שאמרו\u0004 בענין זה —"],["\u0003חוץ מן ההוצאה,\u0004 שהכוונה היא שנשאר רווח נקי של רביעית שמן אחרי שמשלם את דמי המסיקה ודמי הסחיטה מן הזיתים.","שנינו במשנה: \u0003שטף נהר זיתיו\u0004 וכו'. \u0003אמר עולא אמר ריש לקיש: לא שנו\u0004 כן \u0003אלא\u0004 כ\u0003שנעקרו\u0004 הזיתים \u0003בגושיהן,\u0004 כלומר, עם גושי האדמה שהיו מושרשים בהם ושנקלטו בקרקע החדשה, \u0003ולאחר שלש\u0004 שנים שהם זמן איסור ערלה,","\u0003אבל בתוך שלש\u0004 שנים לעקירתן — \u0003הכל של בעל הזיתים. דאמר ליה\u0004 \u0005[שאומר לו]\u0006 בעל הזיתים לבעל הקרקע: \u0003אי את נטעת\u0004 \u0005[אם אתה היית נוטע]\u0006 אותם \u0003בתוך שלש\u0004 שנים \u0003מי הוה אכלת\u0004 \u0005[\u0006\u0005האם היית אוכל\u0006 מהם\u0005]?\u0006 הלא בשלוש שנים הראשונות לנטיעה ערלה הם ואסורים בהנאה, אם כן, בעל כרחך מסכים אתה שהזיתים הללו נזונים מן האדמה שהביאו עמם ואינם כנטועים ברשותך ואסורים בהנאה ולכן הזיתים שעושים עתה שלי הם.","ומקשים: \u0003ולימא ליה\u0004 \u0005[ושיאמר לו]\u0006 בעל השדה: \u0003אי אנא נטעי\u0004 \u0005[אם אני הייתי נוטע]\u0006 אותם, \u0003לאחר שלש\u0004 שנים \u0003הוה אכילנא ליה כוליה\u0004 \u0005[הייתי אוכל\u0006 אותם \u0005כולם].\u0006 \u0003השתא קאכלת פלגא בהדאי\u0004 \u0005[עכשיו\u0006 במקרה זה \u0005אוכל אתה החצי איתי],\u0006 שהרי אמרנו שיחלוקו. ואם כן, אף בשלוש השנים הראשונות מגיע לי חלק!","\u0003אלא\u0004 לא כך נאמר, ו\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ריש לקיש\u0004 בגירסה שונה: \u0003לא שנו אלא שנעקרו בגושיהן ובתוך שלש, אבל לאחר שלש הכל לבעל הקרקע. דאמר ליה\u0004 \u0005[\u0006שיכול הוא \u0005לומר לו]:\u0006 \u0003אי אנא נטעי\u0004 \u0005[אם אני הייתי נוטע]\u0006 אותם, \u0003לאחר שלש\u0004 שנים — \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא הוה אכילנא ליה כוליה\u0004 \u0005[הייתי אוכל אותם כולם]?\u0006","ושואלים: \u0003ולימא ליה\u0004 \u0005[ושיאמר לו]\u0006 בעל הזיתים: \u0003אי את נטעת\u0004 \u0005[אם אתה היית נוטע]\u0006 אותם — \u0003בתוך שלש לא הוה אכלת\u0004 \u0005[היית אוכל]\u0006 מהם כלל משום ערלה, \u0003השתא קא אכלת פלגא בהדאי\u0004 \u0005[עכשיו אתה אוכל חלק אתי]?\u0006 ומשיבים: \u0003משום דאמר ליה\u0004 \u0005[שאומר\u0006 הוא \u0005לו]:\u0006 \u0003אי אנא נטעי\u0004 \u0005[אילו הייתי אני נוטע אותם]\u0006 — במשך שלוש השנים \u0003הוה קטיני וזרענא תחותייהו סילקא וירקא\u0004 \u0005[היו\u0006 \u0005קטנים והייתי זורע תחתם תרד וירק]\u0006 והייתי מרוויח בהם, ונמצא אף אני מפסיד מגדרם של העצים, ודיי בחלק במשך שלוש השנים.","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003אמר הלה\u0004 בעל הזיתים: \u0003\"זיתיי אני נוטל\"\u0004 — \u0003אין שומעין לו\u0004 ליטול את הזיתים בחזרה. ושואלים: \u0003מאי טעמא\u0004 \u0005[מהו טעם]\u0006 הדבר? \u0003אמר ר' יוחנן: משום ישוב ארץ ישראל\u0004 שלא לגרום לאבד את העצים של ארץ ישראל הצומחים עתה במקום זה. \u0003אמר ר' ירמיה: כגון דא צריכא\u0004 \u0003רבה\u0004 \u0005[זה צריך],\u0006 כלומר, לולא פירש לנו רבי יוחנן סברא זו לא היינו יודעים אותה מדעתנו.","\u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה\u0005],\u0006 \u0003ר' יהודה אומר: המקבל\u0004 (כאריס או קבלן לעבד שדה) \u0003שדה אבותיו מן הגוי\u0004 — \u0003מעשר\u0004 מן השדה הזה את כל המעשרות שחייב להפריש מכל שדה \u0003ונותן לו\u0004 לגוי את חלקו, שנמצא מפריש מעשרות גם מחלקו של הגוי.","\u0003סברוה\u0004 \u0005[סברו\u0006 חשבו תחילה\u0005]\u0006 \u0003מאי\u0004 \u0005[מה פירוש]\u0006 \u0003\"שדה אבותיו\"\u0004 — הכוונה היא ל\u0003ארץ ישראל\u0004 כולה, \u0003ואמאי קרו\u0004 \u0005[ומדוע קוראים]\u0006 \u0003\"שדה אבותיו\"\u0004 — משום שהיא \u0003שדה אברהם יצחק ויעקב\u0004 אבותינו.","\u0003וקסבר\u0004 \u0005[וסבור]\u0006 תנא זה: ש\u0003אין קנין לגוי בארץ ישראל להפקיע מיד מעשר,\u0004 כלומר, גם אם קנה הגוי קרקע בארץ ישראל אין הדבר מפקיע את הקרקע מידי חובת המעשרות ולכן חובה לעשר מתבואה שצמחה שם.","\u0003ו\u0004עוד סבר כי \u0003מקבל\u0004 — \u0003כחוכר דמי\u0004 \u0005[נחשב].\u0006 \u0003מה חוכר, בין עבד\u0004 \u0005[שעשתה]\u0006 האדמה, \u0003ובין לא עבד\u0004 \u0005[עשתה],\u0006 \u0003בעי עשורי ומיתן ליה\u0004 \u0005[צריך לעשר ולתת לו],\u0006 \u0003דכי\u0004 \u0005[שכמו]\u0006 \u0003פורע חובתו\u0004 לגוי \u0003דמי\u0004 \u0005[הוא נחשב]\u0006 כאשר נותן לו חלקו, ואינו רשאי להשתמש לשם כך במעשר. \u0003אף מקבל נמי\u0004 \u0005[גם כן]\u0006 \u0003כי\u0004 \u0005[כמו]\u0006 \u0003פורע חובתו דמי\u0004 \u0005[הוא נחשב]\u0006 ולכן \u0003מעשר ונותן לו.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב כהנא לרב פפי, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003לרב זביד: אלא הא דתניא\u0004 \u0005[זו ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה אומר: המקבל שדה אבותיו ממציק גוי\u0004 (אדם שגזל את הקרקע בכח יחסיו עם השלטונות) — \u0003מעשר ונותן לו\u0004 חלקו, ולשיטת הסבר זה: \u0003מאי איריא\u0004 \u0005[מה שייך]\u0006 \u0003מציק\u0004 דווקא? \u0003אפילו אין מציק\u0004 — \u0003נמי\u0004 \u0005[גם כן]\u0006 יתחייב לתת הכל!","\u0003אלא\u0004 עלינו לחזור בנו מן הסברה הראשונה ולומר: \u0003לעולם יש קנין לגוי בארץ ישראל להפקיע מיד מעשר, ומקבל לאו\u0004 \u0005[לא]\u0006 \u0003כחוכר דמי\u0004 \u0005[הוא נחשב],\u0006","\u0003ו\u0004אולם \u0003מאי\u0004 \u0005[מה פירוש]\u0006 \u0003\"שדה אבותיו\"\u0004 — \u0003שדה אבותיו ממש,\u0004 שדה שהיה שייך קודם למשפחתו. \u0003ולדידיה\u0004 \u0005[ולו\u0006 עצמו\u0005]\u0006 \u0003הוא דקנסוה רבנן\u0004 \u0005[שקנסו חכמים]\u0006 שיתן מעשר מן הכל, \u0003דאיידי דחביבא עליה טפי ואזיל מקבל לה\u0004 \u0005[שמתוך שחביבה עליו\u0006 הריהו \u0005מוסיף והולך\u0006 על השכר לבעלים \u0005ומקבל אותה\u0006 כקבלן\u0005].\u0006 \u0003אבל איניש דעלמא\u0004 \u0005[אדם סתם]\u0006 — \u0003לא.\u0004","ושואלים: \u0003ולדידיה מאי טעמא קנסוה רבנן\u0004 \u0005[והוא עצמו מה טעם קנסוהו חכמים]\u0006 בשדה אבותיו? \u0003אמר ר' יוחנן: כדי שתהא ברה\u0004 \u0005[נקיה]\u0006 \u0003בידו,\u0004 שכיוון שגזרו חכמים שיוסיף במעשרות נמצא שהוא משלם יותר מאחר ועל ידי כך לוחצים עליו שיחליט להתאמץ ולקנות בחזרה את השדה מיד המחזיק בה, ותחזור נחלת האבות לידי ישראל.","\u0003אמר ר' ירמיה: כגון דא צריכא רבה\u0004 \u0005[זה צריכה רב]\u0006 שלא היינו מגיעים להסבר זה מכח עצמנו.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו האמוראים בבעיה הבאה: \u0003היורד לתוך שדה חבירו ונטעה שלא ברשות, אמר רב: שמין לו,\u0004 שמעריכים לנוטע כמה הוציא וכמה השביח בשדה, \u0003וידו על התחתונה,\u0004 שאם ההוצאות שלו היו פחותות משבח השדה — מקבל הוצאותיו, ואם שבח השדה פחות מהוצאותיו — נותנים לו שבח השדה בלבד. \u0003ושמואל אמר: אומדין כמה אדם רוצה ליתן בשדה זו לנוטעה,\u0004 ומשלם לו.","\u0003אמר רב פפא: ולא פליגי\u0004 \u0005[נחלקו]\u0006 רב ושמואל בעצם בהלכה זו, אלא כל אחד מהם דן במקרה אחר. \u0003כאן\u0004 — \u0003בשדה העשויה ליטע\u0004 נוהגים כשמואל, \u0003כאן בשדה שאינה עשויה ליטע,\u0004 בזו אמר רב שיד הנוטע על התחתונה.","ומעירים: \u0003והא דרב\u0004 \u0005[\u0006והלכה \u0005זו]\u0006 של רב \u0003לאו\u0004 \u0005[לא]\u0006 \u0003בפירוש איתמר\u0004 \u0005[נאמרה]\u0006 כהלכה ברורה, \u0003אלא מכללא איתמר\u0004 \u0005[מכלל\u0006 הדברים \u0005נאמרה],\u0006 כלומר, זו היא מסקנה מפסק הלכה בנושא דומה. שכך היה המעשה: \u0003דההוא דאתא לקמיה\u0004 \u0005[שאדם אחד בא לפני]\u0006 \u0003רב\u0004 וטען שחבירו נטע את שדהו באילנות, \u0003אמר\u0004 רב לזה: \u0003זיל שום ליה\u0004 \u0005[לך והערך לו]\u0006 כמה מגיע לו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 בעל השדה: \u0003לא בעינא\u0004 \u0005[אין אני רוצה]\u0006 את העצים האלה. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זיל שום ליה\u0004 \u0005[לך הערך לו]\u0006 \u0003וידו על התחתונה,\u0004 שיקבל פחות שבדברים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 שוב אותו אדם: \u0003לא בעינא\u0004 \u0005[אין אני רוצה],\u0006 שאין רצונו כלל בעצים אלה, ואינו מוכן לשלם מאומה.","\u0003לסוף חזייה\u0004 \u0005[לבסוף ראה אותו]\u0006 ש\u0003גדרה,\u0004 את שדה הנטיעות הזה \u0003וקא מנטר לה\u0004 \u0005[ושמר אותוה.\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב: גלית אדעתיך דניחא\u0004 \u0005גילית דעתך שנוח\u0006 \u0003לך\u0004 בנטיעות אלה, ואם כן \u0003זיל שום ליה\u0004 \u0005[לך הערך לו]\u0006 מה שעשה, \u0003וידו על העליונה\u0004 שהרי מעשיך מוכיחים שאתה מרוצה בנטיעות.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שחנלקו האמוראים בבעיה זו: \u0003היורד לתוך חורבתו של חבירו ובנאה שלא ברשותו.\u0004 ואחר כך כשבעל החורבה טען שאיננו מרוצה. \u0003ואמר לו\u0004 הבונה: אם כן, \u0003עציי ואבניי אני נוטל\u0004 מכאן, \u0003רב נחמן אמר: שומעין לו, רב ששת אמר: אין שומעין לו\u0004 ומשאיר מה שבנה.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 הרי בענין זה שנינו בתוספתא: \u0003רבן שמעון בן גמליאל אומר: בית שמאי אומרים: שומעין לו, ובית הלל אומרים: אין שומעין לו,\u0004 ואם כן \u0003לימא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 כי \u0003רב נחמן\u0004 ש\u0003אמר\u0004 הלכה \u0003כ\u0004שיטת \u0003בית שמאי?\u0004","ומשיבים: \u0003הוא\u0004 ש\u0003אמר\u0004 דבריו, \u0003כי האי תנא\u0004 \u0005[\u0006סמך על דברי \u0005תנא זה],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא אחרת\u0005]\u0006 לענין זה: \u0003שומעין לו,\u0004 אלו \u0003דברי ר' שמעון בן אלעזר. ר' שמעון בן גמליאל אומר: בית שמאי אומרים: שומעין לו, ובית הלל אומרים: אין שומעין לו,\u0004 ואם כן, סמך רב נחמן על דעת ר' שמעון בן אלעזר שזו הלכה פסוקה לדעת הכל.","ושואלים: ולמעשה \u0003מאי הוי עלה\u0004 \u0005[מה יהיה עליה]\u0006 על הלכה זו? \u0003אמר ר' יעקב אמר ר' יוחנן:\u0004"],["\u0003בבית,\u0004 שבנה חורבה בלא רשות — \u0003שומעין לו,\u0004 ויכול ליטול מה שבנה. \u0003בשדה\u0004 — \u0003אין שומעין לו.\u0004","ומסבירים: \u0003בשדה מאי טעמא\u0004 \u0005[מה טעם]\u0006 אין שומעין לו — \u0003משום ישוב ארץ ישראל. איכא דאמרי\u0004 \u0005[יש אומרים]:\u0006 \u0003משום כחשא דארעא,\u0004 שהרי בין כה וכה כבר כחשה האדמה על ידי הנטיעות, ולכן אין הוא יכול לומר \"הריני נוטל את נטיעותי\" ולא יהיה עוד בינינו משא ומתן. ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 אם זה הטעם או זה הטעם? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה\u0005]\u0006 לגבי \u0003חוצה לארץ,\u0004 שאז אין טעם של ישוב ארץ ישראל.","\u0003המשכיר בית לחבירו בימות הגשמים\u0004 — \u0003אינו יכול להוציאו\u0004 מן הבית \u0003מן החג\u0004 (סוכות) \u0003ועד הפסח,\u0004 שאלה הם ימות הגשמים. \u0003בימות החמה\u0004 שיעורו \u0003שלשים יום. ובכרכים, אחד ימות החמה ואחד ימות הגשמים\u0004 — הזמן המקובל לענין שכירות בתים הוא \u0003שנים עשר חדש,\u0004 לפי שקשה יותר להשיג מקום פנוי בכרך. וכן בשכירת \u0003חנויות, אחד\u0004 ב\u0003עיירות ואחד\u0004 ב\u0003כרכים\u0004 — \u0003שנים עשר חדש. רבן שמעון בן גמליאל אומר: חנות של נחתומים ושל צבעים\u0004 זמנם \u0003שלש שנים,\u0004 כפי שיבואר.","שואלים: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 בשוכר ל\u0003ימות הגשמים, דכי אגר איניש ביתא\u0004 \u0005[שכאשר שוכר אדם בית]\u0006 \u0003בימות הגשמים אגר לכולהו\u0004 \u0005[שוכר לכל]\u0006 \u0003ימות הגשמים,\u0004 ואולם ב\u0003ימות החמה נמי\u0004 \u0005[גם כן],\u0006 \u0003דכי אגר איניש ביתא לכולהו\u0004 \u0005[שכאשר שוכר אדם בית\u0006 הרי \u0005לכל]\u0006 \u0003ימות החמה אגר\u0004 \u0005[שכר]!\u0006 \u0003אלא\u0004 יש לומר כך: כאן מדובר בשוכר בית סתם, ולא פירש לכמה זמן שוכרו ו\u0003בימות הגשמים היינו טעמא\u0004 \u0005[זהו הטעם]:\u0006 ש\u0003לא שכיח ביתא למיגר\u0004 \u0005[מצוי בית לשכור]\u0006 ולכן אינו יכול להוציאו אלא בסוף ימות הגשמים, ובימות החמה יכול הוא לעשות זאת.","ומקשים, \u0003אימא סיפא\u0004 \u0005[אמור את סופה\u0006 של משנתנו\u0005]:\u0006 \u0003בכרכים, אחד ימות החמה ואחד ימות הגשמים\u0004 זמנם \u0003שנים עשר חדש, ו\u0004לפי זה, \u0003אילו מלו ליה יומי\u0004 \u0005[אם ימלאו לו ימי]\u0006 \u0003שכירות ב\u0004תוך \u0003ימות הגשמים, מפיק ליה\u0004 \u0005[מוציא אותו]\u0006 בימות הגשמים, \u0003ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לא שכיח ביתא למיגר\u0004 \u0005[מצוי בית לשכור]\u0006 ונמצא שמוציאו בזמן שגורם לו טירחה יתירה!","\u0003אמר רב יהודה:\u0004 כל משנתנו לענין \u0003להודיע קתני\u0004 \u0005[שנה].\u0006 \u0003והכי קאמר\u0004 \u0005[וכך אמר,\u0006 כך יש לומר\u0005]:\u0006 \u0003המשכיר בית לחבירו סתם\u0004 בלא לקבוע לו זמן מסויים — \u0003אין יכול להוציאו בימות הגשמים מחג ועד הפסח אלא אם כן הודיעו שלשים יום מעיקרא\u0004 \u0005[מתחילה]\u0006 עוד בימות החמה.","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנוייה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003כשאמרו\u0004 ודברו אודות זמן של \u0003שלשים\u0004 יום, \u0003וכשאמרו שנים עשר חדש\u0004 — \u0003לא אמרו אלא\u0004 לענין \u0003להודיעו.\u0004 ומוסיפים: \u0003כשם שמשכיר צריך להודיע\u0004 — \u0003כך שוכר צריך להודיע\u0004 שהוא יוצא, \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 המשכיר לשוכר: \u0003אי אודעתן, הוה טרחנא ומותיבנא ביה איניש מעליא\u0004 \u0005[אם היית מודיע לי\u0006 בשעה הראויה, \u0005הייתי טורח ומושיב שם אדם מעולה,\u0006 הגון\u0005].\u0006","\u0003אמר רב אסי:\u0004 אם \u0003נכנס יום אחד בימות הגשמים\u0004 — \u0003אינו יכול להוציאו מן החג עד הפסח.\u0004 ומקשים: \u0003והא אנן\u0004 \u0005[והרי אנחנו]\u0006 \u0003שלשים יום קאמר!\u0004 ומשיבים, \u0003הכי קאמר\u0004 \u0005[כך אמר,\u0006 כך יש לומר\u0005]:\u0006 \u0003אם נכנס יום אחד בימות הגשמים\u0004 ואותו יום הוא \u0003מהני\u0004 \u0005[מאותם]\u0006 \u0003שלשים יום\u0004 — שוב \u0003אינו יכול להוציאו מן החג ועד הפסח.\u0004","\u0003אמר רב הונא: ואם בא לרבות בדמיה,\u0004 אם בעל הבית רוצה להעלות את שכר הדירה — לאחר ההודעה — \u0003מרבה. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן: האי לנקטיה בכובסיה דלשבקיה לגלימא\u0004 \u0005[\u0006הרי \u0005זה\u0006 דומה כמי \u0005שמחזיק אותו באשכיו שיעזוב את גלימתו],\u0006 כלומר, הרי זה אונס גמור, ומה ההבדל אם מוציא אותו במישרין מביתו או מרבה במחיר?! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 לומר אלא לאופן \u0003דאייקור בתי\u0004 \u0005[שנתייקרו הבתים\u0006 בינתיים\u0005]\u0006 וברור שיש לו לבעל הבית הפסד.","ומביאים כמה דינים בנושא זה: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 ברור לנו\u0005]\u0006 שאם \u0003נפל ליה ביתא\u0004 \u0005[לו,\u0006 למשכיר, \u0005הבית]\u0006 שבו הוא עצמו דר — \u0003אמר ליה\u0004 \u0005[אומר לו]\u0006 המשכיר לשוכר: \u0003לא עדיפת מינאי\u0004 \u0005[אין אתה עדיף ממני]\u0006 בזכותך לדירה, וכיון שהגיע סוף השכירות הרי הוא מוציאו, אף שלא הודיעו מראש, לפי שהרי הוא עצמו לא ידע שייפול ביתו ויימצא ללא מקום מגורים.","אם \u0003זבניה\u0004 \u0005[מכרו],\u0006 המשכיר \u0003או אורתיה\u0004 \u0005[הורישו],\u0006 \u0003או יהביה\u0004 \u0005[נתנו]\u0006 \u0003במתנה\u0004 לאחר — \u0003אמר ליה\u0004 \u0005[אומר לו]\u0006 השוכר לבעל הבית החדש: \u0003לא עדיפת מגברא דאתית מיניה\u0004 \u0005[אין אתה עדיף מהאיש שבאת ממנו,\u0006 מכוחו\u0005],\u0006 שכשם שהוא אינו יכול להוציאני אלא בזמן קבוע, גם אתה אינך יכול.","אם \u0003כלליה לבריה\u0004 \u0005[\u0006אם \u0005עשה\u0006 את הבית הזה \u0005בית חתונה\u0006 עבור \u0005בנו],\u0006 \u0003חזינן\u0004 \u0005[רואים אנו]:\u0006 \u0003אי הוה\u0004 \u0005[אם היה]\u0006 \u0003אפשר לאודועיה\u0004 \u0005[להודיעו]\u0006 מראש — \u0003איבעי ליה לאודועיה\u0004 \u0005[היה צריך להודיעו],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא, אמר ליה\u0004 \u0005[אומר לו]\u0006 בעל הבית: \u0003לא עדיפת מינאי\u0004 \u0005[אין אתה עדיף ממני].\u0006","מסופר: \u0003ההוא גברא דזבן ארבא דחמרא\u0004 \u0005[אדם אחד קנה אניה\u0006 טעונה כדי \u0005יין].\u0006 \u0003לא אשכח דוכתא לאותוביה\u0004 \u0005[מצא מקום להעמידה בינתיים].\u0006 \u0003אמר ליה לההיא איתתא\u0004 \u0005[לה לאשה אחת]\u0006 שהיתה לה חלקה ליד הנהר: האם \u0003אית\u0004 \u0005[יש]\u0006 \u0003לך דוכתא לאוגרי\u0004 \u0005[מקום להשכיר לי]?\u0006 \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003לא\u0004 \u0005[לא]\u0006 אין אני רוצה להשכיר. \u0003אזל\u0004 \u0005[הלך]\u0006 ו\u0003קדשה\u0004 להיות אשתו. \u0003יהבה ליה דוכתא לעייליה\u0004 \u0005[נתנה לו מקום להכניס\u0006 את אונייתו\u0005].\u0006 \u0003אזל לביתיה\u0004 \u0005[הלך\u0006 אותו אדם \u0005לביתו]\u0006 ו\u0003כתב לה גיטא\u0004 \u0005[גט],\u0006 \u0003שדר\u0004 \u0005[\u0006ו\u0005שלח]\u0006 \u0003לה,\u0004 מאחר שקיבל מה שרצה. \u0003אזלא איהי, אגרא שקולאי מיניה וביה, אפיקתיה ואותביה בשבילא\u0004 \u0005[הלכה היא, שכרה סבלים מתוך דמי היין שבאניה, הוציאה\u0006 את כל היין משם \u0005והעמידה\u0006 אותו \u0005בשביל\u0006 מחוץ לקרקעה\u0005].\u0006 הגיע הדבר לדין, \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע:\u0004 על מקרה זה אפשר לומר \u0003\"כאשר עשה כן יעשה לו, גמולו ישוב בראשו\"\u0004 (ראה עובדיה א, טו), כי","\u0003לא מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר שאם זו היתה \u0003חצר דלא קיימא לאגרא\u0004 \u0005[שאינה עומדת\u0006 כלל \u0005להשכרה]\u0006 שרשאית היתה לעשות כן, \u0003אלא אפילו\u0004 אם היתה זו \u0003חצר דקיימא לאגרא\u0004 \u0005[שעומדת להשכרה],\u0006 \u0003אמרה ליה\u0004 \u0005[\u0006יכולה היא \u0005לומר לו]:\u0006 \u0003לכולי עלמא ניחא\u0004 \u0005[לכל העולם נוח]\u0006 \u0003לי לאוגורי\u0004 \u0005[להשכיר]\u0006 \u0003ולך לא ניחא\u0004 \u0005[נוח]\u0006 \u0003לי\u0004 משום \u0003דדמית עלי כי אריא ארבא\u0004 \u0005[שנחשב אתה בעיני כאריה אורב]\u0006 שכך נהגת בי ברמאות.","שנינו במשנה ש\u0003רבן שמעון בן גמליאל אומר:\u0004 שחנויות \u0003של נחתומים ושל צבעין\u0004 זמנם \u0003שלש שנים. תנא\u0004 \u0005[שנה]\u0006 החכם בתוספתא והסביר שהטעם הוא \u0003מפני שהקיפן מרובה,\u0004 שכן בעלי החנויות אלה נותנים לקונים בהקפה לזמן ארוך, ואם צריכים הם לעבור ממקום למקום קשה להם לקבל את פרעון הקפותיהם ולייצב את עסקיהם.","\u0003המשכיר בית לחבירו, המשכיר חייב\u0004 לספק לבית \u0003דלת, ונגר\u0004 לנעול \u0003ובמנעול,\u0004 וכן \u0003בכל דבר ש\u0004הוא \u0003מעשה אומן,\u0004 צריך לקחת בעל מלאכה לעשותו. \u0003אבל דבר שאינו מעשה אומן\u0004 אלא כל אדם יכול לעשותו — \u0003השוכר עושהו.\u0004","\u0003הזבל של בעל הבית,\u0004 המשכיר, הוא, \u0003ואין לשוכר\u0004 זכות \u0003אלא\u0004 לגבי האפר \u0003היוצא מן התנור ומן הכירים בלבד.\u0004 וכאשר יבואר בגמרא.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003המשכיר בית לחבירו,\u0004 ה\u0003משכיר חייב להעמיד לו\u0004 לבית שהשכיר \u0003דלתות, לפתוח לו חלונות, לחזק לו תקרה, לסמוך לו קורה\u0004 כדי לחזקו. \u0003ושוכר חייב לעשות\u0004 לבית \u0003סולם, לעשות לו מעקה, לעשות לו מרזב ולהטיח את גגו\u0004 בטיח שלא יכנסו בו גשמים.","\u0003בעו מיניה\u0004 \u0005[שאלו אותו]\u0006 את \u0003רב ששת:\u0004 \u0003מזוזה על מי\u0004 חובה לעשותה, האם על המשכיר, או על השוכר? ותוהים: \u0003מזוזה?! האמר\u0004 \u0005[הרי אמר]\u0006 \u0003רב משרשיא: מזוזה חובת הדר היא;\u0004 שמוטלת המצווה על האדם הדר בדירה, ובוודאי שחייב בה השוכר. \u0003אלא\u0004 השאלה היתה: החובה להכין \u0003מקום\u0004 כדי להכניס בו \u0003מזוזה על מי?\u0004","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב ששת:\u0004 הלא כבר \u0003תניתוה\u0004 \u0005[שניתם אותה]\u0006 במשנתנו; שהרי שנינו בה: \u0003דבר שאין\u0004 הוא \u0003מעשה אומן\u0004 — \u0003השוכר עושהו, והאי נמי לאו\u0004 \u0005[וזה גם כן לא]\u0006 \u0003מעשה אומן הוא,\u0004 שהרי \u0003אפשר\u0004 שהשוכר \u0003הוא\u0004 שיעשה מקום למזוזה, וכגון"],["\u0003בגובתא דקניא\u0004 \u0005[בקנה]\u0006 ושם יכניס את המזוזה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003המשכיר בית לחבירו\u0004 — \u0003על השוכר לעשות לו מזוזה, וכשהוא יוצא\u0004 — \u0003לא יטלנה בידו ויוצא\u0004 אלא משאירה במקומה. ואם השכיר את הבית ל\u0003גוי\u0004 — \u0003נוטלה בידו ויוצא. ומעשה באחד שנטלה בידו ויצא\u0004 — \u0003וקבר אשתו ושני בניו.\u0004","ותוהים: \u0003מעשה לסתור?!\u0004 והרי אמרת שנוטלה ויוצא! \u0003אמר רב ששת:\u0004 הכוונה היא \u0003ארישא\u0004 \u0005[על ראשה\u0006 של הברייתא\u0005]\u0006 שבמקום שנאמר בה שאסור להוציא, יש סכנה בדבר.","שנינו במשנה: כי \u0003הזבל של בעל הבית ואין לשוכר אלא\u0004 הזבל־האפר \u0003היוצא מן התנור ומן הכירים בלבד.\u0004 ושואלים: \u0003במאי עסקינן\u0004 \u0005[במה אנו עוסקים]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר \u0003בחצר דאגיר ליה\u0004 \u0005[ש\u0006היא \u0005מושכרת לו]\u0006 \u0003לשוכר ותורי\u0004 \u0005[ו\u0006גם \u0005השוורים]\u0006 שבחצר הם של \u0003ה\u0004\u0003שוכר\u0004 — \u0003אמאי\u0004 \u0005[מדוע]\u0006 הזבל \u0003של בעל הבית? אלא\u0004 תפרש שמדובר \u0003בחצר דלא אגירא\u0004 \u0005[שאינה מושכרת]\u0006 \u0003לשוכר ותורי\u0004 \u0005[ו\u0006גם \u0005השוורים]\u0006 שבחצר הם של \u0003ה\u0004\u0003משכיר,\u0004 אם כן \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכך הדין!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 לומר אלא \u0003בחצר\u0004 של ה\u0003משכיר\u0004 שאת החצר לא השכיר בעל הבית, \u0003ותורי דאתו מעלמא קמו\u0004 \u0005[ושוורים שבאים מן החוץ עומדים]\u0006 \u0003בה\u0004 ויש בה זבל, ובזה אמרו שכיוון שלא השכיר את החצר הרי כל מה שנמצא בה שייך למשכיר.","ומעירים: הרי זה \u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003לר' יוסי בר' חנינא.\u0004 ש\u0003אמר ר' יוסי בר' חנינא: חצרו של אדם קונה לו שלא מדעתו.\u0004 ואף כאן, למרות שבעל החצר לא עשה מעשה לקנות את הזבל, כיוון שנמצא בחצרו הרי כל מה שהיה בחצר נקנה לו ממילא.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך: \u0003אם אמר\u0004 אדם \u0003\"כל מציאות שיבאו לתוכו\u0004 של ביתי או חצרי \u0003היום תקנה לי חצרי\"\u0004 — \u0003לא אמר כלום\u0004 ואמירה זו אינה מקנה לו כל זכות. \u0003ואם איתא להא\u0004 \u0005[יש,\u0006 מקובל, \u0005זה]\u0006 ש\u0003אמר ר' יוסי בר' חנינא\u0004 ש\u0003חצרו של אדם קונה לו שלא מדעתו, אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא אמר כלום?\u0004","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003בחצר שאינה משתמרת,\u0004 שהחצר פרוצה ודבר הנמצא בה אינו נשמר, ובחצר זו אין נקנה לו מה שבחצר.","ומקשים: \u0003אי הכי אימא סיפא\u0004 \u0005[אם כך, אמור את סופה\u0006 של המשנה\u0005]:\u0006 אם \u0003יצא לו שם מציאה בעיר,\u0004 שנודע לבריות שמצא מציאה בחצרו — הרי \u0003דבריו קיימים\u0004 למרות שלא עשה מעשה. \u0003ואי\u0004 \u0005[ואם]\u0006 מדובר \u0003בחצר שאינה משתמרת,\u0004 \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003יצא לו שם מציאה בעיר מאי הוי\u0004 \u0005[מה היה]\u0006 על ידי כך?","ומשיבים: \u0003כיון\u0004 ש\u0003יצא לו שם מציאה בעיר\u0004 — \u0003מיבדל בדילי אינשי מינה\u0004 \u0005[אנשים נבדלים ממנה]\u0006 וסבורים שהמציאה בחצר שייכת לו, \u0003והויא לה\u0004 \u0005[והרי דינה]\u0006 \u0003כחצר המשתמרת.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך: \u0003זבל היוצא מן התנור ומן הכירים וה\u0004דבר שהוא \u0003קולט מן האויר\u0004 — \u0003הרי הוא שלו,\u0004 של השוכר. \u0003ושברפת ושבחצר\u0004 — \u0003של בעל הבית. ואם איתא להא\u0004 \u0005[ישנה,\u0006 יש בסיס \u0005לזו]\u0006 ש\u0003אמר ר' יוסי בר' חנינא, חצרו של אדם קונה לו שלא מדעתו,\u0004 אם כן \u0003קולט מאויר אמאי\u0004 \u0005[מדוע]\u0006 \u0003הרי הוא שלו,\u0004 של השוכר? הלא ה\u0003אויר חצרו\u0004 של המשכיר \u0003הוא!\u0004","\u0003אמר אביי:\u0004 כאן מדובר כגון ש\u0003מדביק כלי בשולי פרה\u0004 שהניח את הכלי סמוך לפרה והטילה גלליה ישר לכלי, ולא שהיה מונח סתם באויר החצר.","\u0003רבא אמר: אויר שאין סופו לנוח,\u0004 כלומר, כל דבר המצוי בחלל (באויר), שאין סופו בהכרח לנוח במקום — \u0003לאו\u0004 \u0005[לא]\u0006 \u0003כמונח דמי\u0004 \u0005[\u0006הוא \u0005נחשב].\u0006","ושואלים: \u0003ומי פשיטא ליה\u0004 \u0005[והאם פשוט לו]\u0006 \u0003לרבא\u0004 ענין זה שכך הוא הדין? \u0003והא מיבעי בעי לה\u0004 \u0005[והרי\u0006 ידוע כי שאל \u0005והסתפק בכך],\u0006 \u0003דבעי\u0004 \u0005[ששאל]\u0006 \u0003רבא\u0004 שאלה זו: \u0003זרק ארנקי\u0004 (ארנק, כיס מעות) והפקירו \u0003בפתח זה\u0004 של הבית \u0003ויצאתה\u0004 (יצאה) \u0003בפתח זה, מהו\u0004 הדין? האם נחשב כאילו היה מונח בבית וזכה בו בעל הבית? והצד העקרוני בבעיה, האם אומרים אנו ש\u0003אויר\u0004 (דבר שבחלל) \u0003שאין סופו לנוח\u0004 האם \u0003כמונח דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 \u0003או לאו\u0004 \u0005[לא]\u0006 \u0003כמונח דמי\u0004 \u0005[\u0006הוא \u0005נחשב]?\u0006","ומשיבים: יש מקום לחלק בין המקרים; \u0003התם לא מיפסק ולא מידי\u0004 \u0005[שם אין דבר מפסיק]\u0006 ולכן יש מקום לשאול, \u0003הכא מיפסק\u0004 \u0005[כאן מפסיק]\u0006 ה\u0003כלי\u0004 שבו נקלט הדבר ולכן כאן הדין שונה.","שנינו בברייתא שזבל \u0003שברפת ושבחצר הרי אלו של בעל הבית.\u0004 ותוהים: האם עוסק התנא ב\u0003תרתי\u0004 \u0005[שני]\u0006 דינים, גם בחצר שאינה מושכרת, וגם בזו המושכרת (שהרי הזכיר ענין בעל הבית)?","\u0003אמר אביי:\u0004 אכן עוסק התנא גם בחצר מושכרת, ו\u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003ושברפת שבחצר\u0004 המושכרת \u0003הרי אלו\u0004 הזבלים שנמצאים בתוכה הם \u0003של בעל הבית,\u0004 שאף שהשכיר לו את החצר לא השכיר לו את הרפת. \u0003אמר רב אשי: זאת אומרת המשכיר חצירו סתם\u0004 ולא פירש — \u0003לא השכיר רפת שבה\u0004 והיא נשארת ברשותו.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על שיטת ר' יוסי בר' חנינא, ממה ששנינו: \u0003יוני שובך ויוני עלייה חייבות בשילוח\u0004 הקן, שכן הן נחשבות כיוני בר ואם מצא אם על הבנים — חייב לשלח את האם (כאמור בדברים כב, ו–ז), \u0003ואסורות בגזל\u0004 לאדם אחר \u0003מפני דרכי שלום.\u0004","\u0003ואם איתא להא\u0004 \u0005[ואם ישנו לזה]\u0006 ש\u0003אמר ר' יוסי בר' חנינא: חצרו של אדם קונה לו שלא מדעתו,\u0004 אם כן שלו הם. \u0003קרי\u0004 \u0005[קרא]\u0006 \u0003כאן\u0004 את האמור בדרשת הכתוב \u0003\"כי יקרא\u0004 לפניך\u0003\"\u0004 (דברים כב, ו) — \u0003פרט למזומן\u0004 ואם כל שבחצרו שלו הוא, הרי אין כאן חובת שילוח!","\u0003אמר רבא,\u0004 כך יש לומר: ה\u0003ביצה\u0004 כבר \u0003ביציאת רובה\u0004 מן הציפור \u0003הוא דאיחייבה לה\u0004 \u0005[ש\u0006גורמת \u0005לה להתחייב]\u0006 \u0003בשילוח, ו\u0004אולם \u0003מיקנא לא קניא\u0004 \u0005[לקנות אותה\u0006 כרכושו \u0005אינה נקנית]\u0006 לו לבעל החצר \u0003עד\u0004 שלא \u0003נפלה לחצרו\u0004 ממש, \u0003וכי קתני\u0004 \u0005[וכאשר שנה]\u0006 \u0003\"חייבות בשילוח\"\u0004 — הכוונה היא \u0003מקמי דתיפול\u0004 \u0005לפני שנפלה]\u0006 \u0003לחצירו.\u0004","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שעדיין אינו קניינו \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003אסורות משום גזל!\u0004 ומשיבים: איסור גזל זה הוא \u0003אאמן\u0004 \u0005[על אמן]\u0006 של הביצים הללו.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 \u0003לעולם\u0004 מדובר על ה\u0003ביצים,\u0004 ואף על פי כן \u0003ומדנפיק רובה דעתיה עילוה\u0004 \u0005[וכיון שיצא רובה\u0006 של הביצה כבר \u0005דעתו עליה]\u0006 ואם נוטלה מבעליה משום דרכי שלום הרי זה גזל.","ומעירים: \u0003והשתא\u0004 \u0005[ועכשיו]\u0006 שנאמרה הלכה זו ש\u0003אמר רב יהודה אמר רב: אסור לזכות בביצים כל זמן שהאם רובצת עליהם, שנאמר: \"שלח תשלח את האם\" והדר\u0004 \u0005[ואחר כך]\u0006 \u0003\"\u0004ו\u0003את הבנים תקח לך\"\u0004 (שם ז) אינך נזקק לתירוצים אלה, אלא \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 ש\u0003נפלה לה\u0004 הביצה \u0003לחצרו, כל היכא דאיהו מצי זכי ליה\u0004 \u0005[מקום,\u0006 דבר, \u0005שהוא\u0006 בעצמו \u0005היה יכול לזכות בו]\u0006 באותה שעה — \u0003חצרו\u0004 עצמה \u0003זכיא ליה\u0004 — \u0005[זוכה לו],\u0006 \u0003וכל היכא דאיהו לא מצי זכי ליה\u0004 \u0005[היכן שהוא אינו יכול לזכות]\u0006 — \u0003חצרו נמי לא זכיא ליה\u0004 \u0005[גם כן אינה\u0006 יכולה \u0005לזכות לו].\u0006","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש מדוע נאמר כי \u0003אסורות בגזל מפני דרכי שלום\u0004 בלבד? הרי, \u0003אי\u0004 \u0005[אם]\u0006 מדובר באופן שכבר \u0003שלחה\u0004 לאם ולקח לעצמו את הביצים — הלא \u0003גזל מעליא\u0004 \u0005[מעולה,\u0006 גמור\u0005]\u0006 \u0003הוא,\u0004 \u0003אי\u0004 \u0005[\u0006ו\u0005אם]\u0006 מדובר באופן ש\u0003לא שלחה\u0004 עדיין — \u0003הא בעי שלוחה\u0004 \u0005[הרי צריך\u0006 עדיין \u0005לשלוח אותה]\u0006 לפני שיהא מותר לזכות בביצים?","ומתרצים: מדובר כאן \u0003בקטן דלאו בר\u0004 \u0005[שלא בן]\u0006 \u0003שילוח הוא,\u0004 שאינו חייב במצות שילוח. ושואלים: אם כן, וכי, \u0003קטן בר\u0004 \u0005[בן]\u0006 \u0003דרכי שלום הוא?\u0004 אם היה זה קטן מה דרכי שלום יש בו? ומשיבים, \u0003הכי קאמר\u0004 \u0005[כך אמר,\u0006 כך יש לומר\u0005]:\u0006 \u0003אביו של קטן חייב להחזיר לו\u0004 לבעל החצר \u0003מפני דרכי שלום.\u0004","\u0003המשכיר בית לחבירו לשנה\u0004 אחת, אם \u0003נתעברה השנה\u0004 — \u0003נתעברה לשוכר\u0004 שאיננו משלם עבור החודש הנוסף. אם \u0003השכיר לו\u0004 את הבית \u0003לחדשים,\u0004 ולאחר מכן \u0003נתעברה השנה\u0004 — \u0003נתעברה למשכיר,\u0004 והוא מקבל שכר עבור החודש הזה.","מסופר: \u0003מעשה בציפורי באחד ששכר מרחץ מחבירו\u0004 והתנה שהוא שוכר ממנו \u0003בשנים עשר\u0004 דינר \u0003זהב לשנה, מדינר זהב לחדש,\u0004 ונתעברה השנה"],["\u0003ובא\u0004 ה\u0003מעשה לפני רבן שמעון בן גמליאל ולפני ר' יוסי. ואמרו: יחלוקו את חדש העיבור.\u0004","ושואלים: הלא במשנה נראה כי חודש העיבור הוא כולו או לשוכר או למשכיר, והמעשה שהובא הוא \u0003מעשה לסתור?!\u0004 ומשיבים: \u0003חסורי מחסרא והכי קתני\u0004 \u0005[חסרה המשנה וכך היא שנויה]:\u0006 \u0003ואם אמר לו: בשנים עשר זהובים לשנה מדינר זהב לחדש\u0004 — הרי זו לשון המשתמעת לשני פנים, ו\u0003יחלוקו. ומעשה נמי\u0004 \u0005[גם כן]\u0006 \u0003בציפורי באחד ששכר מרחץ מחבירו בשנים עשר זהובים לשנה מדינר זהב לחדש, ובא\u0004 ה\u0003מעשה לפני רבן שמעון בן גמליאל ולפני ר' יוסי, ואמרו,\u0004 כך פסקו: \u0003יחלוקו את חדש העיבור.\u0004","\u0003אמר רב: אי הואי התם הוה יהיבנא ליה כוליה\u0004 \u0005[אם הייתי שם הייתי נותן את הכל]\u0006 \u0003למשכיר.\u0004","ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 בכך שהוא מחזיק בשלל \u0003\"תפוס לשון אחרון\"!\u0004","כיון שצד זה בתנאי היה לשון אחרון — הוא הקובע, ואולם \u0003הא\u0004 \u0005[הרי]\u0006 כבר \u0003אמר רב\u0004 דבר זה \u0003חדא זימנא\u0004 \u0005[פעם אחת],\u0006 ש\u0003אמר רב הונא: אמרי בי\u0004 \u0005[אמרו בבית\u0006 מדרשו\u0005]\u0006 של \u0003רב:\u0004 שנים שהסכימו על מחירו של דבר, ואמרו לשון כפולה: \u0003אסתירא\u0004 (שהוא שווה תשעים ושש מעות) \u0003מאה מעי\u0004 \u0005[מאה מעות]\u0006 — הרי צריך לתת \u0003מאה מעי\u0004 \u0005[מאה מעות],\u0006 ואם אמרו \u0003מאה מעי אסתירא\u0004 \u0005[מאה מעות אסתירא]\u0006 — הרי הוא משלם \u0003אסתירא,\u0004 לפי הכלל של \"תפוס לשון אחרון\". ואם כן מדוע חזר רב ואמר שוב אותם הדברים?","ומשיבים: \u0003אי מהתם הוה אמינא\u0004 \u0005[אם משם הייתי אומר]\u0006 שאין זה משום \"תפוס לשון אחרון\" אלא משום ש\u0003פרושי קא מפרש\u0004 \u0005[פירוש הוא שמפרש\u0006 את דבריו\u0005],\u0006 שמסביר באילו מעות ובאיזו אסתירא מדובר, על כן \u0003קמשמע לן\u0004 \u0005[השמיע לנו]\u0006 שהולכים אחרי לשון אחרון אפילו כשיש סתירה בין הלשונות.","\u0003ושמואל אמר\u0004 הסבר אחר למשנה: \u0003בבא באמצע\u0004 ה\u0003חדש עסקינן\u0004 \u0005[עוסקין אנו],\u0006 שכיון שבפועל כבר היה חציו בחזקת השוכר, לכן נותנים לו חצי חודש. \u0003אבל\u0004 אם \u0003בא\u0004 הדיון \u0003בתחלת חדש\u0004 — \u0003כוליה\u0004 \u0005[כולו]\u0006 \u0003למשכיר, בא בסוף חדש\u0004 — \u0003כוליה\u0004 \u0005[כולו]\u0006 \u0003לשוכר,\u0004 שכבר זכה בו.","ושואלים: \u0003מי\u0004 \u0005[\u0006ו\u0005האם]\u0006 \u0003אמר שמואל\u0004 כי \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 \u0003\"תפוס לשון אחרון\"? והא\u0004 \u0005[והרי]\u0006 \u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 האומר לחבירו \u0003כור בשלשים\u0004 דינר \u0003אני מוכר לך\u0004 — \u0003יכול לחזור בו אפילו בסאה אחרונה,\u0004 שכל הכור הוא כיחידה אחת, וכל עוד לא משכו כולו — לא נגמר המכר! ואם אמר: \u0003כור בשלשים, סאה בסלע אני מוכר לך\u0004 — נמצא שכל סאה היא כקנין לעצמו, ו\u0003ראשון ראשון קנה,\u0004 שכל סאה שקיבל הרי זה משך וקנה אותה.","ומשיבים: \u0003התם טעמא מאי\u0004 \u0005[שם מהו הטעם]\u0006 שקנה — לא משום שאנו הולכים אחר לשון אחרון, אלא \u0003משום דתפיס\u0004 \u0005[שתופס]\u0006 את גוף הדבר הנקנה, \u0003הכא נמי קא תפיס\u0004 \u0005[כאן גם כן\u0006 במרחץ \u0005תופס]\u0006 שאין שמואל בטוח מה היא הלשון המחייבת, והוא הולך רק לפי החזקה בלבד.","\u0003ורב נחמן אמר: קרקע בחזקת בעליה קיימת\u0004 וכיון שכך נמצא המרחץ בחזקת הבעלים ובכל מקום של ספק — הכל למשכיר. ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו\u0006 בכך\u0005]\u0006 — \u0003\"תפוס לשון אחרון\"\u0004 שפוסקים כאילו אמר רק \"דינר זהב לחודש\" אם כן \u0003היינו\u0004 \u0005[זהו]\u0006 שאמר \u0003רב,\u0004 ומה חידש רב נחמן? ומשיבים: אינו כן, שאף שלהלכה למעשה אינם חולקים, מכל מקום לדעת רב נחמן \u0003אף על גב דאפיך מיפך\u0004 \u0005[אף על פי\u0006 שהיה \u0005הופך]\u0006 את התנאי ואומר \"מדינר זהב לחודש\" — בתחילה לא היה הדין משתנה כי לא אחרי הלשון אנו הולכים אלא אחרי החזקה.","\u0003בעו מיניה\u0004 \u0005[שאלו אותו]\u0006 את \u0003ר' ינאי:\u0004 במקרה שה\u0003שוכר אמר: נתתי\u0004 כבר את התשלום, \u0003ומשכיר אמר: לא נטלתי\u0004 — \u0003על מי\u0004 מהם \u0003להביא ראיה?\u0004","ושואלים: \u0003אימת\u0004 \u0005[מתי\u0006 היה הדבר\u0005]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 היה זה \u0003בתוך זמנו\u0004 (בתוך תקופת הפרעון) — הלא כבר \u0003תנינא\u0004 \u0005[שנינו],\u0006 \u0003אי\u0004 \u0005[\u0006ו\u0005אם]\u0006 היה זה \u0003לאחר זמנו\u0004 — \u0003תנינא\u0004 \u0005[שנינו].\u0006 \u0003דתנן\u0004 \u0005[ש\u0006שכן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מת האב בתוך שלשים יום\u0004 ללידת בנו הבכור — הרי זה \u0003בחזקת שלא נפדה\u0004 הבן \u0003עד שיביא ראיה שנפדה.\u0004 מת \u0003לאחר שלשים יום\u0004 — הריהו \u0003בחזקת שנפדה, עד שיאמרו לו שלא נפדה,\u0004 ואם כן אף לענין שוכר ומשכיר כך הדין.","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא כשהיה הדין \u0003ביומא דמשלם זמניה\u0004 \u0005[ביום ש\u0006בו בדיוק \u0005נשלם זמנו].\u0006 והשאלה היא: \u0003מי עביד איניש דפרע ביומא דמשלם זמניה\u0004 \u0005[האם עשוי אדם לפרוע\u0006 בדיוק \u0005ביום שנשלם הזמן],\u0006 \u0003או לא?\u0004","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003ר' יוחנן\u0004 לשואלים: כבר \u0003תניתוה\u0004 \u0005[שניתם אותה],\u0006 שיש לנו תשובה לדבר מן המשנה,"],["\u0003שכיר\u0004 אם תובע שכרו ממעבידו \u0003בזמנו,\u0004 ביום לאחר גמר המלאכה, הריהו \u0003נשבע\u0004 שעדיין לא קיבל שכרו \u0003ונוטל,\u0004 שאף כי כרגיל הנתבע הוא הנשבע שאינו חייב, כאן תיקנו שהתובע־השכיר הוא שישבע ויטול.","ומכאן נדייק: \u0003שכיר הוא דרמו רבנן\u0004 \u0005[שהטילו חכמים]\u0006 חובת \u0003שבועה עליה\u0004 \u0005[עליו]\u0006 \u0003משום\u0004 ש\u0003בעל הבית טרוד בפועליו\u0004 ומחמת טרחה פעמים נדמה לו ששילם כשלא שילם עדיין. \u0003אבל הכא\u0004 \u0005[כאן]\u0006 \u0003שוכר מהימן\u0004 \u0005[נאמן]\u0006 \u0003בשבועה\u0004 ככל מי שנתבע לשלם ואין כנגדו ראיה גמורה.","\u0003אמר רבא אמר רב נחמן: האי מאן דאוגר ליה ביתא לחבריה\u0004 \u0005[מי שהשכיר לו בית לחבירו]\u0006 \u0003לעשר שנין\u0004 \u0005[שנים]\u0006 \u0003וכתב ליה שטרא\u0004 \u0005[לו שטר]\u0006 ולא נכתב בשטר זה תאריך, ולאחר זמן בא בעל הבית לשוכר \u0003ואמר ליה\u0004 \u0005[לו]:\u0006 \u0003נקיטת\u0004 \u0005[החזקת בו]\u0006 כבר \u0003חמש שנין\u0004 \u0005[שנים]\u0006 אף שהשכיר אומר שדר רק שלוש שנים — \u0003מהימן\u0004 \u0005[נאמן\u0006 המשכיר\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא מדפתי לרבינא: אלא מעתה\u0004 לפי עקרון זה, אילו \u0003אוזפיה\u0004 \u0005[הלוה לו]\u0006 \u0003מאה זוזי בשטרא\u0004 \u0005[דינרים בשטר],\u0006 \u0003ואמר ליה\u0004 \u0005[לו]\u0006 הלווה: \u0003\"פרעתיך\u0004 כבר \u0003פלגא\u0004 \u0005[מחצית]\u0006 הסכום \u0003\"\u0004— \u0003הכי נמי דמהימן\u0004 \u0005[כך גם כן\u0006 יהיה הדין \u0005שנאמן]?\u0006","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי השתא\u0004 \u0005[כיצד אתה משווה]?!\u0006 \u0003התם\u0004 \u0005[שם]\u0006 — \u0003שטר\u0004 בהלוואה \u0003לגוביינא קאי\u0004 \u0005[לגביה\u0006 הוא \u0005עומד],\u0006 שהשטר הוא הראיה והאופן בו יגבה את כספו, \u0003אם איתא דפרעיה\u0004 \u0005[אם אמנם פרעו]\u0006 — \u0003איבעי ליה למכתבא אגביה\u0004 \u0005[היה צריך לכתוב על גבו]\u0006 שנפרע, \u0003אי נמי מיכתב עליה תברא\u0004 \u0005[או גם כן לכתוב לו\u0006 למשלם שובר\u0005].\u0006 \u0003אבל הכא\u0004 \u0005[כאן]\u0006 בהשכרה, \u0003אמר ליה\u0004 \u0005[\u0006יכול הוא \u0005לומר לו]:\u0006 \u0003האי דכתיבי\u0004 \u0005[זה שכתבתי]\u0006 \u0003לך שטרא\u0004 — \u0003כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא תחזק עליה\u0004 \u0005[\u0006תטען \u0005חזקה עליו]\u0006 והשטר עצמו איננו משמש הוכחה אלא לכך.","\u0003אמר רב נחמן: שואל אדם בטובו לעולם,\u0004 כלומר, מי ששואל חפץ מחבירו ואומר לו \"השאילני אותו בטובו\" יכול להשתמש בו לעולם, ואין לכך כל גבול קבוע.","\u0003אמר רב מרי ברה\u0004 \u0005[בנה]\u0006 של \u0003בת שמואל: והוא דקני מיניה\u0004 \u0005[שעשה קנין]\u0006 ועומד החפץ ברשותו, ואם לאו — צריך להחזירו. \u0003אמר רב מרי בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אשי:\u0004 ויכול להשתמש כל כך עד ש\u0003מהדר ליה קתיה\u0004 \u0005[שיחזיר לו את הקת\u0006 בלבד\u0005].\u0006","","בדומה לזה \u0003אמר רבא: האי מאן דאמר ליה לחבריה\u0004 \u0005[מי שאומר לו לחבירו]:\u0006 \u0003\"אושלן מרא למירפק ביה האי פרדיסא\"\u0004 \u0005[השאל לי מעדר לעדור בו פרדס זה]\u0006 — \u0003רפיק ביה ההוא פרדיסא\u0004 \u0005[עודר בו אותו פרדס].\u0006 אמר לו השאל לי את המעדר לעדור בו \u0003\"פרדיסא\"\u0004 \u0005[\u0006\u0005פרדס]\u0006 — \u0003רפיק ביה\u0004 \u0005[עודר בו]\u0006 \u0003כל פרדיסא דבעי\u0004 \u0005[פרדס ש\u0006הוא \u0005רוצה],\u0006 ואפילו פרדס גדול. אמר לו \u0003\"פרדיסי\u0004 \u0005[פרדסים]\u0006 אני רוצה לעדור בהם \u0003\",\u0004 ולא קבע גבול — \u0003רפיק ואזיל\u0004 \u0005[עודר\u0006 בו \u0005והולך]\u0006 \u0003כל פרדיסי דאית ליה ומהדר ליה קתיה\u0004 \u0005[הפרדסים שיש לו ומחזיר לו את קתו].\u0006","כיוצא בו \u0003אמר רב פפא האי מאן דאמר ליה לחבריה\u0004 \u0005[מי שאומר לו לחבירו]:\u0006 \u0003\"אושלן האי גרגותא\"\u0004 \u0005[השאל לי את הבאר הזו]\u0006 \u0003ונפלה\u0004 התמוטטו כתלי הבאר — \u0003לא בני לה\u0004 \u0005[אינו\u0006 רשאי \u0005לבנות אותה],\u0006 שהרי שאל ממנו באר זו. אם אמר לו סתם \u0003\"גרגותא\"\u0004 \u0005[באר]\u0006 \u0003ונפלה\u0004 — \u0003בני לה\u0004 \u0005[בונה אותה\u0006 מחדש\u0005],\u0006 שהרי אמר לו \"באר\" ולא פירש. אם אומר לו \u0003\"בי גרגותא\"\u0004 \u0005[מקום באר\u0006 השאל לי\u0005]\u0006 — \u0003כרי ואזיל\u0004 \u0005[כורה והולך]\u0006 \u0003כמה גרגותי בארעיה\u0004 \u0005[בארות באדמתו]\u0006 \u0003עד דמתרמי ליה\u0004 \u0005[שמזדמן לו\u0006 מקום שיש בו מים\u0005].\u0006 ומעירים: \u0003וצריך למיקני מיניה\u0004 \u0005[לעשות קנין ממנו,\u0006 מבעל השדה\u0005]\u0006 כדי שהסכם זה יהיה מוחלט, שאם לא כן יוכל בעל השדה לחזור בו מתי שירצה.","\u0003המשכיר בית לחבירו ונפל\u0004 הבית — \u0003חייב\u0004 המשכיר \u0003להעמיד לו בית\u0004 אחר כל זמו שכירותו. \u0003היה\u0004 הבית \u0003קטן\u0004 — \u0003לא יעשנו גדול,\u0004 שהשוכר יוכל לומר שאינו רוצה בכך, ואם היה \u0003גדול\u0004 — \u0003לא יעשנו קטן.\u0004 היה זה בית \u0003אחד\u0004 — \u0003לא יעשנו שנים, שנים\u0004 — \u0003לא יעשנו אחד. לא יפחות מן החלונות ולא יוסיף עליהם אלא מדעת שניהם.\u0004","\u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 מדובר באופן ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 המשכיר: הריני משכיר לך \u0003\"בית זה\".\u0004 אם כן כיון ש\u0003נפל אזל ליה\u0004 \u0005[הלך לו\u0006 ובטל ביתו\u0005]\u0006 ושוב אין כאן טענה. \u0003אי\u0004 \u0005[אם]\u0006 מדובר באופן ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 המשכיר: \u0003\"\u0004אני משכיר לך \u0003בית סתם\",\u0004 \u0003אחד אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא יעשנו שנים,\u0004 וכן \u0003קטן אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא יעשנו גדול?\u0004 שהרי לא פירש דבר בדבר הבית המושכר!","\u0003אמר ריש לקיש:\u0004 מדובר באופן ש\u0003אמר ליה\u0004 \u0005[לו\u0006 המשכיר: \u0003\"בית שאני משכיר לך מדת ארכו כך וכך\",\u0004 ולכן חייב לספק לו בית כמו זה.","ושואלים: \u0003אי הכי מאי למימרא\u0004 \u0005[אם כן מה\u0006 יש \u0005לומר],\u0006 שאם היה זה תנאי מפורש — ברור שאינו יכול לשנותו!","\u0003אלא, כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ריש לקיש,\u0004 מדובר באופן ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 המשכיר: \u0003\"בית כזה אני משכיר לך\".\u0004 ושואלים: \u0003ואכתי מאי למימרא\u0004 \u0005[ועדיין מה יש לומר]\u0006 בכך? שאם כן התנאי ברור! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 לומר אלא לאופן \u0003דקאי אגודא דנהרא\u0004 \u0005[שעומד\u0006 הבית \u0005על שפת הנהר].\u0006 \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"כזה\"\u0004 שתאמר — שנתכוון \u0003דקאי אגודא דנהרא\u0004 \u0005[שעומד על שפת הנהר]\u0006 אבל לאו דווקא לגבי שאר הפרטים, ועל כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאם תאמר \"כזה\" התחייב שיהיה כזה בכל הפרטים.","","\u0003המקבל שדה מחבירו\u0004 לעבד אותו, בין שעשה זאת כאריס שמקבל חלק מסויים מתנובת השדה, או שחכר את השדה תמורת תשלום קבוע, \u0003מקום שנהגו\u0004 מקבלי השדה \u0003לקצור\u0004 את התבואה — \u0003יקצור,\u0004 במקום שנהגו \u0003לעקור\u0004 את התבואה שצמחה ולא לחתכה במגל וחרמש — \u0003יעקור,\u0004 מקום שנהגו \u0003לחרוש אחריו\u0004 — \u0003יחרוש, הכל כמנהג המדינה. כשם שחולקין\u0004 בעל השדה והאריס \u0003בתבואה כך חולקין בתבן ובקש, כשם שחולקין ביין כך חולקין\u0004"],["\u0003בזמורות ובקנים, ושניהם,\u0004 גם בעל הבית וגם האריס יחד, \u0003מספקין את הקנים\u0004 הללו לסמוך את הגפנים.","\u0003תנא\u0004 \u0005[שנה]\u0006 החכם בתוספתא: \u0003מקום שנהגו לקצור\u0004 — \u0003אינו רשאי לעקור, לעקור\u0004 — \u0003אינו רשאי לקצור, ושניהם מעכבין זה על זה.\u0004","ומפרשים: \u0003לקצור אינו רשאי לעקור,\u0004 כי \u0003האי אמר\u0004 \u0005[זה\u0006 הרוצה לקצור \u0005אומר]:\u0006 \u0003בעינא דתתבן לי ארעאי\u0004 \u0005[רצוני\u0006 שישאר \u0005התבן בתוך אדמתי]\u0006 כזבל, \u0003ו\u0004מאידך \u0003האי אמר\u0004 \u0005[זה\u0006 האריס \u0005אומר]:\u0006 \u0003לא מצינא\u0004 \u0005[איני יכול]\u0006 שיש טירחה בעקירה. וכן \u0003לעקור אינו רשאי לקצור,\u0004 כי \u0003האי אמר\u0004 \u0005[זה,\u0006 בעל הבית, \u0005אומר]:\u0006 \u0003בעינא דתינקר ארעאי\u0004 \u0005[רצוני שתתנקה אדמתי]\u0006 מקש ושאר חומרים, \u0003ו\u0004מאידך \u0003האי אמר\u0004 \u0005[זה\u0006 האריס \u0005אומר]:\u0006 \u0003בעינא תיבנא\u0004 \u0005[רוצה אני את התבן]\u0006 להשתמש בו.","ושואלים: \u0003שניהם מעכבים זה על זה למה לי\u0004 לומר, הלא כבר אמרו דברים אלה! ומסבירים: בלשון \u0003\"מה טעם\" קאמר\u0004 \u0005[אמר]:\u0006 \u0003מה טעם\u0004 במקום שנהגו \u0003לקצור אינו רשאי לעקור,\u0004 או במקום שנהגו \u0003לעקור אינו רשאי לקצור\u0004 — \u0003משום\u0004 ש\u0003שניהם מעכבין זה על זה\u0004 ויש דברים שונים בדבר.","שנינו במשנה שאם המנהג \u0003לחרוש אחריו\u0004 — \u0003יחרש.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שאינו רשאי לשנות! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא \u0003באתרא דלא מנכשי\u0004 \u0005[במקום שאין\u0006 נוהגים \u0005לנכש]\u0006 את העשבים הרעים, \u0003ואזל איהו ונכיש\u0004 \u0005[והלך הוא,\u0006 האריס, \u0005וניכש].\u0006 \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003אמר ליה\u0004 \u0005[\u0006יכול האריס \u0005לומר לו]:\u0006 \u0003האי דנכישנא\u0004 \u0005[זה שניכשתי]\u0006 את העשבים היה זה \u0003אדעתא\u0004 \u0005[על דעת]\u0006 ש\u0003לא כריבנא לה\u0004 \u0005[אחרוש אותה,\u0006 את האדמה\u0005]\u0006 לאחר מכן, ועל כן \u0003קא משמע לן דאיבעי ליה לפרושי ליה\u0004 \u0005[השמיע לנו שהיה צריך לפרש לו],\u0006 ואם לא התנה במפורש — אינו רשאי לשנות.","כלל שני שנינו במשנה: \u0003הכל כמנהג המדינה.\u0004 ושואלים: \u0003\"הכל\" לאתויי מאי\u0004 \u0005[להביא,\u0006 להוסיף את \u0005מה]?\u0006 ומשיבים: \u0003לאתויי הא דתנו רבנן\u0004 \u0005[להביא\u0006 את \u0005זו ששנו חכמים]:\u0006 \u0003מקום שנהגו להשכיר אילנות\u0004 הגדלים בתוך השדה, שאף שאין האריס מעבדם מקבל הוא חלק מפירותיהם \u0003על גבי\u0004 (יחד עם) ה\u0003קרקע\u0004 — \u0003משכירין, מקום שאין נהגו להשכיר\u0004 — \u0003אין משכירין.\u0004","ושואלים: \u0003מקום שנהגו להשכיר משכירין\u0004 — \u0003פשיטא\u0004 \u0005[פשוט,\u0006 ומובן מאליו\u0005]!\u0006 ומשיבים: \u0003לא צריכא,\u0004 \u0005[נצרכה]\u0006 אלא למקרה \u0003דכולי עלמא יהבי בתילתא\u0004 \u0005[שכל העולם,\u0006 הכל, נוהגים \u0005לתת\u0006 לאריס שדה \u0005בשליש\u0006 מיבול התבואה\u0005],\u0006 \u0003ואזל איהו ויהביה בריבעא\u0004 \u0005[והלך הוא,\u0006 בעל שדה זה, \u0005ונתן אותו ברבע].\u0006 \u0003מהו דתימא\u0004 \u0005[שתאמר],\u0006 \u0003דאמר ליה\u0004 \u0005[ש\u0006יכול בעל השדה \u0005לומר לו]:\u0006 \u0003האי דבצרי\u0004 \u0005[זה שהפחתתי]\u0006 \u0003לך\u0004 מחלקי, היה זה \u0003אדעתא\u0004 \u0005[על דעת]\u0006 ש\u0003לא יהיבנא\u0004 \u0005[אתן]\u0006 \u0003לך\u0004 מפירות ה\u0003אילנות,\u0004 ועל כן \u0003קא משמע לן דאיבעי ליה לפרושי ליה\u0004 \u0005[השמיע לנו שהיה צריך לפרש לו].\u0006","שנינו בברייתא שב\u0003מקום שנהגו שלא להשכיר\u0004 — \u0003אין משכירין.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא לאופן \u0003דכולי עלמא מקבלי בריבעא, ואזל איהו\u0004 \u0005[שהכל מקבלים ברבע\u0006 מן היבול \u0005והלך הוא,\u0006 אותו אריס\u0005]\u0006 \u0003וקיבלה בתילתא\u0004 \u0005[בשליש\u0006\u0005].\u0006 \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003אמר ליה\u0004 \u0005[ש\u0006יכול האריס \u0005לומר לו]:\u0006 \u0003האי דטפאי\u0004 \u0005[זה שהוספתי]\u0006 \u0003לך\u0004 היה זה \u0003אדעתא דיהבת\u0004 \u0005[על דעת שתתן]\u0006 \u0003לי\u0004 גם \u0003באילנות,\u0004 על כן \u0003קא משמע לן דאיבעי ליה לפרושי ליה\u0004 \u0005[השמיע לנו שהיה צריך לפרש לו]\u0006","שנינו במשנה ש\u0003כשם שחולקים בתבואה\u0004 — \u0003כך חולקין בתבן ובקש. אמר רב יוסף: בבבל נהיגו דלא יהיבי תיבנא לאריסא\u0004 \u0005[נוהגים שאין נותנים תבן לאריס].\u0006 ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה]?\u0006 שהרי אם זה המנהג, מה חידש לנו רב יוסף? ומשיבים: החידוש בדבריו הוא \u0003דאי איכא איניש דיהיב\u0004 \u0005[שאם יש אדם שנותן]\u0006 לאריס — ב\u0003עין יפה הוא\u0004 שנוהג באריסו \u0003ולא גמרינן מיניה\u0004 \u0005[ואין לומדים ממנו].\u0006","\u0003אמר רב יוסף: בוכרא וטפתא וארכבתא וקני דחיזרא\u0004 \u0005[הגידור הראשון\u0006 של תעלת המים \u0005והשני והשלישי ו\u0006כן \u0005הקנים\u0006 שעושים בכדי לשים עליהם \u0005קוצים\u0006 בגדר\u0005]\u0006 הם משל \u0003בעל הבית, וחזרא גופיה דאריסא\u0004 \u0005[והקוצים עצמם\u0006 שעושים לגדר הם \u0005של האריס].\u0006 \u0003כללא דמילתא\u0004 \u0005[כללו של דבר]:\u0006 \u0003כל עיקר בלמא\u0004 \u0005[המחיצה]\u0006 הוא משל \u0003בעל הבית,\u0004 \u0003נטירותא יתירתא\u0004 \u0005[שמירה יתירה]\u0006 — \u0003דאריסא\u0004 \u0005[משל האריס].\u0006 \u0003ואמר רב יוסף: מרא\u0004 \u0005[המעדר],\u0006 \u0003וזבילא\u0004 \u0005[והאת],\u0006 \u0003ודוולא\u0004 \u0005[הדלי]\u0006 \u0003וזרנוקא\u0004 \u0005[והנאד]\u0006 למלא בו מים — של \u0003בעל הבית,\u0004 ואילו \u0003אריסא עביד בי יאורי\u0004 \u0005[האריס עושה את התעלות]\u0006 להשקות על ידן.","שנינו במשנה ש\u0003כשם שחולקין ביין\u0004 — \u0003כך חולקין בזמורות ובקנים.\u0004 ושואלים: \u0003קנים מאי עבידתייהו\u0004 \u0005[מה מעשיהם,\u0006 מה עניינם\u0005]\u0006 לגפנים? \u0003אמרי דבי\u0004 \u0005[אמרו בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי\u0004 שהכוונה היא ל\u0003קנים המוחלקין\u0004 (המחולקים לשניים), \u0003שבהן מעמידים את הגפנים.\u0004","עוד שנינו במשנה \u0003שניהם מספקין את הקנים.\u0004 ושואלים: \u0003למה לי\u0004 לומר דבר זה, מה עניינו כאן? ומסבירים כי בסגנון \u0003\"מה טעם\" קאמר\u0004 \u0005[אמר];\u0006 וכך יש להבין: \u0003מה טעם שניהם חולקין בקנים\u0004 — \u0003משום\u0004 ש\u0003שניהם מספקין את הקנים.\u0004","\u0003המקבל שדה מחבירו והיא בית השלחין\u0004 (שדה שאינו מסתפק בגשם אלא זקוק להשקאה נוספת), \u0003או בית האילן\u0004 (פרדס של אילנות), אם \u0003יבש המעין\u0004 או \u0003נקצץ האילן,\u0004 אף על פי שמסתבר שבדברים אלה התחשב המקבל כשלקח את השדה — בכל זאת \u0003אינו מנכה לו מן חכורו\u0004 (משכר החכירה) למרות מה שקרה בינתיים. ואולם \u0003אם אמר לו\u0004 במפורש: \u0003\"חכור לי שדה בית השלחין זו\", או\u0004 שאמר לו \u0003\"\u0004חכור \u0003לי\u0004 \u0003שדה בית האילן זה\",\u0004 אם \u0003יבש המעין\u0004 או \u0003נקצץ האילן\u0004 — \u0003מנכה לו מחכורו.\u0004","על גופה של המשנה שואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003יבש נהרא רבה\u0004 \u0005[הנהר הגדול]\u0006 שממנו יוצאות כל אמות המים — \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003אינו מנכה לו מן חכורו? נימא ליה\u0004 \u0005[שיאמר לו]:\u0006 הרי כאן היתה \u0003מכת מדינה,\u0004 כלומר, אסון לכל הסביבה כולה, ולכן יכול לנכות! \u0003אמר רב פפא:\u0004 מדובר כאן באופן ש\u0003יבש\u0004 רק \u0003נהרא זוטא\u0004 \u0005[הנהר הקטן]\u0006 שמושך לשדה זה בלבד, \u0003דאמר ליה\u0004 \u0005[ש\u0006יכול \u0005לומר לו]\u0006 בעל הבית:"],["\u0003איבעי\u0004 \u0005[היה]\u0006 \u0003לך לאתויי בדוולא\u0004 \u0005[להביא\u0006 מים \u0005בדלי].\u0006","\u0003אמר רב פפא: הני תרתי מתניתא קמייתא משכחת לה\u0004 \u0005[שתי המשניות הראשונות הללו מוצא אתה]\u0006 שהן שייכות ונכונות \u0003בין בחכרנותא\u0004 \u0005[בחכירה]\u0006 \u0003בין בקבלנותא\u0004 \u0005[בקבלנות],\u0006 \u0003מכאן ואי\u0004 \u0003לך, דאיתא בקבלנותא\u0004 \u0005[\u0006זו \u0005שישנה\u0006 ושייכת למקרה של \u0005קבלנות]\u0006 — \u0003ליתא בחכרנותא\u0004 \u0005[אינה בחכירה],\u0006 \u0003ודאיתא בחכרנותא\u0004 \u0005[ושישנה בחכירה]\u0006 — \u0003ליתא בקבלנותא\u0004 \u0005[אינה בקבלנות].\u0006","שנינו במשנה: \u0003אם אמר לו \"חכור לי שדה בית השלחין זה\"\u0004 ונפסק המעיין — מנכה לו משכר החכירה. ושואלים: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 יהא כך הדין? \u0003לימא ליה\u0004 \u0005[שיאמר לו]\u0006 המשכיר: \u0003שמא בעלמא אמרי\u0004 \u0005[\u0006את \u0005השם בלבד\u0006 של השדה \u0005אמרתי]\u0006 \u0003לך,\u0004 שכך קוראים לשדה, אבל אין זה בהכרח בית השלחין, \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005],\u0006 \u0003האומר לחבירו: \"בית כור עפר אני מוכר לך\", אף על פי שאין בו אלא\u0004 בית \u0003לתך\u0004 (שהוא חצי כור) — \u0003הגיעו\u0004 (השיגו, תפסו), שאינו יכול לחזור בו, \u0003שלא מכר לו אלא שמא\u0004 \u0005[שם],\u0006 \u0003והוא דמתקרי\u0004 \u0005[שנקרא]\u0006 שדה זה בפי הבריות \u0003\"בית כור\".\u0004","וכן אם אמר לו: \u0003\"כרמא\u0004 \u0005[כרם]\u0006 \u0003אני מוכר לך\", אף על פי שאין בו גפנים\u0004 — \u0003הגיעו, שלא מכר לו אלא שמא\u0004 \u0005[שם],\u0006 \u0003והוא דמתקרי\u0004 \u0005[שנקרא]\u0006 \u0003\"כרמא\".\u0004 וכן אם אמר לו \u0003\"פרדס אני מוכר לך\", אף על פי שאין בו רמונים\u0004 — \u0003הגיעו, שלא מכר לו אלא שמא\u0004 \u0005[שם],\u0006 \u0003והוא דמתקרי \"פרדסא\"\u0004 \u0005[שנקרא \"פרדס\"].\u0006 \u0003אלמא\u0004 \u0003אמר ליה\u0004 \u0005[מכאן\u0006 שיכול המוכר \u0005לומר לו]\u0006 לקונה: \u0003שמא בעלמא אמרי\u0004 \u0005[שם בלבד אמרתי]\u0006 \u0003לך,\u0004 שכך קוראים לו. ואם כן, \u0003הכא נמי נימא ליה\u0004 \u0005[כאן גם כן יאמר\u0006 \u0003לו]:\u0004 \u0003שמא בעלמא אמרי\u0004 \u0005[שם בלבד אמרתי]\u0006 \u0003לך!\u0004","\u0003אמר שמואל: לא קשיא\u0004 \u0005[אינו קשה];\u0006 \u0003הא\u0004 \u0005[זה]\u0006 — ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 ה\u0003מחכיר לחוכר, הא\u0004 \u0005[זה]\u0006 — ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 ה\u0003חוכר למחכיר.\u0004 ומה ההבדל; אם \u0003אמר ליה\u0004 \u0005[לו]\u0006 ה\u0003מחכיר לחוכר\u0004 — יכול המוכר לומר כי \u0003שמא בעלמא\u0004 \u0005[שם בלבד]\u0006 \u0003אמר ליה\u0004 \u0005[לו],\u0006 ואין החוכר יכול להתנגד, ולעומת זאת אם \u0003אמר ליה\u0004 \u0005[לו]\u0006 כך ה\u0003חוכר למחכיר\u0004 — הרי זה \u0003קפידא\u0004 \u0005[הקפדה],\u0006 שוודאי אינו מעונין אלא בדבר זה.","\u0003רבינא אמר: אידי ואידי\u0004 \u0005[זה וזה]\u0006 מדובר באופן ש\u0003אמר ליה\u0004 \u0005לו\u0006 ה\u0003מחכיר לחוכר\u0004 וכלשון משנתנו, ואולם הטעם הוא \u0003מדקאמר\u0004 \u0005[מכיון\u0006 \u0003ש\u0004הוא \u0005אומר]\u0006 \u0003\"זה\", מכלל\u0004 הדבר אתה למד \u0003דקאי בגוה עסקינן\u0004 \u0005[ש\u0006הוא \u0005עומד בתוכה אנו עוסקים],\u0006 ואם הוא מצוי שם \u0003בית השלחין למה ליה למימר\u0004 \u0005[לו לומר]?\u0006 הלא הכל רואים שבית השלחין הוא, אלא ודאי מתכוון להדגיש, \u0003דקאמר ליה\u0004 \u0005[שאומר לו]:\u0006 \u0003בית השלחין כדקיימא השתא\u0004 \u0005[כמו ש\u0006הוא \u0005עומד כעת].\u0006","\u0003המקבל שדה מחבירו והובירה,\u0004 שלא עבד בה כלל — \u0003שמין\u0004 (מעריכים) \u0003אותה\u0004 את השדה \u0003כמה ראויה\u0004 היתה \u0003לעשות\u0004 אם היתה מעובדת כראוי, \u0003ונותן לו\u0004 המקבל לבעל השדה. והטעם: לפי \u0003שכך כותב לו\u0004 בשטרות הקבלנות הרגילים במפורש: \u0003\"אם אוביר\u0004 את השדה \u0003ולא אעביד\u0004 \u0005[אעבוד\u0006 בו\u0005]\u0006 \u0003אשלם במיטבא\u0004 \u0005[במיטב]\u0006 \u0003\".\u0004","\u0003ר' מאיר היה דורש לשון הדיוט,\u0004 כלומר, שהיה מוציא מסקנות הלכתיות מלשונם של שטרות שנהגו בהם הדיוטות, אף על פי ששטרות אלה לא נכתבו על פי חכמים, אלא כיון שכך כתוב בשטר ראוי לדקדק בלשונו, ולהוציא משם את כל המסקנות. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 כעין משנתנו, \u0003ר' מאיר אומר:\u0004 חייב לשלם, שכן כותב: \u0003\"אם אוביר\u0004 את השדה \u0003ולא אעביד\u0004 \u0005[אעבוד\u0006 בו\u0005]\u0006 \u0003אשלם במיטבא\u0004 \u0005[במיטב] \u0006\u0003\",\u0004 וכך יש לו לעשות.","וכן \u0003ר' יהודה היה דורש לשון הדיוט;\u0004 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006, \u0003ר' יהודה אומר: אדם מביא קרבן עשיר על\u0004 (לצורך) \u0003אשתו,\u0004 שאם נתחייבה אשתו בקרבן יולדת שיש בו חילוק בין עשיר לעני, אם עשיר הוא — מביא עליה קרבן עשיר, ואין אומרים שכיון שאין לאשה ממון משלה היא נחשבת לעניה, \u0003וכן\u0004 מביא עבורה \u0003כל קרבן וקרבן שהיא חייבת\u0004 (כגון חטאת או אשם), \u0003שכך כותב לה\u0004 בכתובה בין שאר התחייבותיו לה: כל \u0003אחריות דאית ליך\u0004 \u0005[שיש לך]\u0006 \u0003עלי מן קדמת דנא\u0004 \u0005[מלפנים],\u0006 ובהתאם להתחייבות זו משלם גם עבור הקרבנות.","וכן \u0003הלל הזקן היה דורש לשון הדיוט; דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אנשי אלכסנדריא היו מקדשין את נשותיהם\u0004 זמן ניכר לפני כניסתן לחופה, כפי שהיה נהוג באותם ימים, \u0003ובשעת כניסתן לחופה\u0004 היה קורה ש\u0003באין אחרים וחוטפים אותם מהן, ובקשו חכמים לעשות בניהם ממזרים,\u0004 שהרי אחר הקידושין האשה היא ארוסה לבעלה ואם חטף אותה אחר הרי היא כאשת איש שנחטפה ובניה ממזרים.","\u0003אמר להן הלל הזקן: הביאו לי כתובת אמכם\u0004 ונעיין בה. \u0003הביאו לו כתובת אמן, ומצא שכתוב בהן\u0004 בכתובות אלה נוסח מיוחד: \u0003לכשתכנסי לחופה הוי\u0004 \u0005[היי]\u0006 \u0003לי לאינתו\u0004 \u0005[לאישה],\u0006 ונמצא שהקידושין לא חלו בשעת הקידושין, אלא רק עם הכניסה לחופה. וכיון שלא נכנסו לחופה — לא חלו כלל קידושין ראשונים, \u0003ו\u0004על כן \u0003לא עשו בניהם ממזרים.\u0004","וכן, \u0003ר' יהושע בן קרחה היה דורש לשון הדיוט; דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יהושע בן קרחה אומר: המלוה את חבירו לא ימשכננו\u0004 (לא יקח ממנו משכון) \u0003יותר\u0004 משווי \u0003חובו, שכך כותב לו\u0004 הלווה למלוה, אם המלוה מחזיר לו את המשכון כדי שישתמש בו הלווה: \u0003תשלומתא דאית\u0004 \u0005[תשלום שיש]\u0006 \u0003לך עלי כל קבל דיכי\u0004 \u0005[כנגד זה],\u0006 ומשמע — שלא יותר מכדי חובו.","ומעירים: \u0003טעמא\u0004 \u0005[הטעם]\u0006 דווקא — ש\u0003כתב ליה הכי\u0004 \u0005[לו כך],\u0006 \u0003הא אי\u0004 \u0005[הרי אם]\u0006 \u0003לא כתב ליה הכי\u0004 \u0005[היה כותב לו כך]\u0006 — \u0003לא קניא\u0004 \u0005[היה קונה]\u0006 את המשכון? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר\u0004 \u0003ר' יוחנן: משכנו\u0004 המלוה ללווה \u0003והשיב לו\u0004 את \u0003המשכון, ומת\u0004 הלווה — \u0003שומטו\u0004 את המשכון \u0003מעל גבי בניו,\u0004 ואין אומרים שאין נכסים מטלטלים של יתומים נקנים לבעל חוב של אביהם, כי כיון שמשכנו — נחשב המשכון כרכוש המלוה לענין לגבות ממנו."],["\u0003אהני\u0004 \u0005[הועילה]\u0006 ה\u0003כתיבה לגירעון,\u0004 כלומר, אם יפחתו דמי המשכון יוכל המלוה לקבל את שאר חובו מנכסי הלווה.","\u0003ר' יוסי היה דורש לשון הדיוט; דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003רבי יוסי אומר: מקום שנהגו לעשות כתובה מלוה,\u0004 כלומר, שנהגו לכתוב אותה כמו שכותבים שטר מלוה כדיוקו — \u0003גובה מלוה,\u0004 שכאשר מגיעה הכתובה להיגבות — גובים בה את הסכום הכתוב בה. ואילו מקום שנוהגים \u0003לכפול,\u0004 שהיו מקומות שנהגו לכפול את הסכומים הכתובים בכתובה לכבוד הכלה כדי שייראה שהיא מכניסה לבעלה ממון רב ואף הוא מתחייב על סכומים גדולים — במקרה כזה \u0003גובה\u0004 רק \u0003מחצה\u0004 מן הסכום הכתוב.","מספרים: \u0003נהרבלאי גבו תילתא\u0004 \u0005[היו גובים שליש],\u0006 משום שבמקומם היו נוהגים לכפול את הסכומים פי שלוש. ואילו \u0003מרימר מגבי נמי שבחא\u0004 \u0005[היה גובה גם את השבח],\u0006 כלומר, גם אותם הסכומים שאבי הכלה מוסיף לשבח ולכבודה, היה גובה בדיוק ככתוב בכתובה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא למרימר: והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 שבמקום שהיו נוהגים \u0003לכפול\u0004 היה \u0003גובה מחצה!\u0004 ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה];\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שגובה בדיוק כפי שכתוב, הרי זה באופן \u0003דקני מיניה\u0004 \u0005[זשקנה ממנו],\u0006 שעשה קנין על הסכום הכתוב, ופירושו של דבר שקיבל על עצמו סכום זה, אף כי לא קיבל אותו בפועל. \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שגובה רק כפי הנהוג הרי זה באופן ש\u0003לא קני מיניה\u0004 \u0005[קנה ממנו].\u0006","מסופר, ש\u0003רבינא\u0004 הוסיף ו\u0003משבח וכתיב לברתיה\u0004 \u0005[\u0006וכתב \u0005שבח כנהוג וכתב לבתו\u0006 בכתובתה\u0005].\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003נקני מיניה דמר\u0004 \u0005[נקנה ממנו, מאדוני],\u0006 כלומר, נעשה קנין על כתובה זו. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אי מקנא\u0004 \u0005[אם לקנות]\u0006 — \u0003לא מיכפל\u0004 \u0005[אכפול]\u0006 את הסכום, \u0003אי מיכפל\u0004 \u0005[אם לכפול]\u0006 — \u0003לא מיקנא\u0004 \u0005[לקנות].\u0006","אגב ענין זה מסופר, \u0003ההוא גברא\u0004 \u0005[אדם אחד]\u0006 ש\u0003אמר להו\u0004 \u0005[להם]\u0006 ליורשיו לפני מותו: \u0003הבו\u0004 \u0005[תנו]\u0006 \u0003לה\u0004 \u0003ארבע מאה זוזי לברתי\u0004 \u0005[מאות זוזים לבתי]\u0006 \u0003בכתובתה.\u0004 \u0003שלח רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אויא לקמיה\u0004 \u0005[לפני]\u0006 \u0003רב אשי\u0004 את השאלה הבאה: מה היתה כוונתו של אותו אדם? האם היתה כוונתו \u0003ארבע מאה דאינון תמני מאה\u0004 \u0005[ארבע מאות\u0006 ממש \u0005שהם שמונה מאות\u0006 שכותבים \u0005],\u0006 \u0003או ארבע מאה זוזי דאינון מאתן\u0004 \u0005[ארבע מאות זוזים\u0006 בכתיבה \u0005שהם מאתיים]?\u0006 \u0003אמר רב אשי: חזינן\u0004 \u0005[רואים אנו]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003אמר \"הבו\u0004 \u0005[תנו]\u0006 \u0003לה\"\u0004 — הכוונה היתה \u0003ארבע מאה זוזי דאינון תמני מאה\u0004 \u0005[ארבע מאות זוז שהם שמונה מאות],\u0006 שהתכוון לתת לה ארבע מאות ממש. \u0003אי\u0004 \u0005[אם]\u0006 \u0003אמר \"כתובו לה\",\u0004 הכוונה היתה \u0003ארבע מאה זוז דאינון מאתן\u0004 \u0005[ארבע מאות זוז שהם מאתיים]\u0006 שרצה שיכתבו סכום זה, שאין נותנין בפועל אלא את מחציתו.","\u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 בלשון אחרת, \u0003אמר רב אשי: חזינן\u0004 \u0005[רואים אנו]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003אמר \"לכתובתה\",\u0004 יש לפרש: \u0003ארבע מאה זוזי דאינון תמני מאה\u0004 \u0005[ארבע מאות זוז\u0006 ממש \u0005שהם שמונה מאות\u0006 בכתיבה\u0005],\u0006 שכוונתו היתה שלצורך הכתובה נתן סכום זה. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003אמר \"בכתובתה\"\u0004 משמע שחשב על הסכום הכתוב בכתובה, וצריך לתת \u0003ארבע מאה זוזי דאינון מאתן\u0004 \u0005[ארבע מאות זוז שהם\u0006 רק \u0005מאתים\u0006 בפועל\u0005].\u0006","ומעירים: \u0003ולא היא\u0004 (ואינו כן), \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 כש\u0003אמר \"לכתובתה\" ולא שנא\u0004 \u0005[אינו שונה]\u0006 כש\u0003אמר \"בכתובתה\"\u0004 אין נותנים אלא \u0003ארבע מאה זוזי דאינון מאתן\u0004 \u0005[ארבע מאות זוז\u0006 בכתובים \u0005שהם\u0006 בפועל \u0005מאתיים],\u0006 \u0003עד דאמר\u0004 \u0005[שיאמר]\u0006 \u0003\"הבו\u0004 \u0005[תנו]\u0006 \u0003לה\" סתמא\u0004 \u0005[סתם]\u0006 בלי לפרש שהוא לצורך הכתובה.","מסופר: \u0003ההוא גברא\u0004 \u0005[אדם אחד]\u0006 \u0003קבל ארעא מחבריה\u0004 \u0005[קרקע מחבירו\u0006 לעבדה\u0005],\u0006 ו\u0003אמר: אי מוברנא ליה\u0004 \u0005[אם אוביר\u0006 ולא אעבד \u0005אותה]\u0006 — \u0003יהיבנא\u0004 \u0005[אתן]\u0006 \u0003לך אלפא זוזי\u0004 \u0005[אלף זוז].\u0006 לבסוף הוברר כי \u0003אוביר תילתא\u0004 \u0005[הוביר שליש]\u0006 מהקרקע. \u0003אמרי נהרדעי\u0004 \u0005[אמרו\u0006 חכמי \u0005נהרדעא]:\u0006 \u0003דינא\u0004 \u0005[הדין]\u0006 \u0003הוא דיהיב ליה תלת מאה ותלתין ותלתא ותילתא\u0004 \u0005[שיתן לו\u0006 בשל הוברת שליש השדה \u0005שלוש מאות שלושים ושלושה ושליש\u0006 דינרים\u0005]\u0006 שהם שליש הסכום שקצב. \u0003רבא אמר:\u0004 דבר כגון זה \u0003אסמכתא היא,\u0004 כלומר, התחייבות שאדם מתחייב בלא כוונת אמת לקיים אותה, ואינה אלא כהבטחה בלבד. \u0003ו\u0004הלכה היא ש\u0003אסמכתא לא קניא\u0004 \u0005[אינה קונה].\u0006","ושואלים: \u0003ול\u0004דעת \u0003רבא, מאי שנא מהא דתנן\u0004 \u0005[מה שונה\u0006 דבר זה \u0005ממה ששנינו\u0006 במשנה\u0005]:\u0006 שאם כתב \u0003\"אם אוביר\u0004 את השדה \u0003ולא אעביד\u0004 \u0005[אעבוד\u0006 בו\u0005]\u0006 \u0003אשלם במיטבא\u0004 \u0005[במיטב]\u0006 \u0003\"?\u0004 ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 \u0003לא קא גזים\u0004 \u0005[הגזים]\u0006 ורק אמר שישלם במיטב עבור הנזקים הממשיים שנגרמו לבעל השדה כשלא עובד, \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003כיון דקאמר מילתא יתירתא\u0004 \u0005[שאמר דבר יתר]\u0006 — \u0003גוזמא בעלמא\u0004 \u0005[בלבד]\u0006 \u0003הוא דקגזים\u0004 \u0005[שהגזים],\u0006 ואין לקבל זאת כהתחייבות ממונית ממש, אלא כאסמכתא.","מסופר: \u0003ההוא גברא דקביל ארעא לשומשמי, זרעה חיטי\u0004 \u0005[אדם אחד קיבל קרקע\u0006 על מנת לזרוע בה \u0005שומשומים, וזרעה חיטים],\u0006 וכרגיל הקרקע מנוצלת ונכחשת הרבה על ידי השומשומים, אבל הרווח הוא גדול. אולם באותה שנה \u0003עבדא חיטי כשומשמי\u0004 \u0005[עשתה\u0006 האדמה \u0005חטים\u0006 בשווי של שדה רגיל של \u0005שומשומים].\u0006 \u0003סבר רב כהנא למימר\u0004 \u0005[לומר]\u0006 כי \u0003מנכי ליה כחשא דארעא\u0004 \u0005[מנכה לו\u0006 האריס מן התשלום ערך \u0005כחישתה,\u0006 ירידת ערכה, \u0005של האדמה]\u0006 שכיון שזרע בה חיטים נמצא שהרוויח בעל השדה שלא כחשה הקרקע, וקיבל אותן תוצאות כספיות.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לרב כהנא אמרי אינשי\u0004 \u0005[אומרים בני אדם]\u0006 בפתגם עממי: \u0003כחשא ארעא\u0004 \u0005[שתכחוש האדמה]\u0006 \u0003ו\u0004ש\u0003לא לכחוש מרה\u0004 \u0005[יכחוש בעליה],\u0006 כלומר, אנשים מעוניינים ברווח כספי מהיר, ואינם מביאים בחשבון את ניצול האדמה, והיה האריס יכול לזרוע שומשומים, ואם לא זרע — אינו מקבל תשלום על כך.","מסופר: \u0003ההוא גברא דקביל ארעא לשומשמי, זרעא חיטי, עבדא חיטי טפי מן שומשמי\u0004 \u0005[אדם אחד קיבל אדמה על מנת\u0006 לגדל בה \u0005שומשומים וזרעה חיטים, ועשתה בחיטים יותר מן שומשומים].\u0006 \u0003סבר רבינא למימר\u0004 \u0005[לומר]\u0006 כי \u0003יהיב ליה שבחא דביני ביני\u0004 \u0005[נותן לו את השבח,\u0006 את ההבדל, \u0005שבין זה לזה]\u0006 לחוכר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא מדפתי לרבינא: אטו\u0004 \u0005וכי\u0006 \u0003הוא\u0004 בלבד בעבודתו \u0003אשבח\u0004 \u0005[השביח],\u0006 ואילו \u0003ארעא\u0004 \u0005[האדמה]\u0006 \u0003לא אשבחה\u0004 \u0005[השביחה]?!\u0006 אלא צריכים לומר שיחלוקו ביניהם.","אגב הדיונים בענין חכירת ואריסות שדה, עוברים לדון בסדרת הלכות דומות. \u0003אמרי נהרדעי\u0004 \u0005[אמרו\u0006 חכמי \u0005נהרדעא]:\u0006 \u0003האי עיסקא\u0004 \u0005[\u0006ענין \u0005זה\u0006 של \u0005עיסקה]\u0006 שאדם לוקח מחבירו כסף או סחורה מסויימת והוא מטפל במכירתה, וכדי שלא יהא בכך משום ריבית, מקבל בעל הכסף על עצמו חלק גדול יותר (כגון שני שליש) מן ההפסד האפשרי, וחלק קטן יותר (כגון מחצית) ברווח. עיסקה זו היא מבחינת ההלכה נחשבת כ\u0003פלגא\u0004 \u0005[חציה]\u0006 \u0003מלוה ופלגא\u0004 \u0005[וחציה]\u0006 \u0003פקדון,\u0004 כי \u0003עבוד רבנן מילתא דניחא ליה\u0004 \u0005[עשו חכמים דבר ש\u0006יהיה \u0005נוח לו]\u0006 \u0003ללוה וניחא ליה\u0004 \u0005[ונוח לו]\u0006 \u0003למלוה,\u0004","\u0003השתא דאמרינן פלגא\u0004 \u0005[עכשיו שאמרנו\u0006 ש\u0005חציה]\u0006 של העיסקה הוא כ\u0003מלוה,\u0004 משמע שיכול להוציא את הכסף בכל דרך שירצה, ולכך \u0003אי בעי למשתי ביה שכרא\u0004 \u0005[אם רוצה לשתות בו שיכר]\u0006 — \u0003שפיר דמי\u0004 \u0005[ראוי,\u0006 הדבר ומותר\u0005]\u0006 ואין נותן הכסף יכול לעכב בעדו. ואילו \u0003רבא אמר: להכי קרו ליה\u0004 \u0005[משום כך קוראים לזה]\u0006 \u0003\"עיסקא\"\u0004 — \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 המלוה ללווה: \u0003כי יהבינא\u0004 \u0005[כאשר נתתי]\u0006 \u0003לך\u0004 את הדבר, הרי זה \u0003לאיעסוקי ביה\u0004 \u0005[להתעסק בו]\u0006 במסחר, \u0003ולא למשתי ביה שכרא\u0004 \u0005[לשתות בו שיכר].\u0006","\u0003אמר רב אידי בר אבין\u0004 לפי העקרון הזה: \u0003ואם מת\u0004 מקבל העיסקה — \u0003נעשה\u0004 הרכוש הזה \u0003מטלטלין אצל בניו\u0004 ואי אפשר לקחת מהם בחובם, שדינה כשאר מטלטלים שיורשים היתומים, שאין משתעבדין לתשלום חובות האב. \u0003רבא אמר: להכי קרו ליה\u0004 \u0005[משום כך קוראים לזה]\u0006 \u0003\"עיסקא\"\u0004 — ש\u0003אם מת לא יעשה מטלטלין אצל בניו,\u0004 משום שהעיסקה יש בה משום שותפות, ואינה כהלוואה סתם.","\u0003אמר רבא: חדא עיסקא ותרי שטרי\u0004 \u0005[\u0006ב\u0005עיסקה אחת ושני שטרות],\u0006 אם היה \u0003פסידא\u0004 \u0005[הפסד]\u0006 — הריהו גם של ה\u0003מלוה,\u0004 שאם עשו שנים עיסקה אחת אלא שכתבו שני שטרות עיסקה נבדלים על שני חלקים שבעיסקה, אם בחלק העיסקה הכתוב בשטר אחד הפסיד הרבה, ובחלק האחד הרוויח, כיון שהיו שני שטרות — הרי הדבר הוא כשתי עיסקות, ואין מחשבים את ההפסד בחצי אחד כנגד הרווח שיבוא מהצד האחר, ולכן יש בכך הפסד למלוה. שהרי תמיד המלוה משתתף בהפסד יותר מברווח."],["\u0003תרי עיסקי וחד שטרא\u0004 \u0005[שתי עסקות ושטר אחד]\u0006 — אם יהיה הפסד בעיסקה אחת יהיה זה \u0003פסידא\u0004 \u0005[הפסד]\u0006 גם של ה\u0003לוה,\u0004 המקבל, שהרי שתי העיסקות נחשבות לעיסקה אחת.","\u0003ואמר רבא: האי מאן דקביל עיסקא מן חבריה ופסיד\u0004 \u0005[מי שקיבל עסק מחבירו והפסיד]\u0006 בעסק, והמקבל \u0003טרח ומלייה\u0004 \u0005[ומילא אותו,\u0006 את ההפסד\u0005]\u0006 \u0003ולא אודעיה\u0004 \u0005[הודיעו]\u0006 לבעל הסחורה, \u0003לא מצי אמר ליה\u0004 \u0005[אינו יכול לומר לו]\u0006 אחר כך: \u0003דרי מהיאך פסידא בהדאי\u0004 \u0005[שא בהפסד זה יחד איתי].\u0006 והטעם — \u0003משום דאמר ליה\u0004 \u0005[\u0006שיכול \u0005לומר לו]\u0006 בעל העיסקה: \u0003להכי\u0004 \u0005[משום כך]\u0006 \u0003טרחת למליותיה\u0004 \u0005[למלאותו,\u0006 את ההפסד\u0005]\u0006 — \u0003כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא ליקרו\u0004 \u0005[יקראו]\u0006 \u0003לך \"מפסיד עיסקי\u0004 \u0005[עסקות]\u0006","\u0003\"\u0004שייצא עליך שם רע ויימנעו בשל כך מלתת לך בעתיד עסקות. \u0003ואמר רבא: הני בי תרי דעבדי עיסקא בהדי הדדי ורווח\u0004 \u0005[שנים שעשו,\u0006 שקיבלו \u0005עיסקה יחד והרוויחו],\u0006 ו\u0003אמר ליה חד לחבריה\u0004 \u0005[לו אחד לחבירו]:\u0006 \u0003תא ליפלוג\u0004 \u0005[בוא ונחלק\u0006 בינינו\u0005],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003אמר ליה אידך\u0004 \u0005[לו האחר]:\u0006 נמתין ו\u0003נרווח טפי\u0004 \u0005[נרויח יותר]\u0006 — \u0003דינא\u0004 \u0005[הדין]\u0006 \u0003הוא דמעכב\u0004 \u0005[ש\u0006יכול \u0005לעכב].\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי\u0004 לפחות \u0003פלגא דרווחא\u0004 \u0005[\u0006\u0005חצי מהרווח]\u0006 — \u0003אמר ליה\u0004 \u0005[\u0006יכול האחר \u0005לומר לו]:\u0006 \u0003רווחא\u0004 \u0005[הרווח]\u0006 — \u0003לקרנא\u0004 \u0005[לקרן]\u0006 \u0003משתעבד\u0004 שהרווח והקרן נחשבים כיחידה אחת, ואם אין מוציאים את הרווח יכולים על ידי כך להרוויח יותר בדבר.","\u0003ואי\u0004 \u0005[ואם]\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי פלגא רווחא ופלגא קרנא\u0004 \u0005[חצי רווח וחצי מהקרן]\u0006 \u0003אמר ליה\u0004 \u0005[\u0006יכול האחר \u0005לומר לו]:\u0006 \u0003עיסקא\u0004 \u0005[העסק]\u0006 — \u0003להדדי\u0004 \u0005[לשנינו]\u0006 \u0003משועבד,\u0004 ששנינו שותפים בו, ואין אתה יכול לחלק. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003נפלוג רווחא ונפלוג קרנא\u0004 \u0005[נחלק את הרווח ונחלק את הקרן],\u0006 \u0003ואי מטי\u0004 \u0005[ואם יגיע]\u0006 \u0003לך פסידא\u0004 \u0005[הפסד]\u0006 על ידי כך — \u0003דרינא בהדך\u0004 \u0005[אני אשא עימך\u0006 בהפסד\u0005]\u0006 — \u0003אמר ליה\u0004 \u0005[\u0006יכול \u0005לומר לו]:\u0006 \u0003מזלא דבי תרי\u0004 \u0005[מזל של שנים]\u0006 \u0003עדיף,\u0004 ורצוני שנמשיך שנינו יחד לעבוד, ובכל אלה הדין עמו.","\u0003המקבל שדה מחבירו ולא רצה\u0004 המקבל \u0003לנכש\u0004 את העשבים הרעים מהשדה, \u0003ואמר לו\u0004 לבעל השדה: \u0003מה איכפת לך?\u0004 הלא אתה לא תפסיד בדבר, \u0003הואיל ואני נותן לך את חכירך,\u0004 כלומר, אותה כמות תבואה שהתחייבתי לתת לך — אתן לך, ומה איכפת לך אם אני מפסיד — \u0003אין שומעין לו\u0004 לחוכר. \u0003מפני שיכול\u0004 בעל השדה \u0003לומר לו: למחר אתה יוצא ממנה ומעלת לפני עשבים,\u0004 שכל אותם עשבים רעים שהשארת ישארו בשדה, וישבשו את גידול תבואתו במשך שנים אחדות.","\u0003אי אמר ליה\u0004 \u0005[ואם יאמר לו]\u0006 החוכר: \u0003לבתר הכי כריבנא לה\u0004 \u0005[אחר כך,\u0006 אחרי שאקצור, \u0005אחרוש את השדה]\u0006 ואז יחוסלו העשבים הרעים, ומה איכפת לך שאינני מנכש — יכול בעל השדה \u0003אמר ליה\u0004 \u0005[לומר לו]:\u0006 \u0003חטי מעלייתא בעינא\u0004 \u0005[חיטים מעולות אני רוצה]\u0006 ולא חטים פחותות בטיבן, שצמחו בין העשבים הרעים. \u0003ואי אמר ליה\u0004 \u0005[ואם יאמר לו]\u0006 המקבל: \u0003זביננא\u0004 \u0005[אקנה]\u0006 \u0003לך חטי משוקא\u0004 \u0005[חיטים\u0006 מעולות \u0005מהשוק],\u0006 יכול בעל השדה \u0003אמר ליה\u0004 \u0005[לומר לו]:\u0006 \u0003חטי דארעאי בעינא\u0004 \u0005[חטים מאדמתי אני רוצה].\u0006 \u0003ואי אמר ליה\u0004 \u0005[ואם יאמר לו]\u0006 המקבל: \u0003מנכישנא\u0004 \u0005[אנכש]\u0006 \u0003לך שיעור מנתיך\u0004 \u0005[חלקך],\u0006 ואת השאר לא אנכש — יכול בעל השדה \u0003אמר ליה\u0004 \u0005[לומר לו]:\u0006 \u0003מנסבת\u0004 \u0005[מוציא אתה]\u0006 \u0003שם רע לארעאי\u0004 \u0005[על האדמה שלי],\u0006 שהרי הכל יראו שהיא משובשת בעשבים רעים.","ושואלים: \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 טעם אחר: \u0003מפני שמעלת לפני עשבים!\u0004 אלא כך צריך לומר, \u0003משום\u0004 שיכול בעל השדה \u0003אמר ליה\u0004 \u0005[לומר לו],\u0006 למקבל: \u0003בזרא\u0004 \u0005[זרע]\u0006 ש\u0003נפל\u0004 — \u0003נפל,\u0004 כלומר, אף שאחר כך אתה חורש ועוקר את העשבים עצמם, ואולם זרעיהם נשארים בקרקע והם צומחים בה בשנים הבאות.","\u0003המקבל שדה מחבירו ולא עשתה\u0004 תבואה במדה שיהא כדאי לטפל בה, \u0003אם יש בה\u0004 מספיק \u0003כדי להעמיד כרי\u0004 — \u0003חייב לטפל בה\u0004 ויקבל בעל השדה את חלקו. \u0003אמר ר' יהודה: מאי\u0004 \u0005[מה]\u0006 משמעות \u0003יש ב\u0004\u0003קצבה\u0004 זו שאמרנו \u0003בכרי?\u0004 כלומר, קצבה זו של כרי שבשדה אין בה משמעות שהרי השדה יכול להיות גדול או קטן. \u0003אלא\u0004 השיעור הוא: \u0003אם יש בה כדי נפילה,\u0004 שאם יש בתבואה הצומחת לפחות כדי כמות הזרעים שצריכים כדי לזרוע שדה זה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003המקבל שדה מחבירו ולא עשתה\u0004 דייה, \u0003אם יש בה כדי להעמיד כרי\u0004 — \u0003חייב לטפל בה\u0004 ולתת לבעל הבית את חלקו. \u0003שכך כותב לו\u0004 בחוזה האריסות: \u0003אנא אוקים\u0004 \u0005[אעמוד]\u0006 \u0003ואניר\u0004 \u0005[ואחרוש]\u0006 \u0003ואזרע ואחצוד\u0004 \u0005[ואקצור]\u0006 \u0003ואעמר ואדוש ואידרי\u0004 \u0005[ואזרה]\u0006 \u0003ואוקים כריא קדמך\u0004 \u0005[ואעמיד כרי לפניך],\u0006 \u0003ותיתי אנת\u0004 \u0005[ותבוא אתה]\u0006 \u0003ותיטול פלגא\u0004 \u0005[מחצית\u0006 היבול], \u0003ואנא\u0004 \u0005[ואני]\u0006 \u0003בעמלי ובנפקות\u0004 \u0005[ובהוצאת]\u0006 \u0003ידי\u0004 אקבל אף אני רק \u0003פלגא\u0004 \u0005[חצי],\u0006 ואם כן, כיון שניתן הדבר למילוי — חייב לעשות כלשון ההסכם.","ושואלים: \u0003וכמה\u0004 הוא השיעור ששנינו \u0003\"כדי להעמיד בה כרי\",\u0004 מה גדלו של כרי זה? \u0003אמר ר' יוסי בר' חנינא: כדי שתעמוד בו הרחת,\u0004 שאם הכרי גדול מספיק שיעמוד בו הכלי שמשתמשים בו לזרות את התבואה הרי זה נחשב כבר כרי. \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003רחת היוצא מהאי גיסא להאי גיסא\u0004 \u0005[היוצא מצד זה לצד זה],\u0006 שבולטים קצות הרחת מתוך הכרי, \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 האם נחשב הוא מעמיד רחת, או לא?","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ש\u0003אמר ר' אבהו: לדידי מפרשא לי מיניה\u0004 \u0005[לי נתפרש\u0006 הדבר \u0005ממנו]\u0006 מ\u0003ר' יוסי בר' חנינא\u0004 עצמו: \u0003כל שאין כונס שלו רואה פני החמה,\u0004 כל כרי שבית הקיבול (\"כונס\") של הרחת מתכסה בו (\"אינו רואה פני חמה\") נחשב לכרי. \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בנושא זה. \u0003לוי אמר\u0004 שיעור כרי זה הוא \u0003שלש סאין, דבי\u0004 \u0005[\u0006ב\u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי אמרי\u0004 \u0005[אמרו]\u0006 ששיעור כרי זה הוא \u0003סאתים. אמר ריש לקיש: סאתים שאמרו\u0004 בענין זה כוונתו \u0003חוץ מן ההוצאה.\u0004 כלומר, שלאחר שישלם את ההוצאות הממשיות שהוציא ישאר עוד רווח כדי סאתים, ובמקרה זה נחשב השדה כראוי לעבדו, ואם לאו יכול הקבלן להפקירו אם ירצה.","בדומה למחלוקת זו בשיעורים הביאו מחלוקת בנושא אחר שאף בה דנו בשיעורים דומים, \u0003תנן התם\u0004 \u0005[שנינו\u0006 במשנה \u0005שם]\u0006 בדיני טומאת אוכלים: \u0003פריצי זיתים וענבים, בית שמאי מטמאין,\u0004 שלדעתם הם נחשבים כמאכל \u0003ובית הלל מטהרין,\u0004 שמפני טיבם הפחות אינם ראויים למאכל.","ושאלו: \u0003מאי\u0004 \u0005[מה\u0006 פרוש\u0005]\u0006 \u0003\"פריצי זיתים\"? אמר רב הונא: רשעי זיתים,\u0004 כלומר, זיתים רעים שאין בהם כמעט שמן. \u0003אמר רב יוסף: ומאי קראה\u0004 \u0005[ומה המקרא]\u0006 המלמדנו שכך היא משמעות הלשון — שנאמר: \u0003\"ובני פריצי עמך ינשאו להעמיד חזון ונכשלו\"\u0004 (דניאל יא, יד), משמע ש\"פריצים\" הם רשעים. \u0003רב נחמן בר יצחק אמר: מהכא\u0004 \u0005[מכאן]\u0006 מפסוק זה אפשר ללמוד מה פירושו של \"פריץ\" — שנאמר: \u0003\"והוליד בן פריץ שפך דם\"\u0004 (יחזקאל יח, י).","ושואלים: \u0003וכמה\u0004 הוא השיעור של \u0003פריצי זיתים,\u0004 מתי נקראים הזיתים \"פריצי זיתים\"? \u0003ר' אלעזר אמר:\u0004 כשאפשר להוציא \u0003ארבעת קבין\u0004 שמן \u0003לקורה\u0004 אחת שמכניסים בבת אחת בבית הבד, \u0003דבי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי אמרי\u0004 \u0005[אומרים]:\u0006 כשאפשר להוציא \u0003סאתים לקורה\u0004 של שמן.","ומעירים: \u0003ולא פליגי\u0004 \u0005[נחלקו]\u0006 חכמים אלה בהלכה עצמה, וההבדל ביניהם הוא תוצאה של הבדלי נוהג. כי \u0003הא\u0004 \u0005[זה]\u0006 שאמר ר' אלעזר, הרי זה \u0003באתרא דמעיילי כורא באוללא\u0004 \u0005[\u0006\u0005במקום שמכניסים כור\u0006 אחד \u0005בבת אחת\u0006\u0005]\u0006 לעצור, ומזה יש להוציא ארבעה קבין, \u0003הא\u0004 \u0005[וזה,\u0006 בבית ר' ינאי\u0005]\u0006 \u0003באתרא דמעיילי תלתא כורין באוללא\u0004 \u0005[במקום שמכניסים שלושה כורים בבית הבד],\u0006 שהוא פי שלוש, ולכן גם השמן שיוצא הוא בדיוק פי שלוש.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006"],["\u0003עלו\u0004 הזב והטהור \u0003באילן שכוחו רע,\u0004 שהוא מתנדנד בעלייתם. או \u0003בסוכה\u0004 (ענף) \u0003שכוחה רע\u0004 — \u0003טמא\u0004 הטהור, שאנחנו מחשיבים זאת שהזב מסיט ומניד את הטהור והריהו כטמא טומאת היסט על ידי הזב.","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא\u0006 בדיוק\u0005]\u0006 \u0003אילן שכוחו רע? אמרי דבי\u0004 \u0005[אמרו בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי:\u0004 \u0003כל שאין בעיקרו לחוק רובע,\u0004 כלומר, כל שאין גזעו רחב עד שאפשר לחקוק בו כלי של רובע הקב. \u0003היכי דמי\u0004 \u0005[כיצד היא]\u0006 \u0003סוכה שכוחה רע? אמר ריש לקיש: כל שנחבאת בחזיונה,\u0004 כלומר, שאפשר להכניס (\"להחביא\") בתוך אגרופו של אדם, שסוכה כזו מן הסתם איננה חזקה למדי כדי להחזיק שני אנשים מבלי שתתנועע.","\u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה\u0005]\u0006 מעין דברים אלה: \u0003המהלך בבית הפרס\u0004 כגון בשדה שיש ספק טומאת מת מתחתיו \u0003על גבי אבנים שיכול להסיט\u0004 בהליכתו, ויש לחשוש שמא הסיט איזו עצם של מת ונטמא משום כך, או שהיה רכוב \u0003על האדם\u0004 או \u0003על הבהמה שכוחן רע,\u0004 שאינם חזקים למדי — הרי זה \u0003טמא,\u0004 שנחשב כאילו הוא עצמו הזיז את הטומאה.","ושאלו: \u0003היכי דמי\u0004 \u0005[כיצד זה\u0006 בדיוק\u0005]\u0006 \u0003אדם שכוחו רע? אמר ריש לקיש: כל שרוכבו\u0004 (שרוכב עליו) \u0003וארכבותיו\u0004 (ברכיו) של המרכיב \u0003נוקשות\u0004 זו בזו. \u0003היכי דמי\u0004 \u0005[כיצד זה]\u0006 \u0003בהמה שכוחה רע? אמרי דבי\u0004 \u0005[אמרו בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי:\u0004 \u0003כל שרוכבה\u0004 אדם ובגלל במאמץ היא \u0003מטילה גללים.\u0004","כיון שהוזכרו דברי בית מדרש זה בענין שיעורים, מביאים עוד מה ש\u0003אמרי דבי\u0004 \u0005[אמרו בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי:\u0004 \u0003לתפלה ולתפילין\u0004 השיעור \u0003ארבעה קבין.\u0004","ושואלים: \u0003לתפלה מאי היא,\u0004 מה עניינו של שיעור זה? ומשיבים: \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הנושא משאוי על כתיפו והגיע זמן תפלה,\u0004 אם היה משאוי זה \u0003פחות מארבעה קבין\u0004 — \u0003מפשילין לאחוריו ומתפלל,\u0004 שמשאוי קל כזה איננו מפריע לאדם בתפילתו. היה המשא \u0003ארבעה קבין\u0004 — \u0003מניח\u0004 אותו \u0003על גבי קרקע ומתפלל.\u0004","\u0003לתפילין מאי\u0004 \u0005[מה עניינו]\u0006 — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003היה נושא משאוי על ראשו ותפילין בראשו, אם היו תפילין רוצצות\u0004 (נמעכות) תחת המשא — \u0003אסור\u0004 להשאיר את התפילין במקום, \u0003ואם לאו\u0004 \u0005[לא]\u0006 — \u0003מותר. באיזו משאוי אמרו\u0004 — \u0003במשאוי של ארבעת קבין.\u0004","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא: המוציא זבל על ראשו\u0004 והיו \u0003תפילין בראשו\u0004 — \u0003הרי זה לא יסלקם לצדדים\u0004 שלא ימעכו, וכן \u0003לא יקשרם במתניו, מפני שהוא נוהג בהן\u0004 על ידי כך \u0003מנהג בזיון. אבל קושרם על זרועו במקום תפילין\u0004 של יד.","\u0003משום דבי\u0004 \u0005[בשם בית\u0006 מדרשו\u0005]\u0006 של \u0003שילא\u0004 \u0003אמרו:\u0004 שאסור להניח על ראשו בשעה שמניח תפילין כל משאוי שהוא, ו\u0003אפילו מטפחת שלהן\u0004 (מטפחת שכורכים בה את התפילין) \u0003אסור להניח על הראש שיש בו תפילין.\u0004 ושואלים: \u0003וכמה\u0004 בכל זאת שיעור משאוי שמותר לשאת על הראש לדעת ר' שילא? \u0003אמר אביי:\u0004 \u0003אפילו\u0004 כדי \u0003רבעא דרבעא\u0004 \u0005[רבע של רביעית]\u0006 מן השיעור ב\u0003פומבדיתא\u0004 גם כן אסור להניח על הראש.","שנינו במשנה ש\u0003אמר ר' יהודה: מאי קצבה בכרי אלא\u0004 השיעור הוא: \u0003אם יש בו כדי נפילה,\u0004 שאם יש בתבואה הצומחת לפחות כדי כמות הזרעים שצריכים כדי לזרוע שדה זה. ושואלים: \u0003וכמה\u0004 השיעור המדוייק של \u0003כדי נפילה? ר' אמי אמר\u0004 בשם \u0003ר' יוחנן: ארבעה סאין לכור. ר' אמי דיליה\u0004 \u0005[שלו\u0006 מדעת עצמו\u0005]\u0006 \u0003אמר:\u0004 \u0003שמונת סאין לכור. אמר ליה ההוא סבא\u0004 \u0005[זקן אחד]\u0006 \u0003לרב חמא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבה בר אבוה: אסברה\u0004 \u0005[אסביר]\u0006 \u0003לך\u0004 את הענין: \u0003בשני\u0004 \u0005[בשנותיו,\u0006 בימיו\u0005]\u0006 של \u0003ר' יוחנן הוה שמינא ארעא\u0004 \u0005[היתה הארץ שמנה],\u0006 \u0003בשני\u0004 \u0005[בשנותיו,\u0006 בימיו\u0005]\u0006 של \u0003ר' אמי הוה כחישא ארעא\u0004 \u0005[היתה הארץ כחושה],\u0006 ולכן היה צורך להכפיל את כמות הזרעים שזורעים באותה יחידת קרקע.","\u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה\u0005]:\u0006 \u0003הרוח שפיזרה את העומרין\u0004 הסדורים, ואין יודעים עתה מה היה בשעתו לקט שנפל מן העומרים ושייך משום כך לעניים. \u0003אומדים אותה\u0004 את השדה \u0003כמה לקט\u0004 היא \u0003ראויה לעשות, ונותן לעניים. רבן שמעון בן גמליאל אומר: נותן לעניים כדי נפילה.\u0004","ושאלו: \u0003וכמה\u0004 שיעור \u0003כדי נפילה? כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשם \u0003ר' אלעזר ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' יוחנן: ארבעת קבין לכור. בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה:\u0004 האם הכוונה \u0003לכור זרע,\u0004 לשדה שיש לזרוע בו כור, או \u0003לכור תבואה,\u0004 שדה שיבולו הוא כור? וכן, האם מדובר כאן בזריעה ב\u0003מפולת יד,\u0004 שזורעים ביד, או \u0003למפולת שוורים\u0004 בכעין מכונת זריעה?","ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר \u0003דכי אתי\u0004 \u0005[שכאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' אבוה\u0004 ש\u0003אמר\u0004 בשם \u0003ר' אלעזר, ואמרי לה\u0004 \u0005[יש אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003ר' יוחנן: ארבעת קבין לכור זרע.\u0004 ומעירים: \u0003ועדיין תבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 השאלה: \u0003למפולת יד או למפולת שוורים?\u0004 ואכן לשאלה זו לא נמצאה תשובה ברורה ולכן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003המקבל שדה מחבירו ואכלה חגב, או נשדפה. אם מכת מדינה היא,\u0004 שאירע הדבר בכל השדות, \u0003מנכה לו מן חכורו,\u0004 שצריך בעל השדה לנכות מן הכמות שקצב לו. ו\u0003אם אינה מכת מדינה\u0004 — \u0003אין מנכה לו מן חכורו. ר' יהודה אומר: אם קיבלה הימנו\u0004 (ממנו) \u0003במעות,\u0004 כלומר, שהסכים מראש לשלם סכום מסויים של כסף — \u0003בין כך ובין כך אינו מנכה לו מחכורו.\u0004","שואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 ענין זה של \u0003מכת מדינה,\u0004 מתי אומרים אנו שהדבר הוא בגדר מכת מדינה? \u0003אמר רב יהודה: כגון דאי שדוף רובא דבאגא\u0004 \u0005[שנשתדפו רוב\u0006 שדות אותה \u0005בקעה]\u0006 המישור ששדה זה היה בו. \u0003עולא אמר: כגון שנשתדפו ארבע שדות מארבע רוחותיה.\u0004","\u0003אמר עולא: בעו במערבא\u0004 \u0005[היו שואלים בארץ ישראל]\u0006 את השאלות הבאות: \u0003נשדף תלם אחד על פני כולה\u0004 סמוך לשדות שנשדפו, \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 וכן להיפך: \u0003נשתייר תלם אחד על פני כולה, מהו?\u0004 אם \u0003אפסיקא בירא מאי\u0004 \u0005[הפסיק\u0006 שדה \u0005בור\u0006 בין השדות, \u0005מה\u0006 הדין\u0005]?\u0006 הפסיק שדה של \u0003אספסתא\u0004 \u0005[שחת]\u0006 בין שדה זה ושאר השדות שנשדפו,"],["\u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 הפסיק שדה של \u0003זרע אחר מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 ועוד: \u0003חיטי\u0004 \u0005[חיטים]\u0006 \u0003לגבי שעורים\u0004 האם \u0003כזרע אחר דמי\u0004 \u0005[נחשבים],\u0006 \u0003או לא?\u0004 ועוד: אם של \u0003כל העולם כולו\u0004 מסביב לקה \u0003בשדפון, ושלו\u0004 לקה \u0003בירקון, אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003כל העולם כולו\u0004 לקה \u0003בירקון ושלו\u0004 לקה \u0003בשדפון, מאי\u0004 \u0005[מה\u0006 דינו\u0005]?\u0006 לכל אחד מן הספיקות הללו לא נמצאה תשובה, ולכן \u0003תיקו\u0004 \u0005[יעמוד]\u0006 במקומו.","ועוד שאלה: \u0003אמר ליה\u0004 \u0005[לו]\u0006 בעל הבית לחוכר: \u0003זרעה חיטי\u0004 \u0005[\u0006\u0005זרע\u0006 את השדה \u0005חיטים],\u0006 \u0003ואזל\u0004 \u0005[והלך]\u0006 \u0003הוא\u0004 החוכר \u0003וזרעה שערי\u0004 \u0005[שעורים],\u0006 \u0003ואשתדוף רובא דבאגא\u0004 \u0005[והשתדפו רוב\u0006 שדות אותה \u0005בקעה],\u0006 \u0003ואשתדוף נמי הנך שערי דיליה\u0004 \u0005[והשתדפו גם כן שעורים אלה שלו],\u0006 \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 \u0003מי אמרינן דאמר ליה\u0004 \u0005[האם אומרים אנו\u0006 שיכול החוכר \u0005לומר לו]\u0006 לבעל השדה: \u0003אילו זרעתה חיטי הוה נמי משתדפא\u0004 \u0005[אילו הייתי זורעה חיטים היתה גם כן משתדפת]\u0006 שהרי סביב השתדף הכל, \u0003או דלמא מצי אמר ליה\u0004 \u0005[שמא יכול לומר לו\u0006 המחכיר\u0005]\u0006 \u0003אילו זרעתה חיטי\u0004 \u0005[אילו היית זורע אותה חיטים]\u0006 \u0003הוה מקיים\u0004 \u0005[היה מתקיים]\u0006 \u0003בי\u0004 מה שנאמר \u0003\"ותגזר אמר ויקם\u0004 \u0003לך\u0004 ועל דרכך נגה אור","\u0003\"\u0004(איוב כב, כח), ושמא היתה זכותי גורמת שיעשו משמים שיתמלא רצוני, וכיון ששינית ממה שבקשתי — לא נתקיים בי הדבר. ומשיבים: \u0003מסתברא דאמר\u0004 \u0005[מסתבר ש\u0006יכול הוא \u0005לומר]\u0006 \u0003אי זרעתה חיטי הוה מקיים\u0004 \u0005[אילו היה זורעה חיטים\u0006 \u0005היה מתקיים]\u0006 \u0003בי\u0004 מה שנאמר \u0003\"ותגזר אמר ויקם לך ועל דרכיך נגה אור\".\u0004","ועוד שאלה: \u0003נשתדפו כל שדותיו של\u0004 ה\u0003מחכיר, ואשתדוף נמי הא בהדייהו\u0004 \u0005[והשתדף גם\u0006 שדה \u0005זה אתם],\u0006 \u0003ולא אשתדוף רובא דבאגא מאי\u0004 \u0005[השתדפו רוב\u0006 שדות אותה \u0005בקעה, מה\u0006 הדין\u0005]?\u0006 \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 כי \u0003כיון\u0004 ש\u0003לא אשתדוף רובא דבאגא\u0004 \u0005[השתדפו רוב\u0006 שדות אותה \u0005בקעה]\u0006 \u0003לא מנכי ליה\u0004 \u0005[מנכה לו]\u0006 החוכר מן החכירה, שהרי אין זו מכת מדינה, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון דאשתדוף כולהו ארעתיה\u0004 \u0005[שהשתדפו כל אדמותיו]\u0006 של המחכיר, \u0003מצי אמר ליה\u0004 \u0005[יכול\u0006 החוכר \u0005לומר\u0006 \u0003לו]\u0004 למחכיר: \u0003האי\u0004 \u0005[זה]\u0006 \u0003משום לתך דידך\u0004 \u0005[מזלך שלך]\u0006 \u0003הוא, דהא משתדפו\u0004 \u0005[שהרי השתדפו]\u0006 \u0003כל שדותיך.\u0004","ומשיבים: \u0003מסתברא דאמר ליה\u0004 \u0005[מסתבר ש\u0006יכול \u0005לומר לו]\u0006 לחוכר: \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום לתאי דידי\u0004 \u0005[מזלי שלי]\u0006 — \u0003הוה משתייר\u0004 \u0005[היה נשאר]\u0006 \u0003לי פורתא\u0004 \u0005[מעט],\u0006 \u0003כדכתיב\u0004 \u0005[כפי שנאמר]\u0006 \u0003\"כי נשארנו מעט מהרבה\"\u0004 (ירמיה מב, ב) שאף בגללה אין היא מכלה הכל.","ועוד שאלה: \u0003נשתדפו כל שדותיו של\u0004 ה\u0003חוכר ואשתדוף רובא דבאגא\u0004 \u0005[והשתדפו רוב\u0006 שדות אותה \u0005הבקעה],\u0006 \u0003ואשתדוף נמי הא בהדייהו\u0004 \u0005[והשתדף גם\u0006 שדה \u0005זה עמם]\u0006 \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 כי \u0003כיון דאשתדוף רובא דבאגא מנכי ליה\u0004 \u0005[שהשתדפו רוב\u0006 שדות אותה \u0005בקעה\u0006 הריהו \u0005מנכה לו],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון דאשתדוף כולהו ארעתיה\u0004 \u0005[שנשתדפו כל אדמותיו]\u0006 של החוכר, \u0003מצי אמר ליה\u0004 \u0005[\u0006יכול המחכיר \u0005לומר לו]\u0006 לחוכר: \u0003משום לתך דידך\u0004 \u0005[מזלך שלך]\u0006 \u0003הוא, דהא משתדפו\u0004 \u0005[שהרי השתדפו]\u0006 \u0003כל שדותיך.\u0004 ומשיבים: \u0003מסתברא דאמר ליה\u0004 \u0005[מסתבר ש\u0006יכול המחכיר \u0005לומר לו]\u0006 לחוכר: \u0003משום לתאך\u0004 \u0005[משום מזלך]\u0006 \u0003הוא.\u0004","ושואלים \u0003אמאי\u0004 \u0005[מדוע]?\u0006 \u0003הכא נמי נימא ליה\u0004 \u0005[כאן גם כן יאמר לו]\u0006 החוכר למחכיר: \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום לתאי דידי\u0004 \u0005[מזלי שלי]\u0006 \u0003הוא\u0004 — \u0003הוה משייר\u0004 \u0005[היה\u0006 \u0003נשאר]\u0004 \u0003לי פורתא\u0004 \u0005[מעט],\u0006 \u0003דהוה מקיים\u0004 \u0005[שהיה מתקיים]\u0006 \u0003בי\u0004 מה שנאמר \u0003\"כי נשארנו מעט מהרבה\"\u0004 ומשיבים: \u0003משום דאמר ליה\u0004 \u0005[ש\u0006יכול \u0005לומר לו]\u0006 המחכיר לחוכר: \u0003אי הוה חזית לאישתיורי\u0004 \u0005[אם היה ראוי שישתייר]\u0006 \u0003לך מידי\u0004 \u0005[דבר]\u0006 — \u0003הוה משתייר\u0004 \u0005[היה נשאר]\u0006 \u0003לך מדנפשך\u0004 \u0005[משלך]\u0006 מאדמתך הפרטית ולא מזו שחכרת.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו: \u0003היתה שנת שדפון וירקון או שביעית\u0004 (שמיטה), או \u0003שהיו שנים כשני אליהו\u0004 שאין גשם כלל — \u0003אינו עולה לו מן המנין\u0004 של שנות החכירה.","\u0003קתני\u0004 \u0005[שנה\u0006 שם\u0005]\u0006 \u0003שדפון וירקון דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003שנים כשני אליהו, מה שני אליהו\u0004 — פירושו ש\u0003לא הוי\u0004 \u0005[היתה\u0006 אז\u0005]\u0006 \u0003תבואה כלל,\u0004 אף \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר באופן ש\u0003לא הוי\u0004 \u0005[היתה]\u0006 \u0003תבואה כלל, אבל\u0004 באופן \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003תבואה\u0004 כלשהי — \u0003סלקא ליה\u0004 \u0005[עולה לו\u0006 מן החשבון\u0005],\u0006 \u0003ולא קאמרינן\u0004 \u0005[ואין אנו אומרים]\u0006 \u0003מכת מדינה היא!\u0004","\u0003אמר רב נחמן בר יצחק: שאני התם\u0004 \u0005[שונה שם],\u0006 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 לענין מכירת וחכירת שדות: \u0003\"במספר שני תבואת ימכר\u0004 \u0003לך\"\u0004 (ויקרא כה, טו), שמשמעו: \u0003שנים שיש בהן תבואה בעולם.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לרב כהנא: אלא מעתה שביעית תעלה לו מן המנין, דהא איכא\u0004 \u0005[שהרי יש]\u0006 \u0003תבואה בחוצה לארץ\u0004 על כל פנים! \u0003אמר ליה: שביעית אפקעתא דמלכא\u0004 \u0005[הפקעה של מלך]\u0006 \u0003היא,\u0004 כלומר, הקדוש ברוך הוא הפקיע אותה, וממילא גזר עליה שלא תיכנס בחשבון.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב\u0004 \u0003מרי לרבינא: אלא מעתה,\u0004 שהשביעית מופקעת ונחשבת כבטלה לגמרי, \u0003שביעית לא תעלה לו מן הגירוע,\u0004 שלא יחשב אותה בתוך חשבון השנים שהוא מגרע ממחיר השדה כשפודים אותו, \u0003אלמה תנן\u0004 \u0005[מדוע שנינו\u0006 במשנה שם\u0005]:\u0006 \u0003נותן סלע ופונדיון לשנה\u0004 לפי החשבון האמור בתורה, ואם מדקדקים בחישוב מוצאים שנותן גם עבור שנת השביעית! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שאני התם דחזיא למישטחא\u0004 \u0005[שונה שם שראוייה\u0006 היא \u0005לשטוח]\u0006 \u0003בה פירי\u0004 \u0005[פירות],\u0006 ואם כי איננו יכול להשתמש בשדה לזריעה, הרי יכול להשתמש בשדה לכל צורך אחר.","\u0003אמר שמואל: לא שנו\u0004 כן \u0003אלא\u0004 באופן \u0003שזרעה\u0004 החוכר \u0003וצמחה ואכלה חגב\u0004 או זרע בה דבר אחר, \u0003אבל\u0004 אם \u0003לא זרעה כלל\u0004 — \u0003לא,\u0004 שאין אנו מקילים על החוכר, אפילו היתה זו מכת מדינה. ומדוע — \u0003דאמר ליה\u0004 \u0005[ש\u0006יכול המחכיר \u0005לומר לו]\u0006 לחוכר: \u0003אילו זרעתה הוה מקיים\u0004 \u0005[היית זורע אותה היה מתקיים]\u0006 \u0003בי\u0004 מה שנאמר: \u0003\"לא יבשו בעת רעה ובימי רעבון ישבעו\"\u0004 (תהילים לז, יט), כלומר, שמא זכותי היתה גורמת שמכת המדינה לא היתה פוגעת בשדותי.","\u0003מתיב\u0004 \u0005[מקשה\u0006 על כך\u0005]\u0006 \u0003רב ששת\u0004 ממה ששנינו: \u0003רועה שהיה רועה\u0004 בהמות של אחרים \u0003והניח עדרו ובא לעיר,\u0004 \u0003ו\u0004בינתים \u0003בא זאב וטרף, ובא ארי ודרס\u0004 — \u0003אין אומרים: אילו היה שם היה מציל, אלא אומדין אותו; אם יכול\u0004 היה \u0003להציל\u0004 מחיה רעה זו — \u0003חייב, ואם לאו\u0004 \u0005[לא]\u0006 היה בכוחו להציל — \u0003פטור.\u0004 ולפי שיטתך זו, \u0003ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003נימא ליה\u0004 \u0005[שיאמר לו]\u0006 בעל הבהמות: \u0003אי הוית התם הוה מקיים\u0004 \u0005[אילו היית שם היה מתקיים]\u0006 \u0003בי\u0004 מה שנאמר: \u0003\"גם את הארי גם את הדוב הכה עבדך\"\u0004 (שמואל א' יז, לו)!","ומשיבים: \u0003משום דאמר ליה\u0004 \u0005[\u0006שיכול \u0005לומר לו]\u0006 הרועה לבעל הבהמות: \u0003אי הוית חזית לאיתרחושי\u0004 \u0005[אם היית ראוי שיתרחש]\u0006 \u0003לך ניסא\u0004 \u0005[נס]\u0006 \u0003הוה איתרחיש\u0004 \u0005[היה מתרחש]\u0006 \u0003לך ניסא\u0004 \u0005[נס]\u0006 \u0003כ\u0004מו שאירע ל\u0003ר' חנינא בן דוסא\u0004 \u0003דמתיין עיזי דובי בקרנייהו\u0004 \u0005[שהביאו העיזים דובים בקרניהן]\u0006 בלא כל צורך של סיוע מצד הרועה. ושואלים: \u0003ונימא ליה\u0004 \u0005[ושיאמר לו]\u0006 בעל הבהמות לרועה: \u0003נהי דלניסא רבה\u0004 \u0005[אם אמנם שלנס גדול]\u0006 \u0003לא הוה חזינא\u0004 \u0005[הייתי ראוי],\u0006 מכל מקום \u0003לניסא זוטא\u0004 \u0005[לנס קטן\u0006\u0005]\u0006"],["\u0003חזינא\u0004 \u0005[אני ראוי],\u0006 ומשיבים: אכן \u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר.","\u0003תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]:\u0006 \u0003פעם ראשונה ושניה\u0004 — \u0003זורעה\u0004 את השדה אם היתה תקלה שגרמה לאבד את הזרעים ופעם \u0003שלישית אינו זורעה.\u0004 \u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 פעם \u0003שלישית\u0004 — \u0003זורעה,\u0004 ופעם \u0003רביעית\u0004 — \u0003אינו זורעה.\u0004 ואם כן ישנה סתירה! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין זה קשה];\u0006 \u0003הא\u0004 \u0005[זו]\u0006 \u0003כ\u0004שיטת \u0003רבי,\u0004 \u0003הא\u0004 \u0005[זו]\u0006 \u0003כ\u0004שיטת אביו \u0003רבן שמעון בן גמליאל.\u0004","ומסבירים: \u0003הא\u0004 \u0005[זו]\u0006 \u0003כ\u0004שיטת \u0003רבי,\u0004 ש\u0003אמר\u0004 את הכלל: \u0003בתרי זימני הוי\u0004 \u0005[בשתי פעמים היא]\u0006 \u0003חזקה\u0004 \u0005[חזקה],\u0006 \u0003והא\u0004 \u0005[וזו]\u0006 \u0003כ\u0004שיטת \u0003רבן שמעון בן גמליאל\u0004 ש\u0003אמר: בתלת זימני הוי\u0004 \u0005[בשלוש פעמים היא]\u0006 \u0003חזקה.\u0004","\u0003אמר ריש לקיש: לא שנו\u0004 שהאריס זורע רק מספר פעמים \u0003אלא שזרעה וצמחה ואכלה חגב, אבל\u0004 אם \u0003זרעה ולא צמחה\u0004 כלל — \u0003מצי אמר ליה\u0004 \u0005[יכול לומר לו]\u0006 \u0003בעל הקרקע: כל ימי זרע זרעא לה ואזיל\u0004 \u0005[זמן ימי הזריעה זרע אותה ולך].\u0006 ושואלים: \u0003ועד אימת\u0004 \u0005[מתי]\u0006 הוא זמן הזריעה? \u0003אמר רב פפא: עד\u0004 אותו זמן \u0003דאתו אריסי מדברא\u0004 \u0005[שבאים האריסים מן השדה]\u0006 \u0003וקיימא\u0004 \u0005[ועומד]\u0006 כוכב \u0003כימה ארישייהו\u0004 \u0005[על ראשיהם],\u0006 שהוא בערך בחודש שבט.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך מברייתא המפרשת את הכתוב \"עוד כל ימי הארץ זרע וקציר וקור וחום וקיץ וחורף ויום ולילה לא ישבותו\" (בראשית ח, כב) כמתייחס לשש עונות השנה: \u0003רבן שמעון בן גמליאל משום\u0004 \u0005[בשם]\u0006 \u0003ר' מאיר אומר, וכן היה ר' שמעון בן מנסיא אומר כדבריו:\u0004 ה\u0003חצי\u0004 השני של חודש \u0003תשרי,\u0004 חודש \u0003מרחשון\u0004 כולו, \u0003וחצי\u0004 הראשון של חודש \u0003כסליו\u0004 — הן ימי ה\u0003זרע,\u0004 ה","\u0003חצי\u0004 השני של חודש \u0003כסליו,\u0004 חודש \u0003טבת\u0004 כולו\u0003,\u0004 \u0003וחצי\u0004 הראשון של חודש \u0003שבט\u0004 — הם ימי ה\u0003חורף,\u0004 ה\u0003חצי\u0004 השני של חודש \u0003שבט,\u0004 חודש \u0003אדר\u0004 כולו, \u0003וחצי\u0004 הראשון של חודש \u0003ניסן\u0004 — \u0003קור,\u0004 ה\u0003חצי\u0004 השני של חודש \u0003ניסן,\u0004 חודש \u0003אייר\u0004 כולו, \u0003וחצי\u0004 הראשון של חודש \u0003סיון\u0004 — הוא הקרוי \u0003קציר,\u0004 ה\u0003חצי\u0004 השני של חודש \u0003סיון,\u0004 חודש \u0003תמוז\u0004 כולו, \u0003וחצי\u0004 הראשון של חודש \u0003אב\u0004 — הוא \u0003קיץ,\u0004 ה\u0003חצי\u0004 השני של חודש \u0003אב,\u0004 חודש \u0003אלול\u0004 כולו, \u0003וחצי\u0004 הראשון של חודש \u0003תשרי\u0004 — \u0003חום.\u0004","ומעירים: \u0003רבי יהודה מונה מ\u0004תחילת חודש \u0003תשרי,\u0004 כלומר, אף הוא היה מחלק את השנה לשש עונות אלה, אלא שהוא היה מתחיל את החשבון לא ממחצית החודש אלא מתחילתו, וכן \u0003ר' שמעון מונה\u0004 חודשים שלמים, כשלדעתו הכל מתחיל \u0003ממרחשון,\u0004 שמרחשון וכסלו הם \"זרע\", וכן הלאה.","ושואלים: \u0003מאן\u0004 \u0005[מי הוא]\u0006 ה\u0003מיקל בכולהו\u0004 \u0005[בכולם]\u0006 שמאריך את זמן הזרע — הלא הוא \u0003ר' שמעון, וכולי האי\u0004 \u0005[וכל זה]\u0006 עד לזמן שעומד כוכב כימה על ראשם \u0003לא קאמר\u0004 \u0005[אמר]!\u0006 ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה];\u0006 \u0003הא דקבלה מיניה בחרפי, הא דקבלה מיניה באפלי\u0004 \u0005[זה שקבל ממנו\u0006 לזרוע מינים \u0005מקדימים,\u0006 \u0005ביכורים,\u0006 \u0005וזה שקיבל ממנו באפילים],\u0006 שמינים אפילים נזרעים הרבה יותר מאוחר.","שנינו במשנה ש\u0003רבי יהודה אומר: אם קבלה ממנו\u0004 האריס מבעל הבית \u0003במעות,\u0004 ולא בחלק מן היבול, בין כך ובין כך, גם אם היתה מכת מדינה — משלם. מסופר: \u0003ההוא גברא דקביל ארעא למיזרעה בהו תומי אגודא\u0004 \u0005[אדם אחד קיבל קרקע לזרוע בה שום על שפת]\u0006 \u0003נהר מלכא סבא בזוזי\u0004 \u0005[בכספים],\u0006 כלומר, עבור סכום כסף מסוים. \u0003איסתכר\u0004 \u0005[נסכר,\u0006 נסתם\u0005]\u0006 משום מה \u0003נהר מלכא סבא.\u0004 \u0003אתא לקמיה\u0004 \u0005[בא\u0006 הדין \u0005לפני]\u0006 \u0003רבא\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003נהר מלכא סבא לא עביד דמיסכר\u0004 \u0005[אינו עשוי להיסכר],\u0006 ואם קורה דבר כזה הרי \u0003מכת מדינה היא,\u0004 ולפיכך \u0003זיל נכי ליה\u0004 \u0005[לך נכה לו]\u0006 בגלל ההפסד הזה.","\u0003אמ\u0004 \u0003רו ליה רבנן\u0004 \u0005[לו חכמים]\u0006 \u0003לרבא: הא אנן תנן\u0004 \u0005[הרי אנו שנינו\u0006 במשנה\u0005]\u0006 ש\u0003ר' יהודה אומר: אם קבלה הימנו\u0004 (ממנו) \u0003במעות\u0004 — \u0003בין כך ובין כך אינו מנכה לו מן חכורו\u0004 (שכר החכירה)! \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003לית דחש לה\u0004 \u0005[אין מי שחושש ל\u0006הלכה \u0005זו]\u0006 של \u0003ר' יהודה,\u0004 כלומר, דברי יחיד הם ונדחו מן ההלכה.","\u0003המקבל שדה מחבירו\u0004 לעבד את השדה עבור תשלום של \u0003עשרה כור חטים לשנה ולקתה\u0004 תבואת השדה במחלה וכיוצא בזה — \u0003נותן לו מתוכה,\u0004 כלומר, נותן לו עשרה כור מן החטים שבאותו שדה, ואינו חייב לתת חטים יפות. וכן אם \u0003היו חטיה יפות\u0004 ביותר הרי \u0003לא יאמר לו\u0004 לבעל השדה: \u0003הריני לוקח מן השוק\u0004 חטים רגילות, \u0003אלא נותן לו מתוכה.\u0004","\u0003ההוא גברא דקביל ארעא לאספסתא בכורי דשערי\u0004 \u0005[אדם אחד קיבל אדמה\u0006 לגדל בה \u0005אספסת עבור כורים של שעורים],\u0006 \u0003עבדא אספסתא\u0004 \u0005[עשתה\u0006 השדה \u0005אספסת].\u0006 אחר כך \u0003חרשה וזרעה\u0004 אותו אדם \u0003שערי\u0004 \u0005[שעורים],\u0006 \u0003ולקו הני שערי\u0004 \u0005[אותם שעורים],\u0006 ורצה המקבל לשלם את כורי השעורים מן השעורים הלקויות הללו. \u0003שלחה רב חביבא מסורא דפרת\u0004 לאותה בעיה \u0003לקמיה\u0004 \u0005[לפני]\u0006 \u0003רבינא,\u0004 ושאלו: \u0003כי האי גונא מאי\u0004 \u0005[כגון זה מהו]?\u0006 האם \u0003כי\u0004 \u0005[כמו]\u0006 \u0003\"לקתה נותן לו מתוכה\" דמי\u0004 \u0005[נחשב\u0006 הדבר\u0005],\u0006 \u0003או לא?\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מי דמי\u0004 \u0005[האם דומה]?\u0006 \u0003התם\u0004 \u0005[שם\u0006 במשנתנו \u0005]\u0006 \u0003לא עבדא ארעא שליחותא דמרה\u0004 \u0005[עשתה האדמה את שליחות בעליה]\u0006 וגם המקבל קיבל תבואה לקויה, \u0003הכא עבדא ארעא שליחותא דמרה\u0004 \u0005[כאן\u0006 הרי \u0005עשתה האדמה את שליחות בעליה],\u0006 שהרי חכרה לאספסת, ואספסת זו הצליחה. ומה שהוסיף וזרע בה שעורים — אינו בגדר ההסכם, ואינו רשאי לשלם בשעורים לקויות.","\u0003ההוא גברא\u0004 \u0005[אדם אחד]\u0006 ש\u0003קבל פרדס מחבריה\u0004 \u0005[מחבירו],\u0006 \u0003בעשר דני חמרא\u0004 \u0005[כדי יין],\u0006 \u0003תקיף ההוא חמרא\u0004 \u0005[החמיץ אותו היין]\u0006 מהפרדס. \u0003סבר רב כהנא למימר\u0004 \u0005[לומר]:\u0006 \u0003היינו מתניתין\u0004 \u0005[זוהי משנתנו]\u0006 ששנינו בה: \u0003לקתה\u0004 — \u0003נותן לו מתוכה. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי: מי דמי\u0004 \u0005[האם דומה\u0006 הדבר\u0005]?\u0006 \u0003התם\u0004 \u0005[שם\u0006 במשנה\u0005]\u0006 \u0003לא עבדא ארעא שליחותא\u0004 \u0005[עשתה האדמה את שליחותה]\u0006 והיה היבול לקוי, \u0003הכא עבדא ארעא שליחותא\u0004 \u0005[כאן עשתה האדמה שליחותה]\u0006 והיו הענבים כדרכן, וזה שהחמיץ היין — בחלקו של המעבד החמיץ, ואין לבעל השדה קשר עם הדבר.","ומעירים: \u0003ומודה רב אשי בעינבי דכדום\u0004 (בענבים שהצטמקו בגדילתם) \u0003ובשדה שלקתה בעומריה,\u0004 שכיון שהיה הפגם ביבול השדה עצמו יכול החוכר לשלם מתוך מה שגדל בשדה.","\u0003המקבל שדה מחבירו\u0004 על מנת \u0003לזרעה שעורים\u0004 — \u0003לא יזרענה חטים,\u0004 כי החטים מנצלות יותר את השדה. אבל אם קבלה לזרוע בה \u0003חטים,\u0004 אם רוצה — \u0003יזרענה שעורים. רבן שמעון בן גמליאל אוסר.\u0004 וכן כיוצא בזה אם קיבלה לזרוע בה \u0003תבואה\u0004 — \u0003לא יזרענה קטנית\u0004 שמנצלת את השדה, אם קבלה ל\u0003קטנית\u0004 — \u0003יזרענה תבואה, ורבן שמעון בן גמליאל אוסר.\u0004","\u0003אמר רב חסדא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רבן שמעון בן גמליאל,\u0004 שהרי לכאורה אין בעל השדה מפסיד כלל? ומסביר: טעמו הוא \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"שארית ישראל לא יעשו עולה ולא ידברו כזב ולא ימצא בפיהם לשון תרמית\"\u0004 (צפניה ג, יג), כלומר, אסור לאדם לשנות ממה שקיבל על עצמו גם כאשר אין בזה הפסד לאחרים.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על הסבר זה\u0005]\u0006 ממה ששנינו: \u0003מגבת פורים\u0004 כסף שגובים בפורים הרי זה \u0003ל\u0004צרכי \u0003פורים\u0004 של העניים, \u0003ואין מדקדקין בדבר. ואין העני רשאי ליקח מהן רצועה לסנדלו\u0004 אלא לצרכי הסעודה בלבד, \u0003אלא אם כן התנה במעמד אנשי העיר\u0004 שישתמש בכסף לכל צרכו, אלו \u0003דברי ר' יעקב שאמר משום\u0004 \u0005[בשם]\u0006 \u0003ר' מאיר. רבן שמעון בן גמליאל\u0004"],["\u0003מיקל,\u0004 שהוא סבור שאין הנותנים מקפידים בכך. אם כן, משמע שרבן שמעון בן גמליאל איננו מקפיד על שינוי דעת כשאין בכך נזק.","\u0003אמר אביי: טעמא\u0004 \u0005[הטעם]\u0006 של \u0003רבן שמעון\u0004 בן גמליאל הוא \u0003כדמר\u0004 \u0005[כ\u0006דברי \u0005האדון,\u0006 כלומר, רבו רבה\u0005].\u0006 ש\u0003אמר מר\u0004 \u0005[הרב,\u0006 רבה\u0005]:\u0006 \u0003האי מאן דניחא ליה דתתבור ארעיה\u0004 \u0005[מי שרוצה שתהיה בורה בקרקעו],\u0006 כלומר, שיגדל בה תבואה, ובכל זאת תיחשב כאילו הניחה בורה ולא ניצלה — \u0003ליזרעה שתא חטי ושתא שערי\u0004 \u0005[שיזרע אותה שנה\u0006 אחת \u0005חטים ושנה\u0006 אחת \u0005שעורים],\u0006 \u0003שתא\u0004 \u0005[שנה\u0006 אחת\u0005]\u0006 \u0003שתי ושתא\u0004 \u0005[ושנה\u0006 אחת\u0005]\u0006 \u0003ערב,\u0004 שעל ידי כך לא יתקלקל השדה לגמרי.","ומעירים: \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 שזריעת שדה שנה אחר שנה מזיקה, \u0003אלא\u0004 רק באופן \u0003דלא כריב ותני\u0004 \u0005[שאינו חורש ושונה],\u0006 \u0003אבל\u0004 אם הוא \u0003כריב ותני\u0004 \u0005[חורש ושונה]\u0006 — \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 חשש זה. וטעמו של רבן שמעון בן גמליאל הוא איפוא שהחלפת היבולים שלא בשעתה יכולה לגרום נזק לשדה.","שנינו במשנה שאם קיבל לזרוע בה \u0003תבואה\u0004 — \u0003לא יזרענה קטנית.\u0004 \u0003מתני ליה\u0004 \u0005[[היה משנה לו,\u0006 מלמדו\u0005]\u0006 \u0003רב יהודה לרבין:\u0004 אם קבלה לגדל \u0003תבואה\u0004 — \u0003יזרענה קטנית. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003והא אנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה\u0005]:\u0006 \u0003תבואה\u0004 — \u0003לא יזרענה קטנית! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא קשיא\u0004 \u0005[אינו קשה];\u0006 \u0003הא לן והא להו\u0004 \u0005[זה לנו וזה להם],\u0006 כלומר, תלוי הדבר במקומות, שבארץ ישראל שהאדמה כחושה — יש לחשוש לנזק, ובבבל אין לחשוש לכך.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יהודה לרבין בר רב נחמן: רבין אחי, הני תחלי דבי כתנא\u0004 \u0005[אותם שחלים\u0006 הגדלים בתוך \u0005הפשתה]\u0006 \u0003אין בהן משום גזל,\u0004 שמותר לתלוש ולקחת מהן, שבסופו של דבר הריהו כמנכש את השדה, אבל אם \u0003עומדות על גבולין\u0004 — \u0003יש בהן משום גזל,\u0004 שמן הסתם זרעום הבעלים בשולי השדה, כדי שיהיו להם גם מעט שחלים.","\u0003ואם הוקשו לזרע,\u0004 שכבר גדלו השחלים עד שהתקשו ויש בהם זרע — \u0003אפילו\u0004 היו \u0003דבי כתנא נמי\u0004 \u0005[בתוך הפשתן גם כן]\u0006 \u0003יש בהם משום גזל. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003מאי דאפסיד\u0004 \u0005[מה שהפסידו,\u0006 גרמו הפסד\u0005]\u0006 — כבר \u0003אפסיד\u0004 \u0005[הפסידו]\u0006 והזיקו לגידול הפשתן, ואם ליקטם עכשיו אינו מועיל לשדה ורק לוקח דבר מבעליו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יהודה לרבין בר רב נחמן: רבין אחי, הני דילי\u0004 \u0005[אלה שלי]\u0006 — \u0003די\u0004 \u0003לך\u0004 \u0005[שלך\u0006 הם\u0005],\u0006 \u0003ודי\u0004 \u0003לך\u0004 \u0005[ושלך]\u0006 — \u0003דילי\u0004 \u0005[שלי\u0006 הם\u0005],\u0006 כי לרבין בר רב נחמן ולרב יהודה היו שדות סמוכים, והיו האילנות נוטים משדה לשדה, ואמר לו: יכול להיות שפירות אילנות שלי יהיו שלך, ולהיפך. כי \u0003נהוג בני מצרא\u0004 \u0005[נוהגים\u0006 אנשים ששדותיהם על אותו \u0005מיצר\u0006 זה על יד זה\u0005]\u0006 ש\u0003אילן הנוטה לכאן,\u0004 לצד זה של השדה — פירותיו שייכים \u0003לכאן,\u0004 לאותו צד, \u0003והנוטה לכאן,\u0004 לצד האחר — \u0003לכאן.\u0004 ואין מקפידים מקרקעו של מי צמח.","\u0003דאיתמר\u0004 \u0005[ששמר]\u0006 שחלקו אמוראים בבעיה זו: \u0003אילן העומד על המיצר,\u0004 \u0003אמר רב: הנוטה לכאן\u0004 — \u0003לכאן. והנוטה לכאן\u0004 — \u0003לכאן, ושמואל אמר: חולקין\u0004 שני בעלי השדות בכל הפירות.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא: \u0003אילן העומד על המיצר\u0004 — \u0003יחלוקו,\u0004 והרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על שיטת \u0003רב!\u0004 ומעירים, \u0003תרגמא\u0004 \u0005[הסביר אותה]\u0006 \u0003שמואל אליבא\u0004 \u0005[לפי שיטתו]\u0006 של \u0003רב,\u0004 שכן מדובר \u0003ב\u0004אופן ש\u0003ממלא\u0004 האילן את \u0003כל המיצר כולו\u0004 ונמצא ששייך לשניהם.","ומקשים: \u0003אי הכי, מאי למימרא\u0004 \u0005[אם כך\u0006 שהוא ממלא את כל המיצר, \u0005מה יש לומר],\u0006 מה חידש בכך רב, הלא אז מובן מעצמו שכך הוא! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא לאופן \u0003דתלי טוניה לחד גיסא\u0004 \u0005[שתלוי נופו\u0006 יותר \u0005לצד אחד].\u0006 ושואלים: \u0003ואכתי מאי למימרא\u0004 \u0005[ועדיין מה\u0006 בא \u0005לומר],\u0006 מה החידוש בכך? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 ש\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003פלוג הכי\u0004 \u0005[\u0006בא \u0005נחלק כך],\u0006 שכל אחד יקבל לפי הפירות שצומחים בחלקו, על כן \u0003קא משמע לן\u0004 \u0003דאמר ליה\u0004 \u0005[השמיע לנו ש\u0006יכול \u0005לומר לו]:\u0006 \u0003מאי חזית דפלגת הכי\u0004 \u0005[מה ראית לחלק כך]\u0006 — \u0003פלוג הכי\u0004 \u0005[חלוק כך]\u0006 לרוחב האילן, ואז חלקינו שוים זה לזה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יהודה לרבין בר רב נחמן: רבין אחי, לא תזבין ארעא דסמיכא למתא\u0004 \u0005[אל תקנה קרקע הסמוכה לעיר],\u0006 ש\u0003אמר ר' אבהו אמר רב הונא אמר רב: אסור לו לאדם שיעמוד על שדה חבירו בשעה שעומדת בקמותיה,\u0004 כלומר, כשיש קמה בשדה, משום שיכול לגרום לה על ידי כך לנזק בעין הרע.","ושואלים: \u0003איני\u0004 \u0005[וכי כן הוא]?\u0006 \u0003והא אשכחינהו\u0004 \u0005[והרי מצאם]\u0006 \u0003ר' אבא לתלמידיה\u0004 \u0005[את תלמידיו]\u0006 של \u0003רב\u0004 ו\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 \u0003אמר רב בהני קראי\u0004 \u0005[ב\u0006פירוש \u0005הפסוקים הללו]\u0006 של הברכות \u0003\"ברוך אתה בעיר וברוך אתה בשדה\"\u0004 (דברים כח, ג), \u0003\"ברוך אתה בבאך וברוך אתה בצאתך\"\u0004 (שם ו)?","\u0003ואמרו ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב\u0004 לפרש: \u0003\"ברוך אתה בעיר\"\u0004 — \u0003שיהא ביתך סמוך לבית הכנסת. \"ברוך אתה בשדה\"\u0004 — \u0003שיהו נכסיך קרובים לעיר. \"ברוך אתה בבאך\"\u0004 — \u0003שלא תמצא אשתך\u0004 כשהיא \u0003ספק נדה בשעת ביאתך מן הדרך\u0004 ומחמת הספק אסורה היא עליך. \u0003\"ברוך אתה בצאתך\"\u0004 — \u0003שיהו צאצאי מעיך כמותך.\u0004","\u0003ואמר להו\u0004 \u0005[להם]\u0006 ר' אבא: \u0003ר' יוחנן לא אמר\u0004 לפרש \u0003הכי\u0004 \u0005[כך],\u0006 \u0003אלא\u0004 כך אמר: \u0003\"ברוך אתה בעיר\"\u0004 — \u0003שיהא בית הכסא סמוך לשולחנך, אבל\u0004 את ענין \u0003בית הכנסת לא\u0004 הזכיר. ומסבירים: \u0003ור' יוחנן לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 ש\u0003אמר:\u0004 \u0003שכר פסיעות יש,\u0004 שאדם מקבל שכר עבור הפסיעות שהוא פוסע למקום מצווה, ואם בית הכנסת סמוך לו — נמצא שאינו מקבל שכר על כך.","\u0003\"ברוך אתה בשדה\"\u0004 — \u0003שיהו נכסיך משולשין,\u0004 מחולקין לשלושה חלקים: \u0003שליש בתבואה, שליש בזיתים ושליש בגפנים. \"ברוך אתה בבאך וברוך אתה בצאתך\"\u0004 — \u0003שתהא יציאתך מן העולם כביאתך לעולם; מה ביאתך לעולם בלא חטא\u0004 — \u0003אף יציאתך מן העולם\u0004 תהא \u0003בלא חטא.\u0004"],["\u0003לא קשיא\u0004 \u0005[אין זה קשה];\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו בדעת רב שנכס הסמוך לעיר יש בו ברכה, הרי זה באופן \u0003דמהדר ליה שורא ורתקא\u0004 \u0005[שסובבת אותו חומה ומחיצה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו להיפך, הרי זה באופן \u0003דלא מהדר ליה שורא ורתקא\u0004 \u0005[זה שאין סובבת אותו חומה ומחיצה].\u0006","אגב הדברים שהזכרנו בענייני ברכה וכיוצא בהם מביאים עניינים דומים אחרים. נאמר \u0003\"והסיר ה' ממך כל חלי\"\u0004 (דברים ז, טו), \u0003אמר רב:\u0004 \"כל חולי\" \u0003זו עין\u0004 הרע. ומעירים: \u0003רב לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003רב סליק לבי קברי\u0004 \u0005[הלך לבית הקברות],\u0006 \u0003עבד מאי דעבד\u0004 \u0005[עשה מה שעשה]\u0006 כדי לברר על פי השבעה מה אירע לאנשים שמתו, \u0003אמר: תשעין ותשעה\u0004 מאלה מתו \u0003בעין רעה,\u0004 ורק \u0003אחד בדרך ארץ,\u0004 כלומר, כדרך הטבע לגמרי.","\u0003ושמואל אמר:\u0004 \"כל חולי\" \u0003זה הרוח\u0004 ומעירים: \u0003שמואל לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר שמואל: הכל ברוח.\u0004 כלומר, כל הפגעים הבאים על בני אדם הם מחמת רוח שנכנסת בפצעים ובחלל הגוף. ושואלים: \u0003ול\u0004שיטת \u0003שמואל, הא איכא\u0004 \u0005[הרי יש]\u0006 \u0003הרוגי מלכות\u0004 ושאר הנהרגים בפציעה וכיוצא בהם ולא ברוח! ומשיבים: \u0003הנך נמי, אי לאו זיקא,\u0004 \u0003עבדי להו סמא וחיי\u0004 \u0005[אלה גם כן, לולא הרוח היו עושים להם סם והיו מתרפאים],\u0006 ומחמת הרוח אינם מתרפאים.","\u0003ר' חנינא אמר:\u0004 \"כל חולי\" \u0003זו צינה,\u0004 ש\u0003אמר ר' חנינא: הכל,\u0004 כל המאורעות, באים על אדם \u0003בידי שמים, חוץ מצנים פחים,\u0004 כלומר, מדברים הבאים על ידי צינה שיכול אדם להזהר ולהתרחק מהם, ואינם בידי שמים. \u0003שנאמר: \"צנים פחים בדרך עקש שומר נפשו ירחק מהם\"\u0004 (משלי כב, ה).","\u0003ר' יוסי בר' חנינא אמר:\u0004 \"כל חולי\" \u0003זו צואה.\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003צואת החוטם,\u0004 כלומר, אותם לכלוכים המצויים באף, \u0003וצואת האוזן\u0004 — \u0003רובן\u0004 אם יוצאים הרבה הרי זה \u0003קשה\u0004 ומזיק, \u0003ומיעוטן יפה.\u0004","\u0003ר' אלעזר אמר:\u0004 \"כל חולי\" \u0003זו מרה.\u0004 ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה כך\u0006 בברייתא \u0005גם כן]:\u0006 \u0003\"מחלה\" זו מרה, ולמה נקרא שמה\u0004 של מרה \u0003\"מחלה\"\u0004 — \u0003שהיא מחלה כל גופו של אדם. דבר אחר:\u0004 קוראים למרה \u0003\"מחלה\"\u0004 — משום \u0003ששמונים ושלשה חלאים\u0004 כמנין \"מחלה\" \u0003תלוין במרה.\u0004 ומעירים: \u0003וכולן,\u0004 אכילת \u0003פת שחרית במלח ו\u0004שתיית \u0003קיתון\u0004 (כוס גדולה) \u0003של מים\u0004 — \u0003מבטלתן,\u0004 שאוכל פשוט בסעודת שחרית מרפא את הגוף.","ואגב כך מביאים את מה ששנינו בברייתא. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שלשה עשר דברים\u0004 של שבח \u0003נאמרו ב\u0004ארוחת \u0003פת שחרית: מצלת\u0004 את האוכלה \u0003מן החמה, ומן הצנה, ומן הזיקין\u0004 (הרוחות), \u0003ומן המזיקין, ומחכימת פתי,\u0004 ואותו אדם \u0003זוכה בדין,\u0004 וזוכה \u0003ללמוד תורה וללמד, ודבריו נשמעין, ותלמודו מתקיים בידו,\u0004","\u0003ואין בשרו מעלה הבל\u0004 (זיעה יתירה), \u0003ו\u0004הוא \u0003נזקק לאשתו\u0004 בשעה הראויה, \u0003ואינו מתאוה לאשה אחרת, ו\u0004אף \u0003הורגת כינה שבבני מעים.\u0004 כל כך מועילה ארוחה זו. \u0003ויש אומרים: אף מוציא את הקנאה ומכניס את האהבה.\u0004 שכיון שבריאותו שלמה, אינו נוטה להתרגז ולריב עם הבריות.","דרך אגב מספרים ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה לרבא בר מרי: מנא הא מילתא דאמרי אינשי\u0004 \u0005[מנין אותם דברים שאומרים אנשים\u0006 כפתגם מקובל\u0005]:\u0006 \u0003שיתין רהיטי רהוט\u0004 \u0005[שישים רצים רצו]\u0006 \u0003ולא מטו לגברא דמצפרא כרך\u0004 \u0005[הגיעו,\u0006 השיגו, \u0005לאדם שאכל בבוקר].\u0006 \u0003ו\u0004כן \u0003אמרו רבנן\u0004 \u0005[חכמים]:\u0006 \u0003השכם ואכול, בקיץ מפני החמה ובחורף מפני הצינה\u0004 שיתחזק הגוף לשאת באלה.","ש\u0003אמר ליה\u0004 \u0005[לו]:\u0006 מקרא הוא, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"לא ירעבו ולא יצמאו ולא יכם שרב ושמש\"\u0004 (ישעיה מט, י), מדוע \u0003לא יכם שרב ושמש\u0004 — \u0003כיון\u0004 ש\u0003לא ירעבו ולא יצמאו\u0004 אלא השכימו ואכלו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003את אמרת\u0004 \u0005[אתה אומר]\u0006 \u0003לי\u0004 משום \u0003מהתם\u0004 \u0005[משם]\u0006 \u0003ואנא אמינא\u0004 \u0005[ואני אומר]\u0006 \u0003לך מהכא\u0004 \u0005[מכאן],\u0006 מפסוק אחר, שנאמר \u0003\"ועבדתם את ה' אלהיכם וברך את לחמך ואת מימיך\"\u0004 (שמות כג, כה), וכך הוא מפרש: \u0003\"ועבדתם את ה' אלהיכם\"\u0004 — \u0003זו קריאת שמע ותפלה,\u0004 עבודת ה' שבכל יום. \u0003\"וברך את לחמך ואת מימך\"\u0004 — \u0003זו פת במלח וקיתון של מים\u0004 שאוכל בשחרית לאחר התפילה, \u0003מכאן ואילך\u0004 מתקיים המשך הפסוק \u0003\"והסרתי מחלה מקרבך\"\u0004 (שם).","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יהודה לרב אדא משוחאה\u0004 \u0005[המודד],\u0006 שהיה במקצועו מודד שדות: \u0003לא תזלזל במשחתא\u0004 \u0005[אל תזלזל במדידה]\u0006 ואפילו בשטחים קטנים, ש\u0003כל פורתא ופורתא חזי לכורכמא רישקא\u0004 \u0005[מעט ומעט ראויה\u0006 לגדל בה \u0005כרכום תרבותי]\u0006 שהוא יקר מאוד, ואם כן אין אתה רשאי לזלזל אף בקרקע קטנה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יהודה לרב אדא משוחאה\u0004 \u0005[המודד]:\u0006 \u0003ארבע אמות דאניגרא\u0004 \u0005[ש\u0006סמוכות \u0005לתעלה]\u0006 העשוייה לצורך השקיית השדות ויוצאת מן הנהר — \u0003זלזל בהו\u0004 \u0005[בהן]\u0006 ואל תמדדן בדיוק, כשאתה מודד שטחם של שדות. ארבע אמות \u0003דאנהרא\u0004 \u0005[ש\u0006סמוכות \u0005לנהר]\u0006 \u0003לא תמשחנהו\u0004 \u0005[אל תמדוד אותן]\u0006 \u0003כלל,\u0004 אלא שער במדה גדולה.","ומעירים: כי בענין זה \u0003רב יהודה לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר רב יהודה: ארבע אמות דאניגרא\u0004 \u0005[ש\u0006סמוכות \u0005לתעלה]\u0006 — הריהן שייכות \u0003לבני אניגרא\u0004 \u0005[ל\u0006יושבים על יד \u0005התעלה].\u0006 ארבע \u0003אמות\u0004 \u0003דאנהרא\u0004 \u0005[ש\u0006סמוכות \u0005לנהר]\u0006 — הריהן \u0003דכולי עלמא\u0004 \u0005[\u0006שייכות \u0005לכול].\u0006","היה \u0003מכריז ר' אמי: מלא\u0004 שיעור \u0003כתפי נגדי בתרי עברי נהרא\u0004 \u0005[הנגדים\u0006 מושכי הספינות \u0005בשני עברי הנהר]\u0006 — \u0003קוצו\u0004 \u0005[קצצו]\u0006 את העצים שעל שפת הנהר כדי שלא יפריעו למושכי הספינות. מסופר: \u0003רב נתן בר הושעיא קץ שיתסר אמתא\u0004 \u0005[\u0006ציוה \u0005לקצץ שש עשרה אמות]\u0006 לכל צד של הנהר. \u0003אתו עליה\u0004 \u0005[באו עליו]\u0006 \u0003בני\u0004 המקום \u0003משרוניא דפנוהו\u0004 \u0005[\u0006ו\u0005הכו אותו]\u0006 על שקצץ כה הרבה. ומסבירים: \u0003הוא סבר\u0004 שאם עושים דרך צריכה היא להיות \u0003כרשות הרבים\u0004 שרוחבה שש עשרה אמה, ולאמיתו של דבר \u0003ולא היא\u0004 (ולא כן), אלא \u0003התם\u0004 \u0005[שם]\u0006 ברשות הרבים אכן \u0003בעינן כולי האי\u0004 \u0005[צריכים כל כך הרבה]\u0006 ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003משום אמתוחי אשליהן\u0004 \u0005[מתיחת החבלים]\u0006 \u0003הוא,\u0004 שיש למתוח כדי למשוך את האניות, ו\u0003כמלא כתפי נגדי סגי\u0004 \u0005[הנגדים,\u0006 המושכים, \u0005מספיק].\u0006","מסופר: \u0003רבה בר רב הונא הוה ליה ההוא אבא אגודא דנהרא\u0004 \u0005[היה לו יער על שפת הנהר],\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003ניקוץ מר\u0004 \u0005[שיקצוץ אדוני]\u0006 את העצים שעל שפת הנהר, שהרי שנינו שצריך לקצוץ כדי לעזור לנגדי הספינות! \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003קוצו עילאי ותתאי\u0004 \u0005[יקצצו עליונים ותחתונים],\u0006 כלומר, אלה הנמצאים במעלה הנהר ובמורד הנהר מסביב לי ושייכים לאחרים, \u0003והדר ניקוץ אנא\u0004 \u0005[ואחר כך אקצוץ אני],\u0006 שהרי אין בכך תועלת אם אקצוץ אני קודם. ושואלים: \u0003היכי עביד הכי\u0004 \u0005[כיצד עשה כן]\u0006 להמתין עד שיעשו אחרים? \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"התקוששו וקושו\"\u0004 (צפניה ב, א), ועל כך \u0003אמר\u0004 (דרש) \u0003ריש לקיש: קשוט עצמך ואחר כך קשוט אחרים,\u0004 והרי שצריך אדם קודם לעשות את הטוב והישר ואחר כך לייעץ לאחרים!","ומשיבים: \u0003התם אבא דבי פרזק רופילא הוה\u0004 \u0005[שם היער של בית פרזק שר הצבא היה]\u0006 וברור היה שהם לא ישמעו בקול החכם הישראלי, ולכן אמר: \u0003אי קייצו\u0004 \u0005[אם יקצצו הם]\u0006 אנשי השר הפרסי — \u0003קייצנא\u0004 \u0005[אקצוץ],\u0006 \u0003ואי לא קייצו\u0004 \u0005[ואם אינם קוצצים]\u0006 — \u0003אמאי איקוץ\u0004 \u0005[מדוע אקצוץ],\u0006 שהרי אין בדבר כל תועלת. \u0003דאי ממתחי להו אשלייהו\u0004 \u0005[שאם\u0006 יכולים הנגדים \u0005למתוח את החבלים]\u0006 — הרי \u0003מסתגי להו\u0004 \u0005[יוכלו ללכת]\u0006 בצד זה של הנהר,"],["\u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003לא מיסתגי להו\u0004 \u0005[יכלו ללכת],\u0006 אלא יצטרכו לעבור לעבר הנהר השני, ואם כן אין טעם בקציצת חלק משפת הנהר בלבד.","מסופר: \u0003רבה בר רב נחמן הוה קא אזיל בארבא\u0004 \u0005[היה מהלך באניה]\u0006 \u0003חזא ההוא אבא דקאי אגודא דנהרא\u0004 \u0005[ראה אותו יער המצוי על שפת הנהר\u0006 ממש\u0005]\u0006 שלא קצצו ופינו בו דרך לנגדים. \u0003אמר להו\u0004 \u0005[להם]\u0006 לאנשים שעמו: \u0003דמאן\u0004 \u0005[של מי הוא\u0006 יער זה\u0005]?\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 של \u0003רבה בר רב הונא\u0004 הוא. \u0003אמר\u0004 רבה בר רב נחמן, הרי זה כעין שנאמר: \u0003\"ויד השרים והסגנים היתה במעל הזה ראשונה\"\u0004 (עזרא ט, ב), שחכם מפורסם אינו נוהג כהלכה. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003קוצו קוצו\u0004 \u0005[\u0006\u0005קצצו קצצו]\u0006 ופנו את הדרך!","\u0003אתא\u0004 \u0005[בא]\u0006 \u0003רבה בר רב הונא אשכחיה דקייץ\u0004 \u0005[\u0006ו\u0005מצא\u0006 את יערו \u0005ש\u0006הוא \u0005קצוץ]\u0006 והרי כאמור צדק הוא במה שלא קצץ, ולכן כעס ו\u0003אמר\u0004 בלשון קללה: \u0003מאן קצייה\u0004 \u0005[מי שקצצו]\u0006 את היער הזה — \u0003תקוץ ענפיה\u0004 \u0005[יקצצו ענפיו].\u0006 ואומרים: כיון שיצאה קללה זו מפיו, אף על פי שלא ידע מי עשה זאת, מכל מקום קללת חכם נתקיימה, \u0003כולהו שני\u0004 \u0005[כל שנותיו]\u0006 של \u0003רבה בר רב הונא,\u0004 כל עוד היה חי, \u0003לא אקיים ליה זרעא\u0004 \u0005[התקיים לו זרע]\u0006 \u0003לרבה בר רב נחמן,\u0004 שהיו ילדיו (\"ענפיו\") מתים בחייו.","\u0003אמר רב יהודה: הכל\u0004 משתתפים בתשלום \u0003לאיגלי גפא\u0004 \u0005[\u0006עבור \u0005בניית חומת\u0006 העיר\u0005],\u0006 \u0003ואפילו מיתמי\u0004 \u0005[מיתומים]\u0006 לוקחים לצורך זה, \u0003אבל רבנן\u0004 \u0005[\u0006מן \u0005החכמים]\u0006 \u0003לא.\u0004 \u0003מאי טעמא\u0004 \u0005[מהו טעם]\u0006 הדבר — \u0003רבנן לא צריכי נטירותא\u0004 \u0005[חכמים אינם צריכים שמירה],\u0006 שזכות תורתם משמרתם. \u0003לכריא דפתיא\u0004 \u0005[לכריית בורות,\u0006 או בארות\u0005]\u0006 לצורך שתייה \u0003לוקחים\u0004 \u0003ואפילו מרבנן\u0004 \u0005[מחכמים].\u0006","\u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 שאף החכמים משתתפים בכריית הנהר, \u0003אלא דלא נפקא באוכלוזא\u0004 \u0005[שאין יוצאים באוכלוסיה]\u0006 ובני העיר אינם עושים את העבודה בעצמם, אלא רק משלמים עבור פועלים. \u0003אבל לאוכלוזא לא\u0004 \u0005[\u0006אם \u0005יוצאים באוכלוסיה]\u0006 — \u0003לא,\u0004 והטעם: משום \u0003דרבנן לאו בני מיפק באוכלוזא נינהו\u0004 \u0005[שחכמים אינם בני יציאה בתוך הקהל לעשות עבודה\u0006 בפומבי\u0005].\u0006","\u0003אמר רב יהודה: לכריא דנהרא\u0004 \u0005[לכריית הנהר],\u0006 שהיו חופרים מפעם לפעם ומעמיקים את אפיקו שלא יסתם — \u0003תתאי מסייעי עילאי\u0004 \u0005[התחתונים\u0006 שליד מורד הנהר \u0005מסייעים לעליונים]\u0006 לכרות ולתקן את הנהר, אבל \u0003עילאי לא מסייעי תתאי\u0004 \u0005[העליונים אינם מסייעים לתחתונים],\u0006 שהרי הנמצאים במורד הנהר שותפים בהנאה שיהיה הנהר כרוי עד המקום שלהם, ולא להיפך. \u0003וחילופא במיא דמיטרא\u0004 \u0005[וחילוף,\u0006 היפך הדברים, כשחופרים תעלה כדי להפטר \u0005ממי הגשמים]\u0006 ששם העליונים הם המעוניינים בכך, ועל כן התחתונים אינם מסייעים להם, ולהיפך, הם צריכים לסייע לתחתונים.","ומעירים, \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 היו \u0003חמש גנות המסתפקות\u0004 (המקבלות צרכיהן במים) \u0003ממעין אחד, ונתקלקל המעיין\u0004 — \u0003כולם מתקנות עם העליונה. נמצאת התחתונה מתקנת עם כולן ומתקנת לעצמה. וכן\u0004 אם היו \u0003חמש חצרות שהיו מקלחות מים\u0004 ממי גשמים \u0003לביב אחד ונתקלקל הביב\u0004 — \u0003כולן מתקנות עם התחתונה, נמצאת העליונה מתקנת עם כולן ומתקנת לעצמה.\u0004 והוא כדברי רב יהודה.","\u0003אמר שמואל: האי מאן דאחזיק ברקתא דנהרא\u0004 \u0005[מי שמחזיק בשפת הנהר],\u0006 שהיו משאירים כרגיל את שפת הנהר פנויה קצת, לאפשר לפרוק ולטעון שם, וכיון שהשטח היה פנוי יכול היה אדם לבוא ולהשתמש לפי שעה בשטח הפנוי הזה לחרוש ולזרוע בו — \u0003חציפא הוי\u0004 \u0005[חצוף הוא],\u0006 אבל \u0003סלוקי\u0004 \u0005[לסלק]\u0006 — \u0003לא מסלקינן ליה\u0004 \u0005[אין מסלקים אותו],\u0006 שהרי המקום הוא כעין מקום הפקר. \u0003והאידנא דקא כתבי פרסאי\u0004 \u0005[ועכשיו שכותבים הפרסים]\u0006 לאדם שקונה אחוזה ליד הנהר: \u0003קני\u0004 \u0005[קנה]\u0006 \u0003לך\u0004 את השדה \u0003עד\u0004 תוך הנהר שיעור שיהא \u0003מלי צוארי סוסיא מיא\u0004 \u0005[\u0006\u0005מלוא צווארו של הסוס\u0006 בתוך \u0005המים]\u0006 — \u0003סלוקי נמי מסלקינן ליה\u0004 \u0005[מסלקים אותו גם כן],\u0006 שהרי השטח שייך לבעל השדה.","\u0003אמר רב יהודה אמר רב: האי מאן דאחזיק ביני אחי וביני שותפי\u0004 \u0005[מי שהחזיק\u0006 בקרקע \u0005בין\u0006 שני \u0005אחים\u0006 או \u0005בין\u0006 שני \u0005שותפים]\u0006 והוא גורם להם על ידי כך קשיים, \u0003חציפא הוי\u0004 \u0005[חצוף הוא],\u0006 ואולם \u0003סלוקי\u0004 \u0005[לסלק]\u0006 — \u0003לא מסלקינן ליה\u0004 \u0005[אין מסלקים אותו],\u0006 שהרי אין להם תביעה ממשית עליו. \u0003ורב נחמן אמר: נמי מסלקינן\u0004 \u0005[גם כן מסלקים אנו\u0006 אותו\u0005],\u0006 כי אין לו לאדם לעשות דבר שגורם נזק לחבירו. \u0003ואי\u0004 \u0005[ואם]\u0006 קובלים עליו \u0003משום דינא דבר מצרא\u0004 \u0005[דין בר מיצר],\u0006 שהיו להם שדות סמוך לשדה זה מצד אחר — \u0003לא מסלקינן ליה\u0004 \u0005[אין מסלקים אותו].\u0006","\u0003נהרדעי אמרי\u0004 \u0005[חכמי נהרדעא אומרים]:\u0006 \u0003אפילו\u0004 אם הוא בא בתביעה \u0003משום,\u0004 מכוח, \u0003דינא דבר מצרא\u0004 \u0005[דין של בן מיצר]\u0006 — \u0003מסלקינן ליה\u0004 \u0005[מסלקים אנו אותו],\u0006 \u0003משום שנאמר: \"ועשית הישר והטוב בעיני ה'\"\u0004 (דברים ו, יח), ואין לו לאדם לעשות דבר שאינו ישר וטוב, גם אם יש לו זכות לכך מן הדין.","על פי הלכות אלה שואלים: אם \u0003אתא אימליך ביה\u0004 \u0005[בא\u0006 הזר \u0005להמלך בו],\u0006 באחד מבעלי השדות ו\u0003אמר ליה\u0004 \u0005[לו]:\u0006 האם \u0003איזיל איזבון\u0004 \u0005[אלך ואקנהו]?\u0006 \u0003ואמר ליה\u0004 \u0005[לו]:\u0006 \u0003זיל זבון\u0004 \u0005[לך קנה]\u0006 ואין אני מעכב בידך, האם \u0003צריך למיקנא מיניה\u0004 \u0005[לקנות ממנו],\u0006 לעשות עמו קנין על הסכמה זו, \u0003או לא,\u0004 ודי בהבטחה בלבד? \u0003רבינא אמר: לא צריך למיקנא מיניה\u0004 \u0005[אינו צריך לקנות ממנו],\u0006 \u0003נהרדעי אמרי\u0004 \u0005[\u0006חכמי \u0005נהרדעי אמרו]:\u0006 \u0003צריך למיקנא מיניה\u0004 \u0005[לקנות ממנו].\u0006 ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה\u0006 היא\u0005]\u0006 ש\u0003צריך למיקנא מיניה\u0004 \u0005[לקנות ממנו].\u0006","ומעירים: ו\u0003השתא דאמרת\u0004 \u0005[ועכשיו שאתה אומר]\u0006 ש\u0003צריך למיקנא מיניה\u0004 \u0005[לקנות ממנו]\u0006 את הזכות, \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא קנו מיניה\u0004 \u0005[קנה\u0006 את הזכות \u0005ממנו],\u0006 אם \u0003אייקור וזול\u0004 \u0005[התייקר\u0006 או \u0005הוזל\u0006 השדה\u0005],\u0006 הרי הוא \u0003ברשותיה\u0004 \u0005[ברשותו\u0006 של בן המיצר\u0005],\u0006 שכן קנייתו של הקונה אינה נחשבת, שהרי מסלקים אותו מן הקנין.","אם הקונה הזה \u0003זבן במאה ושוי מאתן\u0004 \u0005[קנה במאה ו\u0006היה השדה \u0005שווה מאתים],\u0006 \u0003חזינא\u0004 \u0005[רואים אנו];\u0006 \u0003אי לכולי עלמא קא מוזילא ומזבין\u0004 \u0005[אם לכל העולם\u0006 היה מוזיל ומוכר] — \u0003יהיב ליה\u0004 \u0005[נותן לו]\u0006 \u0003מאה ושקיל ליה\u0004 \u0005[ולוקח אותו],\u0006 שהרי יכול היה בן המיצר עצמו לקנותו במאה. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא,\u0004 שעשה טובה רק לקונה זה — \u0003יהיב ליה מאתן ושקיל ליה\u0004 \u0005[נותן לו מאתים\u0006 דמי השדה \u0005ויקח אותו].\u0006","ולהיפך: אם \u0003זבן במאתן ושויא\u0004 \u0005[קנה במאתים\u0006 \u0003ושווה]\u0004 הקרקע \u0003מאה,\u0004 \u0003סבור מינה, מצי אמר ליה\u0004 \u0005[סבורים\u0006 היו \u0005שיכול לומר לו]:\u0006 \u0003לתקוני שדרתיך\u0004 \u0005[לתקן שלחתיך]\u0006 \u0003ולא לעוותי\u0004 \u0005[לעוות,\u0006 לקלקל\u0005],\u0006 וכיון שקנין זה אינו נשאר ברשותך, הרי אתה כשלוחי, ואם טעית אין אני מוכן לשלם יותר ממאה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר קשישא\u0004 \u0005[המבוגר]\u0006 \u0003בריה\u0004 \u0005[בנו]\u0006 של \u0003רב חסדא\u0004 \u0003לרב אשי: הכי אמרי נהרדעי\u0004 \u0005[כך אומרים\u0006 חכמי \u0005נהרדעא]\u0006 \u0003משום\u0004 (בשם) \u0003רב נחמן: אין אונאה לקרקעות,\u0004 לפי שאין להם מחיר קצוב אמיתי, ולכן אינו יכול לומר ששילם יותר מהמחיר.","אם \u0003זבין ליה גריוא דארעא במיצעא נכסיה\u0004 \u0005[מוכר לו\u0006 אדם לחבירו \u0005בית סאה של קרקע באמצע נכסיו]\u0006 ושדות המוכר מקיפים אותו מכל צד, \u0003חזינן\u0004 \u0005[רואים אנו]\u0006 את הקרקע הזאת, \u0003אי\u0004 \u0005[אם]\u0006 \u0003עידית היא, אי\u0004 \u0005[אם]\u0006 \u0003זיבורית היא\u0004 כיון שהיא מיוחדת במינה משום טיבה — \u0003זביניה זביני\u0004 \u0005[מכירתו מכירה]\u0006 ואין בני המיצר של המוכר יכולים לעכב בידו, שהרי אין שדותיהם גובלים ממש בחלקה זו."],["\u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא,\u0004 שאין שדה זה מיוחד במינו, ודאי \u0003איערומי קא מערים\u0004 \u0005[מערים\u0006 המוכר\u0005]\u0006 על בני המיצר, שרוצה ליצור מצב שיהיה עוד אדם אחד בין מיצר לכל שדותיו, ולכן יכולים האחרים לעכב בעדו.","\u0003מתנה לית\u0004 \u0005[אין]\u0006 \u0003בה משום דינא דבר מצרא\u0004 \u0005[דין בן המיצר]\u0006 שיכול לתת למי שרוצה, ואין בן המיצר יכול לעכב. \u0003אמר אמימר: אי\u0004 \u0005[\u0006\u0005אם]\u0006 \u0003כתב ליה\u0004 \u0005[לו]\u0006 למקבל המתנה שטר \u0003אחריות\u0004 שאם יטרפו ממנו את הקרקע בשל חובות קודמים של הנותן, יתן לו הנותן קרקע אחרת — \u0003אית\u0004 \u0005[יש]\u0006 \u0003בה,\u0004 במכירה זו \u0003משום דינא דבר מצרא\u0004 \u0005[דין בן מיצר].\u0006","\u0003מכר כל נכסיו ל\u0004אדם \u0003אחד\u0004 — \u0003לית\u0004 \u0005[אין]\u0006 \u0003בה,\u0004 במכירה זו \u0003משום דינא דבר מצרא\u0004 \u0005[דין בן מיצר],\u0006 שכיון שההוא קונה כל נכסיו אינו יכול ליצור יוצא מן הכלל, ולא למכור לו שדה אחד. מכרה \u0003לבעלים הראשונים\u0004 שמהם קנאה — \u0003לית\u0004 \u0005[אין]\u0006 \u0003בה,\u0004 במכירה זו \u0003משום דינא דבר מצרא\u0004 \u0005[דין בן מיצר].\u0006 \u0003זבן\u0004 \u0005[קנה]\u0006 \u0003מגוי וזבין\u0004 \u0005[\u0006או \u0005מכר]\u0006 \u0003לגוי\u0004 — \u0003לית\u0004 \u0005[אין]\u0006 \u0003בה,\u0004 במכירה זו \u0003משום דינא דבר מצרא\u0004 \u0005[דין בן מיצר].\u0006","ומסבירים: אם \u0003זבן\u0004 \u0005[קנה]\u0006 \u0003מגוי\u0004 — הרי \u0003דאמר ליה\u0004 \u0005[\u0006\u0005שאומר לו]\u0006 לשכן: טוב לך שאני קניתי, \u0003ארי אברחי\u0004 \u0005[הרי\u0006 בכך \u0005אריה הברחתי]\u0006 \u0003לך ממצרא\u0004 \u0005[\u0006מן המיצר], שוודאי מוטב לך בשכן ישראל, ולא בגוי. \u0003זבין\u0004 \u0005[מכר]\u0006 \u0003לגוי\u0004 הלוא \u0003גוי ודאי לאו בר\u0004 \u0005[איננו בן,\u0006 שייך\u0005]\u0006 בעשיית \u0003\"ועשית הישר והטוב\" הוא\u0004 ולכן אין חובה על הגוי להימנע לקנות מבר מיצרא. ואולם \u0003שמותי\u0004 \u0005[לנדות]\u0006 \u0003ודאי משמתינן ליה\u0004 \u0005[מנדים אנו אותו],\u0006 את המוכר לגוי \u0003עד דמקבל עליה\u0004 \u0005[שיקבל על עצמו]\u0006 \u0003כל אונסי דאתי ליה מחמתיה\u0004 \u0005[מיני אונס שיבואו לו\u0006 לשכן \u0005מחמתו]\u0006 של הגוי הזה.","אם מוכר את השדה שנתן אותו קודם כ\u0003משכנתא\u0004 \u0005[משכון]\u0006 — \u0003לית\u0004 \u0005[אין]\u0006 \u0003בה,\u0004 במכירה זו \u0003משום דינא דבר מצרא\u0004 \u0005[דין בן מיצר].\u0006 ש\u0003אמר רב אשי: אמרו לי סבי\u0004 \u0005[זקני\u0006 העיר\u0005]\u0006 \u0003מתא מחסיא:\u0004 \u0003מאי\u0004 \u0005[מה\u0006 הוא\u0005]\u0006 לשון \u0003\"משכנתא\"\u0004 — \u0003דשכונה גביה\u0004 \u0005[ש\u0006היא \u0005שוכנת אצלו].\u0006 ו\u0003מאי נפקא מינה\u0004 \u0005[מה יוצא מזה]\u0006 מפירוש זה — ללמדנו \u0003לדינא דבר מצרא\u0004 \u0005[לדין בן מיצר]\u0006 שהמחזיק במשכון נחשב כסמוך מכולם, שהרי יש לו קנין מסויים בו.","אם מכר את השדה במטרה \u0003למכור ברחוק\u0004 ממנו כדי \u0003לגאול\u0004 (להחזיר לעצמו) שדה \u0003בקרוב\u0004 אליו, או מכר שדה \u0003ברע\u0004 כדי \u0003לגאול ביפה\u0004 — \u0003לית\u0004 \u0005[אין]\u0006 \u0003בה,\u0004 במכירה זו \u0003משום דינא דבר מצרא\u0004 \u0005[דין בן מיצר],\u0006 אלא מוכר כפי המזדמן לו.","וכן אם מוכר לדברים נחוצים, כגון \u0003לכרגא\u0004 (מס הקרקעות), או \u0003למזוני\u0004 \u0005[למזונות]\u0006 שמוכרים שדה כדי לשלם מזון אשתו ובנותיו, או \u0003לקבורה\u0004 של אחד ממשפחתו \u0003—\u0004 \u0003לית\u0004 \u0005[אין]\u0006 \u0003בה,\u0004 במכירה זו \u0003משום דינא דבר מצרא\u0004 \u0005[דין בן מיצר].\u0006 \u0003דאמרי\u0004 \u0005[שאמרו]\u0006 חכמי \u0003נהרדעא: לכרגא, למזוני ולקבורה מזבנינן\u0004 \u0005[מוכרים אנו]\u0006 שדה \u0003בלא אכרזתא\u0004 \u0005[הכרזה],\u0006 משום שהדבר נחוץ ודחוף, ואין משהים אותו, וכל שכן שאין מתחשבים בבן המיצר. וכן אדם המוכר שדה \u0003לאשה\u0004 שאין דרכה לחזר \u0003אחרי המוכרים, או\u0004 \u0003ליתמי\u0004 \u0005[ליתומים],\u0006 או \u0003לשותפי\u0004 \u0005[לשותפים]\u0006 שלו — \u0003לית\u0004 \u0005[אין]\u0006 \u0003בה,\u0004 במכירה זו \u0003משום דינא דבר מצרא\u0004 \u0005[דין בן מיצר].\u0006","היו אנשים שונים שלהם זכויות שוות, כגון ששניהם בני מיצר, ומהם \u0003שכיני העיר,\u0004 אנשים ששכנים לו בעיר, \u0003ו\u0004מהם \u0003שכיני\u0004 ה\u0003שדה\u0004 שלו — \u0003שכיני העיר קודמים\u0004 לשכני השדה,","סתם \u0003שכן ותלמיד חכם\u0004 — \u0003תלמיד חכם קודם. קרוב\u0004 משפחה \u0003ותלמיד חכם\u0004 — \u0003תלמיד חכם קודם. איבעיא להו\u0004 \u0005נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003שכן וקרוב מאי\u0004 \u0005[מה],\u0006 למי מהם ראוי להקדים? ומציעים: \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 תשובה לדבר ממה שנאמר: \u0003\"טוב שכן קרוב מאח רחוק\"\u0004 (משלי כז, י).","שני אנשים המציעים לו לקנות שדה, ומביאים כספים, \u0003הני זוזי טבי והני תקולי\u0004 \u0005[אלה זוזים טובים ואלה זוזים שקולים],\u0006 שהם יפים מהם, — \u0003לית ביה\u0004 \u0005[אין בו,\u0006 בכך\u0005]\u0006 \u0003משום דינא דבר מצרא\u0004 \u0005[דין בר מיצר],\u0006 שהוא יכול להעדיף את הנותן לו כסף יפה יותר. \u0003הני ציירי והני שרי\u0004 \u0005[\u0006זוזים \u0005אלה צרורים ואלה מותרים]\u0006 — \u0003לית ביה\u0004 \u0005[אין בו,\u0006 בכך\u0005]\u0006 \u0003משום דינא דבר מצרא\u0004 \u0005[דין בר מיצר]\u0006 ויכול המוכר למכור לנותן לו כסף מזומן ומוכן לספירה.","\u0003אמר: איזיל\u0004 \u0005[אלך]\u0006 \u0003ואטרח ואייתי זוזי\u0004 \u0005[ואביא זוזים]\u0006 ובהם אקנה את הקרקע — \u0003לא נטרינן ליה\u0004 \u0005[אין ממתינים לו]\u0006 אף שהוא בר מיצר, אם מצא המוכר אדם אחר הרוצה לקנותה ומשלם לו מיד. \u0003אמר: איזיל אייתי זוזי\u0004 \u0005[אלך\u0006 ו\u0005אביא כסף],\u0006 \u0003חזינן\u0004 \u0005[רואים אנו]:\u0006 \u0003אי גברא דאמיד\u0004 \u0005[אם אדם שמוערך]\u0006 \u0003הוא\u0004 כאחד \u0003דאזיל ומייתי זוזי\u0004 \u0005[ש\u0006יכול \u0005ללכת ולהביא כסף]\u0006 — \u0003נטרינן ליה\u0004 \u0005[ממתינים לו],\u0006 \u0003ואי\u0004 \u0005ואם\u0006 הוא \u0003לא\u0004 מוערך ככזה — \u0003לא נטרינן ליה\u0004 \u0005[ממתינים לו].\u0006","אם היו \u0003ארעא דחד ובתי דחד\u0004 \u0005[הקרקע של אחד והבתים\u0006 שעליה \u0005של אחד,\u0006 אחר\u0005]\u0006 ורצה אחד מהם למכור — \u0003מרי ארעא\u0004 \u0005[בעל הקרקע]\u0006 \u0003מעכב\u0004 אם רצונו בכך \u0003אמרי בתי\u0004 \u0005[על בעל הבתים]\u0006 למכור לאחר, שלו יש זכות קדימה, אבל \u0003מרי בתי\u0004 \u0005[בעל הבתים]\u0006 \u0003לא מעכב אמרי דארעא\u0004 \u0005[על בעל הקרקע]\u0006 כי עשוי אדם לשנות מקום דירתו בקלות יותר, ואינו קבוע כל כך. היתה \u0003ארעא דחד ודיקלי דחד\u0004 \u0005[הקרקע של אחד והדקלים\u0006 שבה \u0005של אחד]\u0006 — \u0003מרי דארעא מצי\u0004 \u0005[בעל הקרקע]\u0006 \u0003מעכב\u0004 אם רצונו בכך \u0003אמרי דקלי\u0004 \u0005[על בעל הדקלים]\u0006 מלמכור, אך \u0003מרי דיקלי לא מצי מעכב אמרי דארעא\u0004 \u0005[בעל הדקלים אינו יכול לעכב על בעל הקרקע].\u0006","היו קונים לקרקע, ומטרותיהם שונות, \u0003ארעא לבתי וארעא לזרעא\u0004 \u0005[קרקע לבנין וקרקע לזריעה]\u0006 — \u0003ישוב\u0004 של בנין בתים \u0003עדיף, ולית\u0004 \u0005[ואין]\u0006 \u0003בה,\u0004 במכירה זו \u0003משום דינא דבר מצרא\u0004 \u0005[דין בן מיצר],\u0006 אלא ימכור לרוצה לקנות בית, ואפילו אינו מיצרן.","אם \u0003אפסיק משוניתא\u0004 \u0005[הפסיקה שן סלע]\u0006 \u0003או ריכבא דדיקלא\u0004 \u0005[שורות דקלים]\u0006 בין שדה אחד לשדה של הגובל בו, \u0003חזינא\u0004 \u0005[רואים אנו];\u0006 \u0003אם יכול להכניס בה\u0004 בעל השדה הגובל \u0003אפילו תלם אחד\u0004 שיגע ממש בשדה האחר — \u0003אית\u0004 \u0005[יש]\u0006 \u0003בה,\u0004 במכירה זו \u0003משום דינא דבר מצרא\u0004 \u0005[דין בן מיצר],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003לית\u0004 \u0005[אין]\u0006 \u0003בה משום דינא דבר מצרא\u0004 \u0005[דין בן מיצר].\u0006","\u0003הני\u0004 \u0005[אותם]\u0006 \u0003ארבעה בני מצרני\u0004 \u0005[מיצר]\u0006 המקיפים שדה העומד למכירה מארבעה צדדים, \u0003דקדים חד מינייהו וזבין\u0004 \u0005[שקדם אחד מהם וקנה]\u0006 — \u0003זביניה זביני\u0004 \u0005[קנייתו קניה]\u0006 ואין האחרים יכולים לעכב. \u0003ואי כולהו אתו בהדי הדדי\u0004 \u0005[ואם כולם באים יחד]\u0006 לקנות — \u0003פלגו לה בקרנזיל\u0004 — \u0005[חולקים אותה\u0006 את הקרקע, \u0005באלכסון],\u0006 ויטול כל אחד מהם חלק הסמוך לשדהו."],["\u0003המקבל שדה מחבירו לשנים מועטות,\u0004 פחות משבע שנים — \u0003לא יזרענה פשתן,\u0004 מפני שהפשתן מנצל מאד את הקרקע. \u0003ואין לו בקורות שקמה,\u0004 שאם היה עץ שקמה גדל בשדה, אינו רשאי לחתוך את הקורות ולהשתמש בהן, שכן עוברות שנים רבות עד שהאילן מצמיח קורות חדשות. ואולם אם \u0003קיבלה הימנו לשבע שנים\u0004 ויותר — ב\u0003שנה\u0004 ה\u0003ראשונה יזרענה פשתן, ויש לו בקורות שקמה.\u0004","\u0003אמר אביי:\u0004 אם קיבל ממנו את הקרקע לפחות משבע שנים \u0003בקורות שקמה\u0004 אכן \u0003אין לו,\u0004 ואולם \u0003בשבח שקמה יש לו,\u0004 כלומר, במה שהשקמה גדלה בתוך הזמן שהוא בשדה, חלק מרווח זה הוא שלו. \u0003ורבא אמר: אפילו בשבח שקמה נמי\u0004 \u0005[גם כן]\u0006 \u0003אין לו.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו בברייתא: \u0003המקבל שדה מחבירו והגיע זמנו לצאת\u0004 — \u0003שמין\u0004 (מעריכים) \u0003לו. מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה ש\u0003שמין לו בשבח שקמה,\u0004 וכדומה לו? ודוחים: \u0003לא, שמין לו ירקא וסילקא\u0004 \u0005[ירק ותרד]\u0006 שנשארו בשדה.","ושואלים: אם \u0003ירקא וסילקא\u0004 — \u0003נעקור ונשקול\u0004 \u0005[שיעקור\u0006 אותם \u0005ויקח]!\u0006 ומשיבים: מדובר \u0003ב\u0004אופן ש\u0003לא מטא יומא דשוקא\u0004 \u0005[הגיע\u0006 עדיין \u0005יום השוק]\u0006 ואם יעקרם עכשיו לא ימכרם, ועל כן משאיר אותם לבעל הקרקע, אבל מקבל תשלום עבורם.","ומנסים להביא ראיה אחרת, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 ששנינו בברייתא: \u0003המקבל שדה מחבירו והגיע שביעית\u0004 (שנת השמיטה) \u0003שמין לו\u0004 את מה שהיה בשדה. ותחילה תוהים על עצם הברייתא: שנת ה\u0003שביעית מי קא מפקעא ארעא\u0004 \u0005[האם היא מפקיעה את הקרקע]\u0006 מהמחזיק בה? ימשיך להחזיק בה כמקודם, ומה מקום לשומה? \u0003אלא אימא\u0004 \u0005[אמור]\u0006 ותקן כך: \u0003המקבל שדה מחבירו והגיע יובל\u0004 — \u0003שמין לו.\u0004","ושואלים: \u0003ואכתי\u0004 \u0005[ועדיין]\u0006 שנת ה\u0003יובל מי מפקעא\u0004 \u0005האם\u0006 היא \u0005מפקיעה\u0006 חוזה \u0003קבלנות?\u0004 והלא \u0003\"לצמיתת\" אמר רחמנא\u0004 \u0005[אמרה תורה]\u0006 בדין יובל, שקרקע שנמכרה לצמיתות חוזרת לבעלים, אבל שדה שלא נמכר לצמיתות אלא למשך זמן מסויים — אין היובל מפקיע את השדה מן המחזיק בו! \u0003אלא אימא\u0004 \u0005[אמור]\u0006 כך: \u0003הלוקח\u0004 (קונה) \u0003שדה מחבירו והגיע יובל\u0004 — \u0003שמין לו.\u0004","\u0003וכי תימא הכי נמי\u0004 \u0005[ואם תאמר גם כן]\u0006 ש\u0003שמין לו בירקא וסילקא\u0004 \u0005[בירק ותרד]?\u0006 ואולם \u0003סילקא וירקא\u0004 \u0005[תרד וירק]\u0006 \u0003ביובל הפקירא הוא\u0004 \u0005[הפקר הם],\u0006 שהרי דין היובל כשנת השמיטה שאין מגדלים דבר, וכל הגדל בשדה הפקר לכל! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 הכוונה ששמין ב\u0003שבח שקמה!\u0004 וקשה איפוא לרבא.","\u0003תרגמה,\u0004 הסביר זאת \u0003אביי אליבא\u0004 \u0005[על פי שיטתו]\u0006 של \u0003רבא\u0004 החולק עליו: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ויצא ממכר בית...\u0004 ביובל\u0003\"\u0004 (ויקרא כה, לג), \u0003ממכר\u0004 — \u0003חוזר\u0004 לבעליו, \u0003שבח\u0004 — \u0003אינו חוזר.\u0004 ושואלים: אם כן, \u0003ונגמר מיניה\u0004 \u0005[ונלמד מכך]\u0006 הלכה כללית ששבח אין מחזירים! ומשיבים: אין הדברים דומים, \u0003התם זביני מעליא\u0004 \u0005[שם מכירה מעולה,\u0006 שלימה\u0005]\u0006 היא, \u0003ויובל אפקעתא דמלכא היא\u0004 \u0005[הפקעה של מלך,\u0006 הקדוש ברוך הוא, \u0005היא],\u0006 ואין הדבר דומה כלל לחוזה קבלנות, שאינו מכירה ואין בו הפקעה.","מסופר: \u0003רב פפא קביל ארעא לאספסתא\u0004 \u0005[קיבל\u0006 בקבלנות שדה לגדל בו \u0005אספסת].\u0006 \u0003קדחו\u0004 \u0005[צמחו]\u0006 \u0003בה\u0004 בקרקע \u0003תאלי\u0004 \u0005[דקלים].\u0006 \u0003כי קא מסתלק\u0004 \u0005[כאשר הסתלק]\u0006 מן הקרקע, \u0003אמר להו\u0004 \u0005[להם]\u0006 לבעלי השדה: \u0003הבו\u0004 \u0005[תנו]\u0006 \u0003לי שבחא\u0004 \u0005[את השבח]\u0006 שהושבח השדה על ידי הדקלים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי לרב פפא: אלא מעתה\u0004 לשיטתך, \u0003דיקלא ואלים\u0004 \u0005[\u0006היה \u0005דקל ונעשה עבה],\u0006 \u0003הכי נמי דבעי מר שבחיה\u0004 \u0005[כך גם כן ירצה אדוני את שבחו]\u0006 של הדקל? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003התם לאו אדעתא דהכי נחית\u0004 \u0005[שם לא על דעת כן ירד],\u0006 כלומר, המקבל לא הביא בחשבון אלא את אכילת פירות הדקל, ולא את עצם גידולו, ואולם \u0003אנא הכא\u0004 \u0005[כאן\u0006 במקרה \u0005שלי]\u0006 \u0003אדעתא דהכי נחיתנא\u0004 \u0005[על דעת כן ירדתי]\u0006 לקבל עבור כל מה שגדל השדה.","ושואלים: \u0003כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 אמר זאת? — \u0003כ\u0004דעת \u0003אביי,\u0004 ש\u0003אמר: בשבח שקמה יש לו?\u0004 ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שסבר \u0003כ\u0004דעת \u0003רבא,\u0004 אלא \u0003התם לית ליה פסידא\u0004 \u0005[שם אין לו הפסד]\u0006 כשהשקמה גדלה לה בשדה, ואילו \u0003הכא איכא פסידא\u0004 \u0005[כאן יש הפסד],\u0006 שהרי הדקלים שצמחו ממעטים משטח הגידול של האספסת.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 הרי אף כאן יכול בעל השדה לומר \u0003מאי פסדתיך\u0004 \u0005[מה הפסדתיך]\u0006 — \u0003ידא דאספסתא\u0004 \u0005[\u0006מלוא \u0005יד\u0006 שגדלה בו \u0005אספסת],\u0006 \u0003שקול ידא דאספסתא וזיל\u0004 \u0005[קח\u0006 מלוא \u0005היד אספסת ולך]!\u0006 \u0003אמר ליה\u0004 \u0005[לו],\u0006 יכול לומר לו: \u0003אנא כורכמא רישקא רבאי\u0004 \u0005[אני כרכום הגננים גדלתי\u0006 שם\u0005],\u0006 כלומר, הפסדתי חלק מן הקרקע שיכולתי לגדל בו דברים יקרים, ולאו דווקא אספסת. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 מכל מקום הלא אתה מודה שרצית לגדל גידולים שונים בשדה, ולא לנטוע דקלים — \u0003גלית אדעתך דלמשקל ואסתלוקי עבדת\u0004 \u0005[גילית\u0006 איפוא את \u0005דעתך שעל מנת לקחת ולהסתלק עשית],\u0006 ואם כן, \u0003שקל כורכמא רישקא וזיל\u0004 \u0005[קח כרכום גננים ולך]\u0006 ומשום כך \u0003אין לך אלא דמי עצים בלבד\u0004 כיון שלא התכוונת לגדל את העצים הללו, אם כן מגיע לך רק המחיר שיכול אתה לקבל עבור אותם דקלים אילו היית עוקר אותם ומוכרם כעצים.","מסופר: \u0003רב ביבי בר אביי קביל ארעא ואהדר ליה משוניתא, קדחו ביה זרדתא\u0004 \u0005[קיבל קרקע\u0006 \u0005והקיפה\u0006 מסביב \u0005בגדר אדמה,\u0006 ובינתיים \u0005צמחו בה עצים].\u0006 \u0003כי קא מיסתלק\u0004 \u0005[כאשר הסתלק]\u0006 מן השדה \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003הבו\u0004 \u0005[תנו]\u0006 \u0003לי שבחאי\u0004 \u0005[את שבחי]\u0006 עבור העצים שגדלו. \u0003אמר רב פפי: משום דאתיתו ממולאי\u0004 \u0005[שבאתם מאנשים קצוצים]\u0006 \u0003אמריתו מילי מולייתא\u0004 \u0005[אומרים אתם דברים קצוצים]?!\u0006 כי משפחת אביי התייחסה לבית עלי שהיו מתים בקיצור ימים. והסביר לו: \u0003אפילו רב פפא לא אמר\u0004 שמגיע לו עבור שבח הדקלים \u0003אלא דאית ליה פסידא\u0004 \u0005[כשיש לו הפסד],\u0006 שהרי צמחו הדקלים בתוך השדה ומיעטו ממנו, ואולם \u0003הכא מאי פסידא אית\u0004 \u0005[מה הפסד יש]\u0006 \u0003לך,\u0004 שהרי גדלו העצים במקום שאין זורעים בו, וכיון שלא הפסדת דבר — אין ראוי לך לקבל.","מסופר: \u0003רב יוסף הוה ליה ההוא שתלא\u0004 \u0005[היה לו שתלן],\u0006 איש שהיתה אומנותו לשתול עצים, שהיה כאריס אצלו, \u0003שכיב ושבק\u0004 \u0005[מת והניח]\u0006 \u0003חמשה חתנוותא\u0004 \u0005[חתנים].\u0006 \u0003אמר\u0004 רב יוסף: \u0003עד האידנא\u0004 \u0005[עכשיו]\u0006 היה לי עסק רק עם \u0003חד\u0004 \u0005[אחד],\u0006 \u0003השתא\u0004 \u0005[\u0006ו\u0005עכשיו]\u0006 עם \u0003חמשה.\u0004 \u0003עד האידנא\u0004 \u0005[עכשיו]\u0006 \u0003לא הוו סמכו אהדדי\u0004 \u0005[היו סומכים זה על זה]\u0006 \u0003ולא מפסדו\u0004 \u0005[היו מפסידים]\u0006 \u0003לי,\u0004 שהאחריות היתה על החותן, \u0003השתא\u0004 \u0005[עכשיו]\u0006 ש\u0003חמשה\u0004 הם \u0003סמכו אהדדי ומפסדו\u0004 \u0005[יסמכו זה על זה ויפסידו]\u0006 \u0003לי,\u0004 ומשום כך החליט שאין רצונו בהמשך ההסכם עמם. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אי שקליתו שבחייכו ומסתלקיתו\u0004 \u0005[אם תקחו את שבחכם\u0006 שהשבחתם בעבודתכם \u0005ותסתלקו]\u0006 — \u0003מוטב, ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003מסליקנא לכו\u0004 \u0005[אסלק אתכם]\u0006 \u0003בלא שבחא\u0004 \u0005[שבח].\u0006","ש\u0003אמר רב יהודה, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב הונא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב נחמן: האי שתלא דשכיב\u0004 \u0005[שתלן שמת]\u0006 — ה\u0003יורשים דיליה\u0004 \u0005[שלו]\u0006 \u0003מסתלקין להו\u0004 \u0005[להם]\u0006 \u0003בלא שבחא\u0004 \u0005[שבח].\u0006 ומעירים: \u0003ולאו מילתא היא\u0004 \u0005[ואין זה דבר],\u0006 כלומר, אין הלכה כן.","מסופר: \u0003ההוא שתלא\u0004 \u0005[אותו שתלן]\u0006 ש\u0003אמר להו\u0004 \u0005[להם]\u0006 לאותם ששכרו אותו לשתול עצים בקרקעותיהם: \u0003אי מפסדינא מסלקנא\u0004 \u0005[אם אפסיד\u0006 בכרם ואקלקל בנטיעות \u0005הרי\u0006 \u0005אני מסתלק\u0006 מן השדה\u0005].\u0006 ואכן \u0003אפסיד\u0004 \u0005[הפסיד].\u0006 \u0003אמר רב יהודה:\u0004 הריהו \u0003מסתלק\u0004 מן השדה \u0003בלא שבחא\u0004 \u0005[שבח].\u0006 \u0003רב כהנא אמר:\u0004 הריהו \u0003מסתלק ושקיל שבחא\u0004 \u0005[ונוטל שבח]\u0006 שהשביח בעבודתו. \u0003ומודה רב כהנא דאי\u0004 \u0005[שאם]\u0006 \u0003אמר אי פסידנא מסתלקנא\u0004 \u0005[אם אני אפסדי הריני מסתלק]\u0006 מן השדה \u0003בלא שבחא\u0004 \u0005[שבח],\u0006 שאכן הוא \u0003מסתלק בלא שבחא\u0004 \u0005[שבח].\u0006 ואילו \u0003רבא אמר:\u0004 תנאי כגון זה \u0003אסמכתא היא ו\u0004כלל הוא ש\u0003אסמכתא לא קניא\u0004 \u0005[אינה קונה],\u0006 כלומר, אין בה תוקף ואין חובה לקיים הבטחה כגון זו.","ושואלים: \u0003ולרבא מאי שנא מהא דתנן\u0004 \u0005[מה שונה\u0006 הדבר \u0005מזה ששנינו\u0006 במשנה\u0005]\u0006 שמתנה מקבל־השדה: \u0003אם אוביר\u0004 את השדה \u0003ולא אעביד\u0004 \u0005[אעבוד\u0006 בו\u0005]\u0006 \u0003אשלם במיטבא\u0004 \u0005[במיטב]!\u0006 ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 — \u0003מאי דאפסיד\u0004 \u0005[מה שהפסיד]\u0006 הוא \u0003משלם,\u0004 \u0003הכא, מאי דאפסיד\u0004 \u0005[כאן, מה שהפסיד]\u0006 — \u0003מנכינן ליה ואידך יהבינן ליה\u0004 \u0005[מנכים לו, ואת השאר נותנים לו],\u0006 אבל אין ראוי שיפסיד הכל משום שגרם הפסד לחלק מן הנטיעות.","מסופר, אדם בשם \u0003רוניא שתלא\u0004 \u0005[שתלן]\u0006 של \u0003רבינא הוה\u0004 \u0005[היה],\u0006 \u0003אפסיד, סלקיה\u0004 \u0005[והפסיד, וסילק אותו]\u0006 מן השדה. \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רבא\u0004 לדין. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רוניא לרבא: \u0003חזי מר מאי קא עביד לי\u0004 \u0005[יראה אדוני מה שעשה לי]\u0006 רבינא! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003שפיר עביד\u0004 \u0005[יפה עשה]\u0006 שהרי הפסדת לו. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לא\u0004 \u0003התרה בי\u0004 מראש, וכיון שלא התרה בי — לא היה לו לסלקני! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא צריכא\u0004 \u0005[צריך]\u0006 להתרות במקרה כזה. ומעירים, \u0003רבא לטעמיה\u0004 \u0005[לטעמו\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר רבא: מקרי דרדקי\u0004 \u0005[מלמד תינוקות],\u0006 \u0003שתלא\u0004 \u0005[שתלן],\u0006 \u0003טבחא\u0004 \u0005[שוחט],\u0006 \u0003ואומנא\u0004 \u0005[מקיז דם]\u0006"],["\u0003וספר מתא\u0004 \u0005[וסופר העיר],\u0006 הלבלר הכותב שטרות עבור אנשי העיר — \u0003כולן כמותרין ועומדין דמי\u0004 \u0005[\u0006הם \u0005נחשבים],\u0006 וכל הפסד שהם עושים מנכים להם, וקונסים אותם, ואין צורך להתרות בהם מראש. \u0003כללא דמילתא\u0004 \u0005[כללו של דבר]:\u0006 ביחס ל\u0003כל פסידא דלא הדר\u0004 \u0005[הפסד שאינו חוזר]\u0006 — \u0003כמותרין ועומדין דמי\u0004 \u0005[\u0006הם \u0005נחשבים].\u0006","מסופר: \u0003ההוא שתלא\u0004 \u0005[אותו שתלן]\u0006 ש\u0003אמר להו,\u0004 לבעלי השדה: \u0003הבו\u0004 \u0005[תנו]\u0006 \u0003לי שבחאי\u0004 \u0005[\u0006את \u0005השבח\u0006 המגיע \u0005לי]\u0006 משום \u0003דבעינא למיסק לארעא דישראל\u0004 \u0005[שרוצה אני לעלות לארץ ישראל].\u0006 \u0003אתא לקמיה\u0004 \u0005[בא\u0006 הדבר \u0005לפני]\u0006 \u0003רב פפא בר שמואל. אמר להו\u0004 \u0005[להם],\u0006 לבעלי השדה: \u0003הבו ליה שבחיה\u0004 \u0005[תנו לו את שבחו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא:\u0004 וכי \u0003איהו אשבח\u0004 \u0005[הוא השביח]\u0006 את השדה ואילו \u0003ארעא\u0004 \u0005[הקרקע]\u0006 \u0003לא אשבח\u0004 \u0005[השביחה]?\u0006 ואם כן לא כל השבח שלו! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא פלגא דשבחא קאמינא\u0004 \u0005[אני חצי השבח אמרתי]\u0006 \u0003לך\u0004 שיקבל. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003עד האידנא הוה שקיל\u0004 \u0005[עכשיו היה לוקח]\u0006 \u0003בעל הבית פלגא ושתלא פלגא\u0004 \u0005[חצי והשותל חצי],\u0006 והשתלן היה גם מעבד את השדה. \u0003השתא בעי למיתב מנתא לאריסא\u0004 \u0005[עכשיו\u0006 הוא \u0005צריך לתת חלק\u0006 גם \u0005לאריס]\u0006 שימשיך לעבד את השדה! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ריבעא דשבחא קאמינא\u0004 \u0005[רבע השבח אני אומר]\u0006 שהוא חצי ממה שמגיע לו.","\u0003סבר\u0004 \u0005[חשב]\u0006 \u0003רב אשי למימר\u0004 \u0005[לומר]\u0006 שמה שאמרו \"רבע\" כוונתו \u0003ריבעא\u0004 \u0005[רבע]\u0006 ש\u0003הוא דנקא\u0004 \u0005[ששית],\u0006 כלומר, רבע מן הסכום המגיע לבעל הבית (שהוא שני שליש מסך כל היבול) והוא איפוא שישית מן הכל. שכן \u0003אמר רב מניומי בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחומי: באתרא דשקיל שתלא פלגא ואריסא תילתא\u0004 \u0005[במקום שנוטל השתלן חצי\u0006 פירות \u0005והאריס\u0006 נוטל \u0005שליש],\u0006 \u0003האי שתלא דבעי לאסתלוקי\u0004 \u0005[אותו שתלן שרוצה להסתלק]\u0006 — \u0003יהבינן ליה שבחא ומסלקינן ליה כי היכי\u0004 \u0005[נותנים לו את השבח ומסלקים אותו באופן]\u0006 ש\u0003לא נמטייה\u0004 \u0005[יבוא]\u0006 \u0003הפסד לבעל הבית.\u0004","\u0003אי אמרת בשלמא ריבעא דהוא דנקא\u0004 \u0005[נניח אם אומר אתה רבע שהוא ששית]\u0006 — \u0003שפיר\u0004 \u0005[יפה]\u0006 ומתאימים הדברים, \u0003אלא אי אמרת ריבעא\u0004 \u0005[אם אומר אתה רבע\u0006 ממש\u0005],\u0006 הלא \u0003קא מטי ליה פסידא\u0004 \u0005[מגיע לו הפסד]\u0006 \u0003לבעל הבית פלגא דנקא\u0004 \u0005[\u0006ב\u0005חצי שישית],\u0006 שאילו היה בעל הבית נותן לשתלן מתחילה היה משלם רק מחצית, וכאן משלם רבע לשתלן ושליש לאריס. ונמצא שמשלם חצי שישית יתירה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף לרב אשי, ולימא ליה\u0004 \u0005[ושיאמר לו]\u0006 השתלן לבעל הבית: \u0003אנת מנתא די\u0004 \u0003לך\u0004 \u0005[אתה את החלק שלך]\u0006 — \u0003הב ליה לאריסא\u0004 \u0005[תן לו לאריס],\u0006 \u0003ואנא מנתא דילי מאי דבעינא עבידנא ביה\u0004 \u0005[ואני בחלק שלי מה שאני רוצה אעשה בו],\u0006 שהרי אני עשיתי חצי מלאכתי כראוי, ואם רצונך למסור לאריס חלק האם אני צריך להפסיד? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כי מטית\u0004 \u0005[כאשר נגיע]\u0006 \u0003ל\u0004מסכת \u0003\"שחיטת קדשים\",\u0004 מסכת זבחים, \u0003תא ואקשי\u0004 \u0005[בוא והקשה]\u0006 \u0003לי,\u0004 כלומר, יפה אתה מקשה, וקושיה כזו ראויה למסכת קשה שיש בה סברות חריפות כמו מסכת זבחים.","\u0003גופא,\u0004 \u0005[לגופה]\u0006 של אותה הלכה, \u0003אמר רב מניומי בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחומי: באתרא דשקיל שתלא פלגא ואריסא תילתא\u0004 \u0005[במקום שהשתלן נוטל חצי והאריס שליש],\u0006 \u0003האי שתלא דבעי איסתלוקי\u0004 \u0005[שתלן שרוצה להסתלק]\u0006 — \u0003יהבינן ליה שבחיה ומסלקינן ליה כי היכי\u0004 \u0005[נותנים לו\u0006 את \u0005שבחו ומסלקים אותו כדי]\u0006 ש\u0003לא ליפסוד\u0004 \u0005[יפסיד]\u0006 \u0003בעל הבית.\u0004 \u0003אמר רב מניומי בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחומי: קופא סבא\u0004 \u0005[בגפן זקנה]\u0006 בכרם — מקבל השתלן \u0003פלגא\u0004 \u0005[חצי].\u0006 למרות שבגפן זו לא טרח השתלן בשתילה, כיון שירד לכרם כולו מקבל גם עבור מה שהיה בו קודם. \u0003שטפה נהרא\u0004 \u0005[שטף הנהר]\u0006 את הכרם ובאים הבעלים והשתלן לחלק את העצים שנפלו — השתלן מקבל \u0003ריבעא\u0004 \u0005[רבע].\u0006","מסופר: \u0003ההוא גברא דמשכין פרדיסא לחבריה\u0004 \u0005[אדם אחד מישכן פרדס לחבירו]\u0006 \u0003לעשר שנין\u0004 \u0005[שנים],\u0006 ומרווחי הפרדס ינכה לו מן ההלוואה שהלווהו, \u0003וקש\u0004 \u0005[והזקין]\u0006 השדה כבר \u0003לחמש שנין\u0004 \u0005[שנים],\u0006 ושוב אינו עושה פירות כראוי, ואין דרך אלא לעקור האילנות שבו ולמכרם במחיר עצים. \u0003אביי אמר: פירא הוי\u0004 \u0005[פרי הוא],\u0006 שאף עצים אלה נחשבים כפירות הפרדס, ויכול המלווה לקחתם כולם. \u0003רבא אמר:\u0004 העצים הללו \u0003קרנא הוי\u0004 \u0005[קרן הם],\u0006 שדינם כפרדס עצמו, ואין למלוה זכות בגופם, אלא \u0003וילקח בו\u0004 במחיר העצים \u0003קרקע, והוא\u0004 המלוה \u0003אוכל פירות.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו בברייתא העוסקת בדין משכנתא: \u0003יבש האילן או נקצץ\u0004 — \u0003שניהם,\u0004 גם המלווה וגם הלווה \u0003אסורים בו. כיצד יעשו? ימכרו לעצים, וילקח\u0004 (תיקנה) \u0003בהן קרקע, והוא,\u0004 המלוה, \u0003אוכל פירות. מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן במקרה של \u0003יבש דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003נקצץ, מה נקצץ\u0004 — \u0003בזמנו, אף יבש\u0004 — \u0003בזמנו, וקתני\u0004 \u0005[ושנה]:\u0006 \u0003ילקח בהן קרקע והוא אוכל פירות. אלמא\u0004 \u0005[מכאן]:\u0006 שהעצים \u0003קרנא הוי\u0004 \u0005[הם\u0006 נחשבים \u0005לקרן]\u0006 ולא לרווח. וכדברי רבא, וקשה לאביי!","ודוחים: \u0003לא, נקצץ\u0004 האמור שם \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003יבש,\u0004 \u0003מה יבש\u0004 כוונתו \u0003בלא זמנו, אף נקצץ\u0004 — \u0003בלא זמנו.\u0004 וכיון שלא היה זה כדרכו לכן נחשב כפרי, אבל אם יבש הפרדס בזמנו נחשבים האילנות כגוף הקרקע.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממקור אחר: \u0003נפלו לה\u0004 לאשה אחרי שהתחתנה \u0003גפנים וזיתים זקנים\u0004 בירושה, מה יעשו בהם —"]]};
